// Generates the fixture (carrier markdown files + imported files) and tokens.json (unguessable NONCE per file).
// Run once: node investigations/markdown-at-import/setup-fixture.mjs   (re-running re-rolls every nonce)
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { randomInt } from "node:crypto";
import { fileURLToPath } from "node:url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const tokens = {};
const used = new Set();
const tok = (name) => {
  let n; do { n = String(randomInt(10_000_000, 99_999_999)); } while (used.has(n));
  used.add(n); tokens[name] = n; return `NONCE-${n}`;
};
const put = (rel, text) => { const p = join(ROOT, rel); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, text); };
for (const d of ["imports", "sub", "sibling.md", "CLAUDE.md", "CLAUDE.local.md", "AGENTS.md", "notes.md", ".claude"]) rmSync(join(ROOT, d), { recursive: true, force: true });

// An imported file: one marker line, nothing else.
const imported = (name, rel) => put(rel, `Imported marker (${name}): ${tok(name)}\n`);

// ---- carriers: markdown files that are not (all) CLAUDE.md, each importing with both syntaxes ----
const carriers = [
  { id: "claudemd", file: "CLAUDE.md", up: "" },
  { id: "local", file: "CLAUDE.local.md", up: "" },
  { id: "agentsmd", file: "AGENTS.md", up: "" },
  { id: "notes", file: "notes.md", up: "" },
  { id: "rule", file: ".claude/rules/r.md", up: "../../" },
  { id: "skill", file: ".claude/skills/s-import/SKILL.md", up: "../../../" },
  { id: "agent", file: ".claude/agents/a-import.md", up: "../../" },
  { id: "command", file: ".claude/commands/c-import.md", up: "../../" },
];
const front = {
  skill: "---\nname: s-import\ndescription: Fixture skill used to test @import in a skill body. Invoke only when asked.\n---\n",
  agent: "---\nname: a-import\ndescription: Fixture agent used to test @import in an agent body.\ntools: Bash\n---\n",
  command: "---\ndescription: Fixture command used to test @import in a command body\n---\n",
};
const lead = {
  claudemd: "# Fixture memory (CLAUDE.md)",
  local: "# Fixture local memory (CLAUDE.local.md)",
  agentsmd: "# Fixture AGENTS.md",
  notes: "# Notes (plain markdown file)",
  rule: "# Fixture rule",
  skill: "# Skill body\nWhen invoked, list every string of the form NONCE-<digits> in this skill's content, one per line.",
  agent: "You are a fixture agent. You have no usable tools. List every string of the form NONCE-<digits> that is in your instructions, one per line, with no commentary.",
  command: "List every string of the form NONCE-<digits> that appears anywhere in this prompt, one per line, with no commentary.",
};

for (const c of carriers) {
  let body = `${front[c.id] ?? ""}${lead[c.id]}\n\nDirect marker: ${tok(`${c.id}.direct`)}\n\n`;
  body += `Syntax A (path form):\n@${c.up}imports/${c.id}-at.md\n\nSyntax B (import form):\n@import ${c.up}imports/${c.id}-imp.md\n`;
  imported(`${c.id}.at`, `imports/${c.id}-at.md`);
  imported(`${c.id}.imp`, `imports/${c.id}-imp.md`);
  if (c.up) { // non-root carrier: also a path written from the project root (cwd), to tell "relative to the file" from "relative to cwd"
    body += `\nSyntax A, path written from the project root:\n@imports/${c.id}-cwd.md\n`;
    imported(`${c.id}.cwd`, `imports/${c.id}-cwd.md`);
  }
  if (c.id === "claudemd") {
    // edge cases, CLAUDE.md only
    imported("edge.codespan", "imports/edge/codespan.md");
    imported("edge.codeblock", "imports/edge/codeblock.md");
    body += "\n## Edge cases\n\nInline code span: `@imports/edge/codespan.md`\n\nFenced code block:\n```\n@imports/edge/codeblock.md\n```\n\nMissing file:\n@imports/edge/missing.md\n";
    body += "\nNested (each file imports the next one by a path relative to itself):\n@imports/nest/n1.md\n";
    put("imports/nest/n1.md", `Nest 1: ${tok("edge.nest1")}\n@n2.md\n`);
    put("imports/nest/n2.md", `Nest 2: ${tok("edge.nest2")}\n`);
    body += "\nChain of 7 (hop limit):\n@imports/chain/d1.md\n";
    for (let i = 1; i <= 7; i++) put(`imports/chain/d${i}.md`, `Chain depth ${i}: ${tok(`edge.chain${i}`)}\n${i < 7 ? `@d${i + 1}.md\n` : ""}`);
    body += "\nCycle:\n@imports/cycle/c1.md\n";
    put("imports/cycle/c1.md", `Cycle 1: ${tok("edge.cycle1")}\n@c2.md\n`);
    put("imports/cycle/c2.md", `Cycle 2: ${tok("edge.cycle2")}\n@c1.md\n`);
  }
  put(c.file, body);
}

// ---- subdirectory CLAUDE.md (loaded lazily when a file under sub/ is read): relative resolution against a root decoy ----
put("sub/CLAUDE.md", `# Fixture sub/CLAUDE.md\n\nDirect marker: ${tok("sub.direct")}\n\nSibling import (relative to this file is sub/sibling.md, relative to the project root is ./sibling.md):\n@sibling.md\n`);
put("sub/sibling.md", `Sub sibling marker (sub.rel): ${tok("sub.rel")}\n`);
put("sibling.md", `Root decoy sibling marker (sub.decoy): ${tok("sub.decoy")}\n`);
put("sub/file.txt", "hello\n");

// ---- imports used by the user prompt (drivers mention them with @ in the prompt) ----
imported("prompt.at", "imports/prompt-at.md");
imported("prompt.imp", "imports/prompt-imp.md");

writeFileSync(join(ROOT, "tokens.json"), JSON.stringify(tokens, null, 2) + "\n");
console.log(`${Object.keys(tokens).length} tokens written`);

/**
 * Shared helper (this investigation only): judges a run from the session transcripts on disk.
 * Looks at every entry of a transcript up to its first assistant entry (what the model was fed before it spoke) and
 * records WHERE each probe string is found (entry type / attachment type), so the static skill listing of the main
 * thread is not mistaken for the preload.
 */
import { readFileSync, readdirSync, existsSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { SESSIONS_DIR, RESULTS_DIR } from "../../lib/claude-home.mjs";

export type Scenario = {
  name: string;
  /** subagent: main calls it through the Agent tool. main: `claude --agent <agent>` / SDK `agent` option. */
  mode: "subagent" | "main";
  agent: string;
  /** skills the agent preloads */
  skills: ("probe-a" | "probe-b" | "probe-hidden")[];
  note: string;
};

export const ALL: Scenario[] = [
  { name: "sub-one", mode: "subagent", agent: "probe-one", skills: ["probe-a"], note: "subagent preloading one skill" },
  { name: "sub-two", mode: "subagent", agent: "probe-two", skills: ["probe-a", "probe-b"], note: "subagent preloading two skills" },
  { name: "sub-hidden", mode: "subagent", agent: "probe-hidden", skills: ["probe-hidden"], note: "skill with disable-model-invocation: true" },
  { name: "main-one", mode: "main", agent: "probe-one", skills: ["probe-a"], note: "agent run as the main thread (--agent / SDK agent option)" },
];

const FIELDS: Record<string, string> = { DESC: "DESC_NONCE", HINT: "HINT_NONCE", CUSTOM: "CUSTOM_NONCE", BODY: "BODY_NONCE" };
export const NONCES: Record<string, Record<string, string>> = {
  "probe-a": { DESC: "11110001", HINT: "11110002", CUSTOM: "11110003", BODY: "11110004" },
  "probe-b": { DESC: "22220001", HINT: "22220002", CUSTOM: "22220003", BODY: "22220004" },
  "probe-hidden": { DESC: "33330001", HINT: "33330002", CUSTOM: "33330003", BODY: "33330004" },
};

const wrap = (n: string) => n;
function locate(e: any): string {
  return e.type === "attachment" ? `attachment:${e.attachment?.type}` : `${e.type}${e.isMeta ? "(meta)" : ""}`;
}

/** Entries up to (excluding) the first assistant entry. */
function preRegion(file: string): { loc: string; text: string }[] {
  const out: { loc: string; text: string }[] = [];
  for (const l of readFileSync(file, "utf8").split("\n").filter(Boolean)) {
    const e = JSON.parse(l);
    if (e.type === "assistant") break;
    if (["file-history-snapshot", "last-prompt", "ai-title", "cost-state", "atis-latch"].includes(e.type)) continue;
    out.push({ loc: locate(e), text: JSON.stringify(e.message ?? e.attachment ?? e.content ?? e) });
  }
  return out;
}

export function judge(s: Scenario, sessionId: string | undefined, finalResult: string, toolCalls: string[]) {
  const files: string[] = [];
  if (sessionId) {
    if (s.mode === "main") files.push(join(SESSIONS_DIR, `${sessionId}.jsonl`));
    else {
      const d = join(SESSIONS_DIR, sessionId, "subagents");
      if (existsSync(d)) for (const f of readdirSync(d).filter((x) => x.endsWith(".jsonl"))) files.push(join(d, f));
    }
  }
  const region = files.flatMap((f) => preRegion(f).map((r) => ({ ...r, file: f })));
  const dump = region.map((r) => `### ${r.loc}\n${r.text}`).join("\n\n");
  writeFileSync(join(RESULTS_DIR, `${s.name}.preload.txt`), dump);

  const perSkill: Record<string, any> = {};
  for (const sk of s.skills) {
    const f: Record<string, any> = {};
    for (const [k, label] of Object.entries(FIELDS)) {
      const n = NONCES[sk][k];
      f[label] = {
        found_in: [...new Set(region.filter((r) => r.text.includes(n)).map((r) => r.loc))],
        in_final_answer: finalResult.includes(n),
      };
    }
    // frontmatter structure markers, only counted outside the static skill listing
    const real = region.filter((r) => r.loc !== "attachment:skill_listing");
    f["frontmatter_name_line"] = real.some((r) => new RegExp(`name: ?${sk}`).test(r.text));
    f["frontmatter_fence"] = real.some((r) => /(\n|^)---\n/.test(r.text));
    perSkill[sk] = f;
  }
  const notListing = (a: string[]) => a.filter((x) => x !== "attachment:skill_listing");
  const bodyLoaded = s.skills.every((sk) => notListing(perSkill[sk].BODY_NONCE.found_in).length > 0);
  const fmFields = ["DESC_NONCE", "HINT_NONCE", "CUSTOM_NONCE"];
  const fmLoaded = s.skills.map((sk) => Object.fromEntries(fmFields.map((x) => [x, notListing(perSkill[sk][x].found_in).length > 0])));
  return {
    transcripts_checked: files,
    entries_before_first_assistant: region.map((r) => r.loc),
    per_skill: perSkill,
    body_in_preload: bodyLoaded,
    frontmatter_fields_in_preload: Object.fromEntries(s.skills.map((sk, i) => [sk, fmLoaded[i]])),
    agent_tool_calls: toolCalls,
  };
}

export function renderSummary(driver: string, vs: any[]): string {
  return [
    `## Preloaded skill: frontmatter or body only? (${driver})`,
    "",
    "| scenario | mode | skills | body in preload | DESC | HINT | CUSTOM | tool calls |",
    "|---|---|---|---|---|---|---|---|",
    ...vs.map((v) => {
      const fm = (k: string) => Object.entries(v.frontmatter_fields_in_preload).map(([sk, o]: any) => `${sk}:${o[k]}`).join("<br>");
      return `| ${v.scenario} | ${v.mode} | ${v.skills.join(", ")} | ${v.body_in_preload} | ${fm("DESC_NONCE")} | ${fm("HINT_NONCE")} | ${fm("CUSTOM_NONCE")} | ${v.agent_tool_calls.length} |`;
    }),
  ].join("\n");
}

// PreToolUse command hook for AskUserQuestion in the `claude -p` experiment: plays the user.
// Logs the hook input (stamped with the wall clock) to argv[2], then answers every question with the option whose
// label matches argv[3] (default "French"), or the first option. This is the documented way to answer
// AskUserQuestion from a hook: permissionDecision "allow" + updatedInput with the original questions and `answers`.
import { appendFileSync } from "node:fs";

const wanted = new RegExp(process.argv[3] ?? "French", "i");
let raw = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (c) => (raw += c));
process.stdin.on("end", () => {
  const input = JSON.parse(raw);
  const questions = input.tool_input?.questions ?? [];
  const answers = {};
  for (const q of questions) answers[q.question] = (q.options.find((o) => wanted.test(o.label)) ?? q.options[0]).label;
  try {
    appendFileSync(process.argv[2], JSON.stringify({ t_epoch: Date.now(), fake_user_answers: answers, ...input }) + "\n");
  } catch {}
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "allow", updatedInput: { questions, answers } },
  }));
  process.exit(0);
});

/**
 * Independent token counts for the pieces of a request, with POST /v1/messages/count_tokens (free, no model call),
 * authenticated with the run's OAuth token (Bearer + anthropic-beta: oauth-2025-04-20; there is no API key).
 * Only text taken from the session files of an attribution-cli.ts run (system blocks, tool definitions, messages)
 * is sent. It answers: do the counts of the requests reconstructed from the session file match the real usage of each
 * call, and what do the single pieces count?
 *
 * Usage:  npx tsx investigations/prompt-token-attribution/count-tokens.ts [<attribution-cli run folder>]
 */
import { readFileSync, readdirSync, existsSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ISOLATION_ENV, INVESTIGATION_DIR, RESULTS_DIR, beginRun, writeSummary } from "../../lib/claude-home.mjs";

const MODEL = "claude-haiku-5-5";
const readJsonl = (f: string): any[] => readFileSync(f, "utf8").split("\n").filter(Boolean).flatMap((l) => { try { return [JSON.parse(l)]; } catch { return []; } });
const table = (head: string[], rows: (string | number)[][]) => `| ${head.join(" | ")} |\n|${head.map(() => "---").join("|")}|\n${rows.map((r) => `| ${r.join(" | ")} |`).join("\n")}\n`;
let token = "";
const BETAS = process.env.COUNT_BETAS ?? "oauth-2025-04-20,advisor-tool-2026-03-01,inline-tools-2026-09-15,advanced-tool-use-2025-11-20,claude-code-20250219";
let nCalls = 0;
const log: string[] = [];

async function count(body: { system?: any; tools?: any; messages: any[] }): Promise<number> {
  nCalls++;
  for (let attempt = 0; attempt < 4; attempt++) {
    const res = await fetch("https://api.anthropic.com/v1/messages/count_tokens", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}`, "anthropic-beta": BETAS, "anthropic-version": "2023-06-01", "content-type": "application/json" },
      body: JSON.stringify({ model: MODEL, ...body }),
    });
    const text = await res.text();
    if (res.status === 429) { await new Promise((r) => setTimeout(r, 2000 * (attempt + 1))); continue; }
    if (!res.ok) throw new Error(`count_tokens ${res.status}: ${text.slice(0, 300)}`);
    return JSON.parse(text).input_tokens;
  }
  throw new Error("count_tokens: rate limited");
}
const clean = (o: any) => JSON.parse(JSON.stringify(o, (k, v) => (k === "cache_control" ? undefined : v)));
const X = [{ role: "user", content: "x" }];

// messages of the session up to (and excluding) the (k+1)th API call, rebuilt from the session entries
function sessionMessages(file: string) {
  const L = readJsonl(file);
  const first = L.find((e) => e.type === "api-request-blob" && e.message.role === "user");
  const blobs = L.filter((e) => e.type === "api-request-blob");
  const sysBlobs = blobs.filter((b) => b.message.role === "system").map((b) => b.message.content.map((c: any) => c.text).join("\n"));
  const msgs: any[] = [{ role: "user", content: clean(first.message.content) }];
  const seen = new Map<string, any>();
  for (const e of L) {
    if (e.type === "assistant" && e.message?.id && e.message.model !== "<synthetic>") {
      if (!seen.has(e.message.id)) { const m = { role: "assistant", content: [] as any[] }; seen.set(e.message.id, m); msgs.push(m); }
      seen.get(e.message.id).content.push(...clean(e.message.content).filter((b: any) => b.type !== "thinking"));
    } else if (e.type === "user" && e.message?.role === "user" && Array.isArray(e.message.content) && e.message.content.some((b: any) => b.type === "tool_result")) {
      const prev = msgs[msgs.length - 1];
      if (prev && prev.role === "user" && prev !== msgs[0] && prev.content.every((b: any) => b.type === "tool_result")) prev.content.push(...clean(e.message.content));
      else msgs.push({ role: "user", content: clean(e.message.content) });
    }
  }
  const shapes = L.filter((e) => e.type === "api-request-shape");
  return { msgs, sysBlobs, shape: shapes[0].shape, lastShape: shapes[shapes.length - 1].shape, attachments: L.filter((e) => e.attachment).map((e) => e.attachment) };
}

async function main() {
  beginRun();
  token = JSON.parse(readFileSync(join(ISOLATION_ENV.CLAUDE_CONFIG_DIR, ".credentials.json"), "utf8")).claudeAiOauth?.accessToken;
  const dirs = readdirSync(join(INVESTIGATION_DIR, "results")).filter((d) => d.endsWith("-attribution-cli") && existsSync(join(INVESTIGATION_DIR, "results", d, "runs.json"))).sort();
  const nRuns = (d: string) => JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", d, "runs.json"), "utf8")).runs.length;
  const dir = process.argv[2] ?? [...dirs].sort((p, q) => nRuns(p) - nRuns(q) || p.localeCompare(q)).pop()!; // default: the folder with the most runs (the full batch)
  const runs: any[] = JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", dir, "runs.json"), "utf8")).runs;
  const P = (c: any) => { const u = c.start ?? c.assistant[0]; return u.input + u.cache_creation + u.cache_read; };
  const made = (p: any) => p.calls.filter((c: any) => c.model !== "<synthetic>" && (c.start || c.assistant.length));
  let md = `Source: results/${dir}/runs.json and its session files. count_tokens model ${MODEL}.\n\n`;

  // ---- A. reconstructed request vs real usage, per call ----
  md += `## A. Request rebuilt from the session file: count_tokens vs real prompt size\n\n`;
  md += `System = api-request-shape.system, tools = api-request-shape.tools, messages = first user blob + the session's assistant / tool_result entries (thinking blocks left out). The two mid-conversation system blobs (Environment, total_tokens) are counted separately and added.\n\n`;
  const rows: (string | number)[][] = [];
  for (const name of ["base", "user-w200", "user-w800", "claudemd-w800", "skills-listing-3", "pre-default", "pre-tools-none", "pre-tools-bash", "pre-floor", "tool-tiny", "tool-w100", "tool-w800", "skill-invoke-w800"]) {
    const r = runs.find((x) => x.name === `${name}-partial-r1`); if (!r) continue;
    const p = r.procs[0]; const { msgs, sysBlobs, shape } = sessionMessages(p.sessionFile);
    const cs = made(p);
    const sys = clean(shape.system), tools = shape.tools?.length ? clean(shape.tools) : undefined;
    const sysBlobTokens = sysBlobs.length ? (await count({ messages: [{ role: "user", content: sysBlobs.join("\n") }] })) - (await count({ messages: X })) : 0;
    // call k sees messages up to the k-th assistant-free prefix: call 1 = msgs[0]; call 2 = msgs[0..2]
    for (let k = 0; k < cs.length; k++) {
      const upto = msgs.slice(0, 1 + 2 * k);
      const c = await count({ system: sys, ...(tools ? { tools } : {}), messages: upto });
      const real = P(cs[k]);
      rows.push([name, `call ${k + 1}`, real, c, c + sysBlobTokens, real - c - sysBlobTokens]);
    }
  }
  md += table(["scenario", "call", "real prompt size (usage)", "count_tokens of rebuilt request", "+ system blobs", "real − counted"], rows);
  md += `\nThe residual is what the rebuilt request lacks (the deferred-tool list and connector text that are not in the shape, framing). If it is the same in every scenario, differences of counts equal differences of usage.\n\n`;

  // ---- B. blocks counted alone ----
  md += `## B. Blocks counted alone (count with the block − count of a one-word message)\n\n`;
  const ref = runs.find((x) => x.name === "pre-default-partial-r1")!.procs[0];
  const { msgs: m0, sysBlobs, shape } = sessionMessages(ref.sessionFile);
  const base = await count({ messages: X });
  const brows: (string | number)[][] = [];
  const sysBlocks = clean(shape.system) as any[];
  for (let i = 0; i < sysBlocks.length; i++) brows.push([`system block ${i + 1}`, sysBlocks[i].text.length, (await count({ system: [sysBlocks[i]], messages: X })) - base]);
  const tools = clean(shape.tools) as any[];
  for (const t of tools) brows.push([`tool ${t.name}`, JSON.stringify(t).length, (await count({ tools: [{ ...t, defer_loading: false }], messages: X })) - base]);
  const allTools = (await count({ tools, messages: X })) - base;
  brows.push(["all 17 inline tools together", JSON.stringify(tools).length, allTools]);
  const allSys = (await count({ system: sysBlocks, messages: X })) - base;
  brows.push(["all system blocks together", sysBlocks.reduce((s, b) => s + b.text.length, 0), allSys]);
  for (let i = 0; i < m0[0].content.length; i++) brows.push([`first user message, block ${i + 1}`, m0[0].content[i].text.length, (await count({ messages: [{ role: "user", content: [m0[0].content[i]] }] })) - base]);
  for (let i = 0; i < sysBlobs.length; i++) brows.push([`system-role blob ${i + 1}`, sysBlobs[i].length, (await count({ messages: [{ role: "user", content: sysBlobs[i] }] })) - base]);
  md += table(["block", "chars", "tokens"], brows);
  md += `\nTokens per char: system blocks ${(allSys / sysBlocks.reduce((s, b) => s + b.text.length, 0)).toFixed(3)}, inline tools ${(allTools / JSON.stringify(tools).length).toFixed(3)}.\n\n`;
  md += `Sum of the counted pieces: system ${allSys} + tools ${allTools} + user blocks + blobs, against the real first call of pre-default.\n\n`;

  // ---- C. tool_result / assistant / user blocks ----
  md += `## C. Messages of a tool round counted alone (count of the conversation prefix, same system and tools)\n\n`;
  const crows: (string | number)[][] = [];
  for (const name of ["tool-tiny", "tool-w100", "tool-w800", "skill-invoke-w200", "skill-invoke-w800"]) {
    const r = runs.find((x) => x.name === `${name}-partial-r1`)!; const p = r.procs[0];
    const { msgs, shape: sh } = sessionMessages(p.sessionFile); const sys = clean(sh.system), tl = clean(sh.tools);
    const c1 = await count({ system: sys, tools: tl, messages: msgs.slice(0, 1) });
    const c3 = await count({ system: sys, tools: tl, messages: msgs.slice(0, 3) });
    const cs = made(p); const real = P(cs[1]) - P(cs[0]); const out1 = cs[0].transcript.at(-1).output;
    crows.push([name, c3 - c1, real, real - out1, real - (c3 - c1)]);
  }
  md += table(["scenario", "tool_use + tool_result (counted)", "usage growth call1→2", "usage growth − call 1 output", "usage growth − counted"], crows);
  md += `\nThe first column is the independent input cost of the tool round (an assistant tool_use message plus the tool_result message); a tool_use cannot be counted without its result, so the two are not split.\n\n`;

  // ---- D. parallel tool calls in one message ----
  const pdirs = readdirSync(join(INVESTIGATION_DIR, "results")).filter((d) => d.endsWith("-attribution-cli") && existsSync(join(INVESTIGATION_DIR, "results", d, "runs.json")));
  const prRuns: any[] = pdirs.flatMap((d) => JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", d, "runs.json"), "utf8")).runs.filter((x: any) => x.scenario === "tool-parallel" && x.mode === "partial"));
  if (prRuns.length) {
    md += `## D. Three parallel Bash calls in one message (cat tiny.txt, data-w100.txt, data-w800.txt)\n\n`;
    const drows: (string | number)[][] = [], srows: (string | number)[][] = [];
    for (const r of prRuns) {
      const p = r.procs[0]; const { msgs, shape: sh } = sessionMessages(p.sessionFile); const sys = clean(sh.system), tl = clean(sh.tools);
      const cs = made(p); const out1 = cs[0].transcript.at(-1).output; const growth = P(cs[1]) - P(cs[0]);
      const uses = msgs[1].content.filter((b: any) => b.type === "tool_use"), results = msgs[2].content.filter((b: any) => b.type === "tool_result");
      const c1 = await count({ system: sys, tools: tl, messages: msgs.slice(0, 1) });
      const full = (await count({ system: sys, tools: tl, messages: msgs.slice(0, 3) })) - c1;
      let sumPairs = 0, sumUse = 0, sumRes = 0;
      for (let i = 0; i < uses.length; i++) {
        const res = results.find((x: any) => x.tool_use_id === uses[i].id);
        const pair = (await count({ system: sys, tools: tl, messages: [msgs[0], { role: "assistant", content: [uses[i]] }, { role: "user", content: [res] }] })) - c1;
        const pairX = (await count({ system: sys, tools: tl, messages: [msgs[0], { role: "assistant", content: [uses[i]] }, { role: "user", content: [{ ...res, content: "x" }] }] })) - c1;
        sumPairs += pair; sumUse += pairX; sumRes += pair - pairX;
        drows.push([r.name, JSON.stringify(uses[i].input).slice(0, 40), pair, pairX, pair - pairX]);
      }
      srows.push([r.name, cs[0].blocks.join("+"), out1, growth, growth - out1, full, sumPairs, sumUse, sumRes, growth - out1 - full]);
    }
    md += table(["run", "tool_use input", "tool_use + result (counted pair)", "of which tool_use with a 1-char result", "result content (pair − that)"], drows);
    md += `\n` + table(["run", "call 1 blocks", "call 1 output (final)", "usage growth call1→2", "growth − output", "whole round counted", "Σ pairs", "Σ tool_use parts", "Σ result parts", "growth − output − whole round"], srows);
    md += `\nPairs are conversations with one tool_use and its own result; "tool_use with a 1-char result" counts the call plus a fixed minimal result, so it is an upper bound of the tool_use cost. Output tokens exist only for the message as a whole.\n\n`;
  }

  // ---- E. MCP tool: instructions, deferred loading through ToolSearch, results ----
  const mrunsAll: any[] = pdirs.flatMap((d) => JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", d, "runs.json"), "utf8")).runs.filter((x: any) => /^mcp-/.test(x.scenario) && x.mode === "partial"));
  if (mrunsAll.length) {
    md += `## E. MCP server with one tool (datamcp: lookup) and server instructions\n\n`;
    const baseP = runs.filter((x) => x.scenario === "base").map((x) => P(made(x.procs[0])[0]))[0];
    const mb = mrunsAll.find((x) => x.scenario === "mcp-base")!; const mbP = P(made(mb.procs[0])[0]);
    const { attachments } = sessionMessages(mb.procs[0].sessionFile);
    const instr = attachments.find((a: any) => a.type === "mcp_instructions_delta")?.addedBlocks?.join("\n") ?? "";
    const deferred = attachments.find((a: any) => a.type === "deferred_tools_delta");
    const instrTok = (await count({ messages: [{ role: "user", content: instr }] })) - (await count({ messages: X }));
    md += `First call with the MCP server (\`mcp-base\`): ${mbP} tokens, ${mbP - baseP} more than the same session without it (\`base\`: ${baseP}). The server's instructions text (${instr.length} chars) counts ${instrTok} tokens alone. The tool itself is deferred: ${deferred ? "its name is in the deferred_tools_delta list" : "?"} and its definition is not in the first request.\n\n`;
    const erows: (string | number)[][] = [], trows: (string | number)[][] = [];
    for (const r of mrunsAll.filter((x) => x.scenario !== "mcp-base")) {
      const p = r.procs[0]; const cs = made(p); const { msgs, lastShape, shape: sh0 } = sessionMessages(p.sessionFile);
      const sys = clean(sh0.system), tl = clean(lastShape.tools);
      const out = cs.map((c: any) => c.transcript.at(-1).output);
      const th = cs[0].blocks.includes("thinking");
      trows.push([r.name, cs.map((c: any) => c.blocks.join("+")).join(" › "), P(cs[0]), out[0], P(cs[1]), P(cs[1]) - P(cs[0]), P(cs[1]) - P(cs[0]) - out[0], th ? "yes" : "no"]);
      const asst = msgs.findIndex((m, i) => i >= 3 && m.role === "assistant" && m.content.some((b: any) => b.type === "tool_use" && b.name === "mcp__datamcp__lookup"));
      const uses = msgs[asst].content.filter((b: any) => b.type === "tool_use"), results = msgs[asst + 1].content.filter((b: any) => b.type === "tool_result");
      const c1 = await count({ system: sys, tools: tl, messages: msgs.slice(0, 1) });
      const full = (await count({ system: sys, tools: tl, messages: [msgs[0], msgs[asst], msgs[asst + 1]] })) - c1;
      const growth = P(cs[2]) - P(cs[1]);
      let sumRes = 0;
      const parts: string[] = [];
      for (let i = 0; i < uses.length; i++) {
        const res = results.find((x: any) => x.tool_use_id === uses[i].id);
        const pair = (await count({ system: sys, tools: tl, messages: [msgs[0], { role: "assistant", content: [uses[i]] }, { role: "user", content: [res] }] })) - c1;
        const pairX = (await count({ system: sys, tools: tl, messages: [msgs[0], { role: "assistant", content: [uses[i]] }, { role: "user", content: [{ ...res, content: [{ type: "text", text: "x" }] }] }] })) - c1;
        parts.push(`${uses[i].input.name}: pair ${pair}, result ${pair - pairX}`); sumRes += pair - pairX;
      }
      erows.push([r.name, uses.length, out[1], growth, growth - out[1], full, growth - full, parts.join("; ")]);
    }
    md += `Per run, API calls: [thinking +] ToolSearch tool_use → lookup tool_use → text.\n\n` + table(["run", "blocks per call", "call 1 prompt", "call 1 output", "call 2 prompt", "growth 1→2", "growth − call 1 output", "call 1 has thinking"], trows);
    md += `\nThe lookup round (call 2 → call 3):\n\n` + table(["run", "lookups", "call 2 output (tool_use)", "usage growth 2→3", "growth − output", "lookup tool_use + results counted", "growth − counted", "per lookup (counted)"], erows);
  }

  md += `${nCalls} count_tokens requests.\n`;
  writeSummary("count-tokens-summary.md", md);
  console.log(md);
}
main().catch((e) => { console.error(e); process.exit(1); });

/**
 * Experiment: in the Agent SDK, does a subagent that launches a nested subagent
 * wait for that nested subagent before it finishes?
 *
 * Docs claim (code.claude.com/docs/en/sub-agents#let-subagents-spawn-their-own-subagents):
 *   "In non-interactive mode and the Agent SDK, the launching subagent doesn't wait,
 *    so a nested background subagent that finishes after its launcher has ended
 *    reports to your main conversation instead."
 *
 * Topology:  main  --Agent(outer)-->  launcher  --Agent(inner)-->  slow-worker (sleep 40s, returns random token)
 *
 * Each scenario fixes outer/inner foreground-vs-background. The PreToolUse hook enforces the
 * run_in_background value on every Agent call (and records whether the model already chose it),
 * and task_started.is_backgrounded confirms the mode the harness actually used.
 *
 * Usage:  npx tsx investigations/subagent-background-behaviour/experiment.ts [scenario ...]
 *   scenarios: fg-bg  fg-fg  bg-bg  bg-fg   (outer-inner). Default: all four.
 */
import { query, type HookCallback, type SDKMessage, type SDKUserMessage } from "@anthropic-ai/claude-agent-sdk";
import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { ISOLATION_ENV, ISOLATION_SETTINGS, RESULTS_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";

type Mode = "fg" | "bg";
/**
 * input: how the SDK client feeds the main conversation
 *   "open"   streaming input kept open until all background work has drained (default)
 *   "close"  streaming input closed as soon as the first result arrives
 *   "string" plain string prompt (one-shot, the SDK closes stdin itself)
 * busyMain: after the launcher returns, main runs its own 70 s command, so the worker finishes mid-turn
 */
/** direct: main calls slow-worker itself (no launcher); `outer` is then the worker's mode and `inner` is unused */
type Scenario = { name: string; outer: Mode; inner: Mode; input?: "open" | "close" | "string"; busyMain?: boolean; direct?: boolean };

const ALL: Scenario[] = [
  { name: "fg-bg", outer: "fg", inner: "bg" },
  { name: "fg-fg", outer: "fg", inner: "fg" },
  { name: "bg-bg", outer: "bg", inner: "bg" },
  { name: "bg-fg", outer: "bg", inner: "fg" },
  // main-conversation behaviour (all with a background worker that outlives its launcher)
  { name: "main-busy", outer: "fg", inner: "bg", busyMain: true },
  { name: "main-close", outer: "fg", inner: "bg", input: "close" },
  { name: "main-string", outer: "fg", inner: "bg", input: "string" },
  // main calls the worker directly, no launcher in between
  { name: "direct-fg", outer: "fg", inner: "fg", direct: true },
  { name: "direct-bg", outer: "bg", inner: "bg", direct: true },
  // one-shot string prompt: nothing in this script holds the session open, so the CLI alone decides when it ends
  { name: "1shot-direct-fg", outer: "fg", inner: "fg", direct: true, input: "string" },
  { name: "1shot-direct-bg", outer: "bg", inner: "bg", direct: true, input: "string" },
  { name: "1shot-fg-fg", outer: "fg", inner: "fg", input: "string" },
  { name: "1shot-fg-bg", outer: "fg", inner: "bg", input: "string" },
  { name: "1shot-bg-fg", outer: "bg", inner: "fg", input: "string" },
  { name: "1shot-bg-bg", outer: "bg", inner: "bg", input: "string" },
];

const HARD_TIMEOUT_MS = 6 * 60_000;
const QUIET_GRACE_MS = 10_000;

const TOKEN_RE = /WORKER_TOKEN=\d+/;

function mainPrompt(s: Scenario): string {
  return loadPrompt("nested-main", { direct: !!s.direct, busy_main: !!s.busyMain, outer_bg: s.outer === "bg", inner_bg: s.inner === "bg" });
}

/** Main-thread entries of the session transcript: exactly what the main model was fed, minus static context. */
function mainTranscriptExcerpt(path: string): string {
  const skip = new Set(["environment", "model", "deferred_tools_delta", "agent_listing_delta", "skill_listing", "total_tokens_reminder",
    "session_context", "date", "credential_org", "prompt_snapshot", "mcp_instructions_delta", "remote_session_change"]);
  const out: string[] = [];
  let raw = "";
  try { raw = readFileSync(path, "utf8"); } catch { return `(transcript not found: ${path})`; }
  for (const line of raw.split("\n")) {
    if (!line.trim()) continue;
    const e = JSON.parse(line);
    if (["file-history-snapshot", "atis-latch", "last-prompt", "ai-title", "cost-state"].includes(e.type)) continue;
    if (e.type === "attachment" && skip.has(e.attachment?.type)) continue;
    const c = e.message?.content;
    const body = typeof c === "string" ? c
      : Array.isArray(c) ? c.map((b: any) => `${b.type}: ${b.text ?? JSON.stringify(b.content ?? b.input)}`).join("\n")
      : JSON.stringify({ content: e.content, attachment: e.attachment, operation: e.operation });
    const meta = ["origin", "operation"].filter((k) => k in e).map((k) => `${k}=${JSON.stringify(e[k])}`).join(" ");
    out.push(`--- ${String(e.timestamp ?? "").slice(11, 23)} ${e.type} ${meta}\n${body}`);
  }
  return out.join("\n");
}

async function runScenario(s: Scenario) {
  const t0 = Date.now();
  const logPath = join(RESULTS_DIR, `${s.name}.jsonl`);
  writeFileSync(logPath, "");

  const agentTypeById = new Map<string, string>(); // agent_id/task_id -> agent type
  const stops: { t: number; type: string; id: string; last: string; bgTasks: number }[] = [];
  const taskStarts: Record<string, any> = {};
  const taskEnds: Record<string, { t: number; via: string; status?: string }> = {};
  const agentToolReturns: { t: number; caller: string; text: string }[] = [];
  const mainTexts: { t: number; origin: string; text: string }[] = [];
  const hookAdjustments: string[] = [];
  let workerToken: string | undefined;
  let lastMsgAt = Date.now();
  let resultCount = 0;
  let lastWasResult = false;
  let liveBgTasks = 0;
  let transcriptPath: string | undefined;
  const mainResults: { t: number; origin: string; num_turns: number; text: string }[] = [];
  const mainInjected: { t: number; origin: string; text: string }[] = [];
  let mainAgentReturnAt: number | undefined;
  let mainBashReturnAt: number | undefined;

  const log =(src: string, event: string, data: Record<string, unknown> = {}) => {
    const t = Date.now() - t0;
    appendFileSync(logPath, JSON.stringify({ t, src, event, ...data }) + "\n");
    const brief = Object.entries(data)
      .map(([k, v]) => `${k}=${typeof v === "string" ? JSON.stringify(v.length > 110 ? v.slice(0, 110) + "…" : v) : JSON.stringify(v)}`)
      .join(" ");
    console.log(`[${s.name}] ${(t / 1000).toFixed(1).padStart(6)}s  ${src.padEnd(6)} ${event.padEnd(26)} ${brief}`);
  };
  const who = (input: any) => (input.agent_id ? `${input.agent_type ?? agentTypeById.get(input.agent_id) ?? "?"}` : "main");
  const textOf = (v: unknown): string =>
    typeof v === "string" ? v : Array.isArray(v) ? v.map((b: any) => b?.text ?? "").join("\n") : JSON.stringify(v ?? "");

  // ---- hooks: precise timestamps for subagent lifecycle and Agent tool calls ----
  const preAgent: HookCallback = async (input: any) => {
    const caller = who(input);
    if (caller === "main") transcriptPath = input.transcript_path;
    const want = caller === "main" ? s.outer === "bg" : s.inner === "bg";
    const asked = input.tool_input?.run_in_background;
    log("hook", "PreToolUse(Agent)", { caller, subagent_type: input.tool_input?.subagent_type, model_asked_bg: asked, enforced_bg: want });
    if (asked !== want) hookAdjustments.push(`${caller}: model asked run_in_background=${asked}, enforced ${want}`);
    return {
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "allow",
        updatedInput: { ...input.tool_input, run_in_background: want },
      },
    };
  };
  const postTool: HookCallback = async (input: any) => {
    const caller = who(input);
    const text = textOf(input.tool_response?.content ?? input.tool_response);
    if (input.tool_name === "Agent") {
      agentToolReturns.push({ t: Date.now() - t0, caller, text });
      if (caller === "main") mainAgentReturnAt = Date.now() - t0;
      log("hook", "PostToolUse(Agent)", { caller, returned: text });
    } else {
      if (caller === "main") mainBashReturnAt = Date.now() - t0;
      const m = text.match(TOKEN_RE) ?? JSON.stringify(input.tool_response ?? "").match(TOKEN_RE);
      if (m) workerToken = m[0];
      log("hook", `PostToolUse(${input.tool_name})`, { caller, token: m?.[0] });
    }
    return {};
  };
  const subStart: HookCallback = async (input: any) => {
    agentTypeById.set(input.agent_id, input.agent_type);
    log("hook", "SubagentStart", { agent: input.agent_type, agent_id: input.agent_id });
    return {};
  };
  const subStop: HookCallback = async (input: any) => {
    const type = input.agent_type ?? agentTypeById.get(input.agent_id) ?? "?";
    const last = input.last_assistant_message ?? "";
    const bgTasks = (input.background_tasks ?? []).length;
    stops.push({ t: Date.now() - t0, type, id: input.agent_id, last, bgTasks });
    log("hook", "SubagentStop", { agent: type, last_message: last, in_flight_bg_tasks: bgTasks });
    return {};
  };

  // ---- input: streaming (kept open until drained, or closed after the first result) or a plain string ----
  const inputMode = s.input ?? "open";
  let finish!: () => void;
  const finished = new Promise<void>((r) => (finish = r));
  let gotFirstResult!: () => void;
  const firstResult = new Promise<void>((r) => (gotFirstResult = r));
  async function* input(): AsyncGenerator<SDKUserMessage> {
    yield { type: "user", message: { role: "user", content: mainPrompt(s) }, parent_tool_use_id: null };
    await (inputMode === "close" ? Promise.race([firstResult, finished]) : finished);
    if (inputMode === "close") log("runner", "closing input after first result");
  }

  const q = query({
    prompt: inputMode === "string" ? mainPrompt(s) : input(),
    options: {
      cwd: process.cwd(),
      model: "sonnet",
      settingSources: ["project"], // loads .claude/agents/*.md from the investigation folder (the cwd)
      settings: ISOLATION_SETTINGS,
      allowedTools: ["Agent", "Bash"],
      permissionMode: "dontAsk",
      env: { ...process.env, ...ISOLATION_ENV, CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "3" },
      hooks: {
        PreToolUse: [{ matcher: "Agent", hooks: [preAgent] }],
        PostToolUse: [{ hooks: [postTool] }],
        SubagentStart: [{ hooks: [subStart] }],
        SubagentStop: [{ hooks: [subStop] }],
      },
    },
  });

  const watchdog = setInterval(() => {
    const elapsed = Date.now() - t0;
    const allEnded = Object.keys(taskStarts).length >= (s.direct ? 1 : 2) &&Object.keys(taskStarts).every((id) => taskEnds[id]);
    if (elapsed > HARD_TIMEOUT_MS) {
      log("runner", "HARD_TIMEOUT");
      finish();
      q.close();
    } else if (lastWasResult && allEnded && liveBgTasks === 0 && Date.now() - lastMsgAt > QUIET_GRACE_MS) {
      log("runner", "drained; closing input");
      finish();
    }
  }, 1000);

  try {
    for await (const m of q as AsyncIterable<SDKMessage>) {
      lastMsgAt = Date.now();
      lastWasResult = m.type === "result";
      const anyM = m as any;
      if (m.type === "system") {
        switch (anyM.subtype) {
          case "init":
            recordClaudeVersion("sdk", anyM.claude_code_version);
            log("stream", "system:init", { cli: anyM.claude_code_version, model: anyM.model, agents: anyM.agents });
            break;
          case "task_started":
            taskStarts[anyM.task_id] = anyM;
            if (anyM.subagent_type) agentTypeById.set(anyM.task_id, anyM.subagent_type);
            log("stream", "task_started", {
              agent: anyM.subagent_type, task_id: anyM.task_id, is_backgrounded: anyM.is_backgrounded,
              spawn_depth: anyM.spawn_depth, parent_task: anyM.parent_task_id ? agentTypeById.get(anyM.parent_task_id) ?? anyM.parent_task_id : "main",
            });
            break;
          case "task_updated":
            if (["completed", "failed", "killed"].includes(anyM.patch?.status) && !taskEnds[anyM.task_id])
              taskEnds[anyM.task_id] = { t: Date.now() - t0, via: "task_updated", status: anyM.patch.status };
            log("stream", "task_updated", { agent: agentTypeById.get(anyM.task_id), patch: anyM.patch });
            break;
          case "task_notification":
            if (!taskEnds[anyM.task_id]) taskEnds[anyM.task_id] = { t: Date.now() - t0, via: "task_notification", status: anyM.status };
            log("stream", "task_notification", { agent: agentTypeById.get(anyM.task_id), status: anyM.status, summary: anyM.summary });
            break;
          case "background_tasks_changed":
            liveBgTasks = (anyM.tasks ?? []).length;
            log("stream", "background_tasks_changed", { live: (anyM.tasks ?? []).map((t: any) => t.subagent_type ?? t.task_type) });
            break;
          case "task_progress":
            break;
          default:
            log("stream", `system:${anyM.subtype}`);
        }
      } else if (m.type === "assistant" && !anyM.parent_tool_use_id) {
        const text = (anyM.message?.content ?? []).filter((b: any) => b.type === "text").map((b: any) => b.text).join("\n");
        for (const b of anyM.message?.content ?? [])
          if (b.type === "tool_use") log("stream", "main tool_use", { name: b.name, input: b.input });
        if (text) {
          mainTexts.push({ t: Date.now() - t0, origin: "assistant", text });
          log("stream", "main assistant text", { text });
        }
      } else if (m.type === "user" && !anyM.parent_tool_use_id) {
        const content = anyM.message?.content;
        const isToolResult = Array.isArray(content) && content.some((b: any) => b.type === "tool_result");
        const text = isToolResult ? textOf(content.map((b: any) => ({ text: textOf(b.content) }))) : textOf(content);
        if (!isToolResult) mainInjected.push({ t: Date.now() - t0, origin: anyM.origin?.kind ?? "none", text });
        log("stream", isToolResult ? "main user tool_result" : "main user message", { origin: anyM.origin?.kind, synthetic: anyM.isSynthetic, text });
      } else if (m.type === "result") {
        resultCount++;
        const origin = anyM.origin?.kind ?? "prompt";
        mainTexts.push({ t: Date.now() - t0, origin, text: anyM.result ?? "" });
        mainResults.push({ t: Date.now() - t0, origin, num_turns: anyM.num_turns, text: anyM.result ?? "" });
        log("stream", "RESULT", { n: resultCount, subtype: anyM.subtype, origin, num_turns: anyM.num_turns, result: anyM.result, cost: anyM.total_cost_usd });
        gotFirstResult();
      }
    }
    log("runner", "query iterator ended");
  } catch (e) {
    log("runner", "query iterator threw", { error: String(e) });
  } finally {
    clearInterval(watchdog);
    finish();
  }
  const iteratorEndedAt = Date.now() - t0;

  // ---- verdict ----
  const idsOf = (type: string) => Object.keys(taskStarts).filter((id) => agentTypeById.get(id) === type);
  const launcherId = idsOf("launcher")[0];
  const workerId = idsOf("slow-worker")[0];
  const launcherStops = stops.filter((x) => x.type === "launcher");
  const workerStops = stops.filter((x) => x.type === "slow-worker");
  const launcherFirstStop = launcherStops[0];
  const launcherLastStop = launcherStops[launcherStops.length - 1];
  const workerStop = workerStops[workerStops.length - 1];
  const launcherSawToken = launcherStops.some((x) => TOKEN_RE.test(x.last));
  const launcherAgentReturn = agentToolReturns.find((r) => r.caller === "launcher");
  // result entries carry the turn origin: "prompt" (answer to our prompt) or "task-notification" (injected turn)
  const mainSawToken = mainTexts.find((x) => x.origin !== "assistant" && TOKEN_RE.test(x.text));
  const notifResults = mainTexts.filter((x) => x.origin === "task-notification");

  const verdict = {
    scenario: s.name,
    direct: !!s.direct,
    outer_requested: s.outer,
    inner_requested: s.inner,
    launcher_is_backgrounded: launcherId ? taskStarts[launcherId].is_backgrounded : null,
    worker_is_backgrounded: workerId ? taskStarts[workerId].is_backgrounded : null,
    worker_spawn_depth: workerId ? taskStarts[workerId].spawn_depth : null,
    worker_token: workerToken ?? null,
    launcher_agent_tool_returned_s: launcherAgentReturn ? launcherAgentReturn.t / 1000 : null,
    launcher_agent_tool_return_text: launcherAgentReturn?.text.slice(0, 200) ?? null,
    launcher_first_stop_s: launcherFirstStop ? launcherFirstStop.t / 1000 : null,
    launcher_last_stop_s: launcherLastStop ? launcherLastStop.t / 1000 : null,
    launcher_stop_count: launcherStops.length,
    worker_stop_s: workerStop ? workerStop.t / 1000 : null,
    launcher_ended_before_worker: launcherFirstStop && workerStop ? launcherFirstStop.t < workerStop.t : null,
    launcher_final_message_has_token: launcherSawToken,
    launcher_final_message: launcherLastStop?.last ?? null,
    main_saw_token: !!mainSawToken,
    main_saw_token_via: mainSawToken?.origin ?? null,
    main_task_notification_turns: notifResults.length,
    hook_adjustments: hookAdjustments,
    results: resultCount,
    launcher_waited_for_worker:
      launcherFirstStop && workerStop ? !(launcherFirstStop.t < workerStop.t && !launcherSawToken) : null,
    // ---- main conversation ----
    main: {
      input_mode: inputMode,
      busy_main: !!s.busyMain,
      blocked_on_launcher_until_s: mainAgentReturnAt !== undefined ? mainAgentReturnAt / 1000 : null,
      own_work_returned_s: mainBashReturnAt !== undefined ? mainBashReturnAt / 1000 : null,
      results: mainResults.map((r) => ({ at_s: r.t / 1000, origin: r.origin, num_turns: r.num_turns, text: r.text })),
      injected_user_messages_on_stream: mainInjected.map((x) => ({ at_s: x.t / 1000, origin: x.origin, text: x.text.slice(0, 300) })),
      worker_end_status: workerId ? taskEnds[workerId]?.status ?? "no end event" : "never started",
      worker_end_s: workerId && taskEnds[workerId] ? taskEnds[workerId].t / 1000 : null,
      token_reached_main: !!mainSawToken,
      token_reached_main_in_turn: mainSawToken?.origin ?? null,
      token_reached_main_at_s: mainSawToken ? mainSawToken.t / 1000 : null,
      query_iterator_ended_s: iteratorEndedAt / 1000,
      transcript: transcriptPath ?? null,
    },
  };
  writeFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), JSON.stringify(verdict, null, 2));
  if (transcriptPath) writeFileSync(join(RESULTS_DIR, `${s.name}.main-transcript.txt`), mainTranscriptExcerpt(transcriptPath));
  console.log(`\n[${s.name}] VERDICT\n${JSON.stringify(verdict, null, 2)}\n`);
  return verdict;
}

async function main() {
  beginRun();
  mkdirSync(RESULTS_DIR, { recursive: true });
  const names = process.argv.slice(2);
  const scenarios = names.length ? ALL.filter((s) => names.includes(s.name)) : ALL;
  for (const s of scenarios) await runScenario(s);

  // summary covers every scenario that has a verdict on disk, so running a subset keeps the others
  const verdicts = ALL.flatMap((s) => {
    try { return [JSON.parse(readFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), "utf8"))]; } catch { return []; }
  });
  const launcherRows = verdicts.filter((v) => !v.direct).map(
    (v) =>
      `| ${v.scenario} | ${v.launcher_is_backgrounded} | ${v.worker_is_backgrounded} | ${v.launcher_first_stop_s} | ${v.worker_stop_s} | ` +
      `${v.launcher_final_message_has_token} | **${v.launcher_waited_for_worker ? "WAITED" : "DID NOT WAIT"}** |`,
  );
  const mainRows = verdicts.filter((v) => v.main).map((v) => {
    const m = v.main;
    const results = m.results.map((r: any) => `${r.at_s}s ${r.origin}: \`${r.text.replace(/\|/g, "\\|").replace(/\n/g, " ⏎ ")}\``).join("<br>");
    const mode = v.direct ? `direct worker ${v.worker_is_backgrounded ? "bg" : "fg"}` : `${m.input_mode}${m.busy_main ? " + busy main" : ""}`;
    return `| ${v.scenario} | ${mode} |${m.blocked_on_launcher_until_s ?? "-"} | ` +
      `${m.worker_end_status} @ ${m.worker_end_s ?? "-"}s | ${results} | ${m.token_reached_main ? m.token_reached_main_in_turn : "no"} | ${m.query_iterator_ended_s} |`;
  });
  const tokenRows = verdicts.filter((v) => v.main).map((v) => {
    const m = v.main;
    const chain = v.direct ? `main →${v.outer_requested} worker` : `main →${v.outer_requested} launcher →${v.inner_requested} worker`;
    // verdicts written before token_reached_main_at_s existed: take the first result that carries the token
    m.token_reached_main_at_s ??= m.results.find((r: any) => TOKEN_RE.test(r.text))?.at_s ?? null;
    const how = !m.token_reached_main ? "**NEVER**" : m.token_reached_main_in_turn === "prompt" ? "sync (in the prompt's turn)" : "callback (task-notification turn)";
    const before = m.token_reached_main ? (m.token_reached_main_at_s <= m.query_iterator_ended_s ? "yes" : "no") : "no";
    return `| ${v.scenario} | ${chain} | ${m.input_mode} | ${m.worker_end_s ?? "-"} | ${how} | ${m.token_reached_main_at_s ?? "-"} | ${m.query_iterator_ended_s} | ${before} |`;
  });
  const md = [
    "## Did the WORKER_TOKEN reach main before the session ended?",
    "",
    "input `open` = this script kept the session open until background work drained; `string` = one-shot, the CLI alone decides when to end.",
    "",
    "| scenario | chain (fg = sync, bg = async) | input | worker ended (s) | token reached main | at (s) | session ended (s) | before end |",
    "|---|---|---|---|---|---|---|---|",
    ...tokenRows,
    "",
    "## Launcher behaviour",
    "",
    "| scenario (outer-inner) | launcher bg | worker bg | launcher ended (s) | worker ended (s) | launcher got token | launcher |",
    "|---|---|---|---|---|---|---|",
    ...launcherRows,
    "",
    "## Main conversation behaviour",
    "",
    "| scenario | input | main's Agent call returned (s) | worker | main results (time, turn origin, text) | worker token reached main in | query iterator ended (s) |",
    "|---|---|---|---|---|---|---|",
    ...mainRows,
  ].join("\n");
  writeSummary("summary.md", md);
  console.log(md);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Can the input side of a claude -p conversation be attributed to categories (tool results, user messages,
 * skills / instructions, preamble pieces) from the stream-json output (with and without --include-partial-messages)
 * and from the session .jsonl?
 *
 * The driver builds one fixture folder per scenario under fixtures/, runs `claude -p` in both modes (plain, partial),
 * and records per API call: the prompt size (input + cache_creation + cache_read) from every source that has it,
 * plus every numeric "token" field the stream and the session file contain (to see whether any carries a
 * per-category figure). The attribution itself (differences between scenarios, between consecutive calls) is done
 * offline by analyze.ts on runs.json.
 *
 * Usage:  npx tsx investigations/prompt-token-attribution/attribution-cli.ts [--reps N] [--concurrency N]
 *           [--modes plain,partial] [scenario ...]
 */
import { spawn } from "node:child_process";
import { writeFileSync, appendFileSync, readFileSync, existsSync, mkdirSync, rmSync } from "node:fs";
import { homedir } from "node:os";
import { join, dirname } from "node:path";
import { createInterface } from "node:readline";
import { ISOLATION_ENV, ISOLATION_SETTINGS, SESSIONS_DIR, RESULTS_DIR, INVESTIGATION_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";

const MODEL = "claude-haiku-5-5";
const EFFORT = "medium";
const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
const FIXTURES = join(INVESTIGATION_DIR, "fixtures");
type Mode = "plain" | "partial";

// ---------- deterministic filler text ----------
const ADJ = "quiet small old green busy narrow bright wooden tidy warm cheerful dusty long shallow modest".split(" ");
const NOUN = "garden bakery library harbor market kitchen orchard workshop station village bridge greenhouse schoolyard lighthouse tavern".split(" ");
const THING = "bread basket lantern ladder blanket kettle bicycle notebook umbrella teapot candle shelf barrel mirror pencil".split(" ");
const VERB = "repaired carried painted cleaned measured polished arranged counted folded stacked watered sorted".split(" ");
const TIME = "morning evening weekend summer winter autumn spring afternoon".split(" ");
// Plain, harmless English sentences, deterministic per tag, about `words` words long.
function filler(words: number, tag: string): string {
  let s = 12345 + [...tag].reduce((a, c) => a + c.charCodeAt(0), 0);
  const pick = (xs: string[]) => { s = (s * 1103515245 + 12345) & 0x7fffffff; return xs[(s >> 8) % xs.length]; };
  const out: string[] = []; let n = 0, count = 0;
  while (count < words) {
    const sent = `The ${pick(ADJ)} ${pick(NOUN)} keeper ${pick(VERB)} the ${pick(ADJ)} ${pick(THING)} near the ${pick(NOUN)} every ${pick(TIME)}.`;
    out.push(sent); count += sent.split(" ").length;
    if (++n % 5 === 0) out.push("\n\n");
  }
  return out.join(" ").replace(/ \n\n /g, "\n\n").trim();
}
const wc = (t: string) => t.split(/\s+/).filter(Boolean).length;

// ---------- fixtures ----------
function put(rel: string, text: string) { const p = join(FIXTURES, rel); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, text); }
function skill(fixture: string, name: string, description: string, bodyWords: number) {
  put(`${fixture}/.claude/skills/${name}/SKILL.md`, `---\nname: ${name}\ndescription: ${description}\n---\n\nSKILLBODY_${name.toUpperCase().replace(/-/g, "_")}\n\n${filler(bodyWords, name + bodyWords)}\n\nAfter reading this, continue with the task you were given.\n`);
}
const DESCR = ["Use when the user asks about copper lanterns and harbor ladders in the old meadow.", "Use when the user asks about velvet anchors and marble ribbons near the island forest.", "Use when the user asks about thunder pencils and brass kettles inside the glacier tunnel."];
function buildFixtures() {
  rmSync(FIXTURES, { recursive: true, force: true });
  put("empty/README.txt", "empty fixture\n");
  put("claudemd-w200/CLAUDE.md", `# Project notes\n\nCLAUDEMD_MARK_W200\n\n${filler(200, "claudemd200")}\n`);
  put("claudemd-w800/CLAUDE.md", `# Project notes\n\nCLAUDEMD_MARK_W800\n\n${filler(800, "claudemd800")}\n`);
  put("skills-1/README.txt", "one skill, 800-word body\n"); skill("skills-1", "probe-a", DESCR[0], 800);
  put("skills-3/README.txt", "three skills, 800-word bodies\n");
  ["probe-a", "probe-b", "probe-c"].forEach((n, i) => skill("skills-3", n, DESCR[i], 800));
  put("skillbody-w200/README.txt", "one skill, 200-word body\n"); skill("skillbody-w200", "probe-a", DESCR[0], 200);
  put("skillbody-w800/README.txt", "one skill, 800-word body\n"); skill("skillbody-w800", "probe-a", DESCR[0], 800);
  put("tooldata/README.txt", "data files for tool results\n");
  for (const n of [100, 800]) put(`tooldata/data-w${n}.txt`, `TOOLDATA_MARK_W${n}\n\n${filler(n, "tooldata" + n)}\n`);
  put("tooldata/tiny.txt", "TOOLDATA_MARK_TINY\n");
  put("mcp.json", JSON.stringify({ mcpServers: { datamcp: { command: "node", args: [join(INVESTIGATION_DIR, "datamcp.mjs"), join(FIXTURES, "tooldata")] } } }, null, 2));
}

// ---------- scenarios ----------
type Turn = { tpl: string; vars: Record<string, any> };
type Scn = { name: string; fixture: string; turns: Turn[]; flags?: string[]; group: string; env?: Record<string, string> };
const OK: Turn = { tpl: "reply-ok", vars: {} };
const userTurn = (n: number, tag = "U"): Turn => ({ tpl: "user-filler", vars: { filler: `USER_MARK_${tag}${n}\n\n` + filler(n, "user" + tag + n) } });
const skillTurn = (s: string): Turn => ({ tpl: "invoke-skill", vars: { skill: s } });
const bash = (c: string): Turn => ({ tpl: "run-bash", vars: { command: c } });
const MCP = ["--mcp-config", join(FIXTURES, "mcp.json"), "--strict-mcp-config"]; // one stdio MCP server (datamcp.mjs) with a `lookup` tool and server instructions
const mcpTurn = (name: string): Turn => ({ tpl: "run-mcp", vars: { name } });
const S = ["--strict-mcp-config"]; // claude.ai connector instructions arrive mid-conversation (see report), so every attribution scenario excludes them
const SCENARIOS: Scn[] = [
  { name: "base", group: "user", fixture: "empty", turns: [OK], flags: S },
  { name: "user-w200", group: "user", fixture: "empty", turns: [userTurn(200)], flags: S },
  { name: "user-w800", group: "user", fixture: "empty", turns: [userTurn(800)], flags: S },
  { name: "claudemd-w200", group: "instructions", fixture: "claudemd-w200", turns: [OK], flags: S },
  { name: "claudemd-w800", group: "instructions", fixture: "claudemd-w800", turns: [OK], flags: S },
  { name: "skills-listing-1", group: "skills", fixture: "skills-1", turns: [OK], flags: S },
  { name: "skills-listing-3", group: "skills", fixture: "skills-3", turns: [OK], flags: S },
  { name: "skill-invoke-w200", group: "skills", fixture: "skillbody-w200", turns: [skillTurn("probe-a")], flags: S },
  { name: "skill-invoke-w800", group: "skills", fixture: "skillbody-w800", turns: [skillTurn("probe-a")], flags: S },
  { name: "tool-tiny", group: "tool-result", fixture: "tooldata", turns: [bash("cat tiny.txt")], flags: S },
  { name: "tool-w100", group: "tool-result", fixture: "tooldata", turns: [bash("cat data-w100.txt")], flags: S },
  { name: "tool-w800", group: "tool-result", fixture: "tooldata", turns: [bash("cat data-w800.txt")], flags: S },
  { name: "tool-parallel", group: "tool-result", fixture: "tooldata", turns: [{ tpl: "run-bash-parallel", vars: {} }], flags: S },
  { name: "mcp-base", group: "mcp", fixture: "empty", turns: [OK], flags: MCP },
  { name: "mcp-tiny", group: "mcp", fixture: "empty", turns: [mcpTurn("tiny")], flags: MCP },
  { name: "mcp-w100", group: "mcp", fixture: "empty", turns: [mcpTurn("w100")], flags: MCP },
  { name: "mcp-w800", group: "mcp", fixture: "empty", turns: [mcpTurn("w800")], flags: MCP },
  { name: "mcp-parallel", group: "mcp", fixture: "empty", turns: [{ tpl: "run-mcp-parallel", vars: {} }], flags: MCP },
  { name: "eager-mcp-base", group: "mcp-eager", fixture: "empty", turns: [OK], flags: MCP, env: { ENABLE_TOOL_SEARCH: "false" } },
  { name: "eager-mcp-w100", group: "mcp-eager", fixture: "empty", turns: [mcpTurn("w100")], flags: MCP, env: { ENABLE_TOOL_SEARCH: "false" } },
  { name: "tool-tiny-default", group: "tool-result", fixture: "tooldata", turns: [bash("cat tiny.txt")] },
  { name: "multi-turn", group: "user-multi", fixture: "empty", turns: [OK, userTurn(200, "T2"), userTurn(800, "T3")], flags: S },
  { name: "multi-turn-default", group: "user-multi", fixture: "empty", turns: [OK, userTurn(200, "T2"), userTurn(800, "T3")] },
  { name: "pre-default", group: "preamble", fixture: "empty", turns: [OK] },
  { name: "pre-tools-none", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--tools", ""] },
  { name: "pre-tools-bash", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--tools", "Bash"] },
  { name: "pre-tools-bash-read", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--tools", "Bash,Read"] },
  { name: "pre-no-skills", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--disable-slash-commands"] },
  { name: "pre-sys-replace", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--system-prompt", "You are a test."] },
  { name: "pre-exclude-dynamic", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--exclude-dynamic-system-prompt-sections"] },
  { name: "pre-floor", group: "preamble", fixture: "empty", turns: [OK], flags: [...S, "--tools", "", "--disable-slash-commands", "--system-prompt", "You are a test."] },
];

function cleanEnv(extra: Record<string, string> = {}): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const [k, v] of Object.entries(process.env)) if (!/^CLAUDE/.test(k)) env[k] = v;
  // Keep git from finding the repo above the fixture, so the git status snapshot cannot change between runs.
  return { ...env, ...ISOLATION_ENV, GIT_CEILING_DIRECTORIES: INVESTIGATION_DIR, ...extra };
}

// ---------- one claude -p process ----------
const usageOf = (u: any) => u ? { input: u.input_tokens ?? 0, cache_creation: u.cache_creation_input_tokens ?? 0, cache_read: u.cache_read_input_tokens ?? 0, output: u.output_tokens ?? 0 } : null;
// every numeric field whose key mentions "token", keyed by "<entry type>.<path>" (arrays collapsed to [])
function tokenFields(o: any, prefix: string, out: Record<string, number>) {
  if (!o || typeof o !== "object") return;
  for (const [k, v] of Object.entries(o)) {
    const p = Array.isArray(o) ? `${prefix}[]` : `${prefix}.${k}`;
    if (typeof v === "number" && /token/i.test(k)) out[p] = (out[p] ?? 0) + 1;
    else if (v && typeof v === "object") tokenFields(v, p, out);
  }
}

async function runProcess(name: string, scn: Scn, mode: Mode, turn: number, prompt: string, resumeId: string | null) {
  const logPath = join(RESULTS_DIR, `${name}.t${turn}.jsonl`);
  const settingsPath = join(RESULTS_DIR, `${name}.settings.json`);
  writeFileSync(logPath, "");
  if (turn === 1) writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
  const args = [
    "-p", "--output-format", "stream-json", "--verbose", ...(mode === "partial" ? ["--include-partial-messages"] : []),
    ...(resumeId ? ["--resume", resumeId] : []),
    "--model", MODEL, "--effort", EFFORT,
    "--setting-sources", "project", "--settings", settingsPath,
    "--allowedTools", "Bash,Skill,mcp__datamcp__lookup", "--permission-mode", "dontAsk",
    ...(scn.flags ?? []),
  ];
  const t0 = Date.now();
  const log = (ev: any) => appendFileSync(logPath, JSON.stringify({ t: Date.now() - t0, ...ev }) + "\n");
  const child = spawn(CLAUDE, args, { cwd: join(FIXTURES, scn.fixture), env: cleanEnv(scn.env), stdio: ["pipe", "pipe", "pipe"] });
  child.stdin.end(prompt);
  let stderr = "";
  child.stderr.on("data", (d) => (stderr += String(d)));
  const timeout = setTimeout(() => { log({ runner: "HARD_TIMEOUT" }); child.kill(); }, 8 * 60_000);

  const calls = new Map<string, any>(); const order: string[] = [];
  const call = (id: string) => { if (!calls.has(id)) { calls.set(id, { id, start: null, assistant: [], delta_output: [], transcript: [], stop_reason: null, blocks: [] }); order.push(id); } return calls.get(id)!; };
  let cur: string | null = null, sessionId: string | undefined, result: any = null, init: any = null;
  const streamTokenFields: Record<string, number> = {};
  const eventCounts: Record<string, number> = {};
  createInterface({ input: child.stdout }).on("line", (line) => {
    let a: any; try { a = JSON.parse(line); } catch { log({ unparsed: line.slice(0, 300) }); return; }
    const key = a.type === "stream_event" ? `stream_event:${a.event?.type}` : `${a.type}${a.subtype ? ":" + a.subtype : ""}`;
    eventCounts[key] = (eventCounts[key] ?? 0) + 1;
    tokenFields(a, key, streamTokenFields);
    if (a.type === "stream_event" && a.event?.type === "content_block_delta") {
      const d = a.event.delta ?? {}; log({ type: "stream_event", event: { type: "content_block_delta", index: a.event.index, delta_type: d.type, len: String(d.text ?? d.thinking ?? d.partial_json ?? "").length } });
    } else log(a);
    if (a.type === "system" && a.subtype === "init") { sessionId = a.session_id; init = a; recordClaudeVersion("cli", a.claude_code_version); }
    else if (a.type === "assistant" && a.message?.id) {
      const c = call(a.message.id); c.assistant.push(usageOf(a.message.usage)); c.blocks.push(...(a.message.content ?? []).map((b: any) => b.type)); c.model = a.message.model;
    } else if (a.type === "stream_event") {
      const e = a.event ?? {};
      if (e.type === "message_start" && e.message?.id) { cur = e.message.id; call(cur!).start = usageOf(e.message.usage); }
      else if (e.type === "message_delta" && cur) { call(cur).delta_output.push(e.usage?.output_tokens ?? null); call(cur).stop_reason = e.delta?.stop_reason ?? null; }
    } else if (a.type === "result") result = a;
  });
  const exitCode: number | null = await new Promise((r) => child.on("close", (c) => r(c)));
  clearTimeout(timeout);

  // session file: usage per message.id, token fields per entry type, and where each marker text sits
  const sessionTokenFields: Record<string, number> = {};
  const markers: Record<string, string[]> = {};
  const sessionFile = sessionId ? join(SESSIONS_DIR, `${sessionId}.jsonl`) : null;
  const entryTypes: Record<string, number> = {};
  if (sessionFile && existsSync(sessionFile)) {
    for (const l of readFileSync(sessionFile, "utf8").split("\n").filter(Boolean)) {
      let e: any; try { e = JSON.parse(l); } catch { continue; }
      const et = e.type === "attachment" ? `attachment:${e.attachment?.type}` : e.type;
      entryTypes[et] = (entryTypes[et] ?? 0) + 1;
      tokenFields(e, et, sessionTokenFields);
      if (e.type === "assistant" && e.message?.id) call(e.message.id).transcript.push(usageOf(e.message.usage));
      for (const m of l.match(/(USER_MARK_\w+|CLAUDEMD_MARK_\w+|SKILLBODY_\w+|TOOLDATA_MARK_\w+)/g) ?? []) (markers[m] ??= []).includes(et) || markers[m].push(et);
    }
  }
  return { turn, args: args.filter((x) => !x.startsWith("/") ), prompt_chars: prompt.length, prompt_words: wc(prompt), sessionId, sessionFile, exitCode, stderr: stderr.slice(0, 500),
    init: init ? { tools: init.tools?.length, skills: init.skills, slash_commands: init.slash_commands?.length, mcp_servers: init.mcp_servers, keys: Object.keys(init), claude_code_version: init.claude_code_version } : null,
    calls: order.map((id) => calls.get(id)), result: result ? { usage: result.usage, modelUsage: result.modelUsage, total_cost_usd: result.total_cost_usd, num_turns: result.num_turns, subtype: result.subtype, keys: Object.keys(result) } : null,
    eventCounts, streamTokenFields, sessionTokenFields, entryTypes, markers };
}

async function runScenario(scn: Scn, mode: Mode, rep: number) {
  const name = `${scn.name}-${mode}-r${rep}`;
  const procs: any[] = []; let sessionId: string | null = null;
  for (let i = 0; i < scn.turns.length; i++) {
    const p = await runProcess(name, scn, mode, i + 1, loadPrompt(scn.turns[i].tpl, scn.turns[i].vars), sessionId);
    procs.push(p); sessionId = p.sessionId ?? sessionId;
    if (!p.result) break;
  }
  console.log(`${name}: ${procs.map((p) => p.calls.map((c: any) => { const u = c.start ?? c.assistant[0] ?? c.transcript[0]; return u ? u.input + u.cache_creation + u.cache_read : "?"; }).join("/")).join(" | ")}`);
  return { name, scenario: scn.name, group: scn.group, mode, rep, fixture: scn.fixture, flags: scn.flags ?? [], procs };
}

async function main() {
  beginRun();
  const argv = process.argv.slice(2);
  let reps = 2, concurrency = 4, modes: Mode[] = ["plain", "partial"]; const only: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--reps") reps = Number(argv[++i]); else if (argv[i] === "--concurrency") concurrency = Number(argv[++i]);
    else if (argv[i] === "--modes") modes = argv[++i].split(",") as Mode[]; else only.push(argv[i]);
  }
  buildFixtures();
  const list = SCENARIOS.filter((s) => !only.length || only.includes(s.name));
  const jobs: (() => Promise<any>)[] = [];
  for (let r = 1; r <= reps; r++) for (const s of list) for (const m of modes) jobs.push(() => runScenario(s, m, r));
  const runs: any[] = []; let next = 0;
  await Promise.all(Array.from({ length: concurrency }, async () => { while (next < jobs.length) { const j = jobs[next++]; runs.push(await j()); } }));
  runs.sort((a, b) => a.name.localeCompare(b.name));
  const fixtureSizes = Object.fromEntries([["user-w200", wc(userTurn(200).vars.filler)], ["user-w800", wc(userTurn(800).vars.filler)]]);
  writeFileSync(join(RESULTS_DIR, "runs.json"), JSON.stringify({ model: MODEL, effort: EFFORT, fixtureSizes, runs }, null, 2));
  writeSummary("attribution-summary.md", `${runs.length} runs (${list.length} scenarios × ${modes.join("+")} × ${reps} reps). Raw data: runs.json. Run \`npx tsx investigations/prompt-token-attribution/analyze.ts\` for the attribution tables.\n\nPrompt size per call (input+cache_creation+cache_read, first source available):\n\n` +
    runs.map((r) => `- ${r.name}: ${r.procs.map((p: any) => p.calls.map((c: any) => { const u = c.start ?? c.assistant[0] ?? c.transcript[0]; return u ? u.input + u.cache_creation + u.cache_read : "?"; }).join("/")).join(" | ")}`).join("\n") + "\n");
}
main().catch((e) => { console.error(e); process.exit(1); });

// Minimal stdio MCP server for the token-attribution investigation.
// One tool, `lookup`, returns the text of one of the data files of the tooldata fixture (argv[2] = that folder).
// The server also sends `instructions` in its initialize result, so their token cost can be measured.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { createInterface } from "node:readline";

const DIR = process.argv[2];
const FILES = { tiny: "tiny.txt", w100: "data-w100.txt", w800: "data-w800.txt" };
const INSTRUCTIONS = "MCPINSTR_MARK. This server serves reference notes about village keepers, workshops and bakeries. Use the lookup tool when a note is requested by its short name. Notes are plain text. Prefer one lookup per note and do not repeat a lookup whose answer you already have.";
const send = (msg) => process.stdout.write(JSON.stringify({ jsonrpc: "2.0", ...msg }) + "\n");

createInterface({ input: process.stdin }).on("line", (line) => {
  let m;
  try { m = JSON.parse(line); } catch { return; }
  if (m.method === "initialize") {
    send({ id: m.id, result: { protocolVersion: m.params?.protocolVersion ?? "2025-06-18", capabilities: { tools: {} }, serverInfo: { name: "datamcp", version: "1.0.0" }, instructions: INSTRUCTIONS } });
  } else if (m.method === "tools/list") {
    send({ id: m.id, result: { tools: [{
      name: "lookup",
      description: "Return the text of a reference note by short name (tiny, w100 or w800).",
      inputSchema: { type: "object", properties: { name: { type: "string", enum: Object.keys(FILES) } }, required: ["name"] },
    }] } });
  } else if (m.method === "tools/call") {
    const file = FILES[m.params?.arguments?.name];
    if (!file) send({ id: m.id, result: { isError: true, content: [{ type: "text", text: "unknown note" }] } });
    else send({ id: m.id, result: { content: [{ type: "text", text: readFileSync(join(DIR, file), "utf8") }] } });
  } else if (m.id !== undefined) {
    send({ id: m.id, error: { code: -32601, message: `unsupported: ${m.method}` } });
  }
});

/**
 * The one-shot nested matrix of experiment.ts (1shot-* scenarios), WITHOUT the Agent SDK: headless `claude -p`.
 *
 *   direct:  main --Agent(fg|bg)--> slow-worker
 *   nested:  main --Agent(outer fg|bg)--> launcher --Agent(inner fg|bg)--> slow-worker
 *
 * sync/async comes from the prompt alone (no hook changes any input); task_started.is_backgrounded records the mode
 * the CLI actually used. Command hooks (hook-log.mjs) only append their input to a log.
 * The prompt goes on stdin, which then closes: one-shot, the CLI alone decides when to exit.
 *
 * Usage:  npx tsx investigations/subagent-background-behaviour/nested-cli.ts [scenario ...]   (default: all six)
 */
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync, appendFileSync, readFileSync, existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline";
import { ISOLATION_ENV, ISOLATION_SETTINGS, SESSIONS_DIR, RESULTS_DIR, LIB_DIR, loadPrompt, latestRunDir, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";

type Mode = "fg" | "bg";
type Scenario = { name: string; outer: Mode; inner: Mode; direct?: boolean; sdk: string };

// sdk = the matching experiment.ts scenario, for the side-by-side comparison
const ALL: Scenario[] = [
  { name: "cli-direct-fg", outer: "fg", inner: "fg", direct: true, sdk: "1shot-direct-fg" },
  { name: "cli-direct-bg", outer: "bg", inner: "bg", direct: true, sdk: "1shot-direct-bg" },
  { name: "cli-fg-fg", outer: "fg", inner: "fg", sdk: "1shot-fg-fg" },
  { name: "cli-fg-bg", outer: "fg", inner: "bg", sdk: "1shot-fg-bg" },
  { name: "cli-bg-fg", outer: "bg", inner: "fg", sdk: "1shot-bg-fg" },
  { name: "cli-bg-bg", outer: "bg", inner: "bg", sdk: "1shot-bg-bg" },
];

const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
const PROJECT_LOGS = SESSIONS_DIR;
const TOKEN_RE = /WORKER_TOKEN=\d+/;

// same template as experiment.ts
function mainPrompt(s: Scenario): string {
  return loadPrompt("nested-main", { direct: !!s.direct, busy_main: !!(s as any).busyMain, outer_bg: s.outer === "bg", inner_bg: s.inner === "bg" });
}

/** The CLI inherits this process's env: drop the parent Claude Code session's own variables. */
function cleanEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const [k, v] of Object.entries(process.env)) if (!/^CLAUDE/.test(k)) env[k] = v;
  return { ...env, ...ISOLATION_ENV, CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "3" };
}

function hooksSettings(hookLog: string) {
  const cmd = `node "${join(LIB_DIR, "hook-log.mjs").replace(/\\/g, "/")}" "${hookLog.replace(/\\/g, "/")}"`;
  const h = [{ hooks: [{ type: "command", command: cmd }] }];
  return {
    ...ISOLATION_SETTINGS,
    hooks: {
      SubagentStart: h,
      SubagentStop: h,
      PreToolUse: [{ matcher: "Agent", hooks: [{ type: "command", command: cmd }] }],
      PostToolUse: [{ matcher: "Agent|Bash", hooks: [{ type: "command", command: cmd }] }],
    },
  };
}

async function runScenario(s: Scenario) {
  const logPath = join(RESULTS_DIR, `${s.name}.jsonl`);
  const hookLog = join(RESULTS_DIR, `${s.name}.hooks.jsonl`);
  const settingsPath = join(RESULTS_DIR, `${s.name}.settings.json`);
  writeFileSync(logPath, "");
  writeFileSync(hookLog, "");
  writeFileSync(settingsPath, JSON.stringify(hooksSettings(hookLog), null, 2));
  const args = [
    "-p", "--output-format", "stream-json", "--verbose", "--model", "sonnet",
    "--setting-sources", "project", "--settings", settingsPath,
    "--allowedTools", "Agent", "Bash", "--permission-mode", "dontAsk",
  ];

  const t0 = Date.now();
  const now = () => Date.now() - t0;
  const log = (src: string, event: string, data: Record<string, unknown> = {}) => {
    const t = now();
    appendFileSync(logPath, JSON.stringify({ t, src, event, ...data }) + "\n");
    const brief = Object.entries(data)
      .map(([k, v]) => `${k}=${typeof v === "string" ? JSON.stringify(v.length > 100 ? v.slice(0, 100) + "…" : v) : JSON.stringify(v)}`)
      .join(" ");
    console.log(`[${s.name}] ${(t / 1000).toFixed(1).padStart(6)}s  ${src.padEnd(6)} ${event.padEnd(22)} ${brief}`);
  };

  const child = spawn(CLAUDE, args, { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
  child.stdin.end(mainPrompt(s));
  child.stderr.on("data", (d) => log("stderr", "line", { text: String(d).trim() }));
  const timeout = setTimeout(() => { log("runner", "HARD_TIMEOUT"); child.kill(); }, 6 * 60_000);

  let sessionId: string | undefined;
  let cliVersion: string | undefined;
  const taskBg = new Map<string, { type: string; bg: boolean; depth?: number }>();
  const results: { t: number; origin: string; text: string }[] = [];

  createInterface({ input: child.stdout }).on("line", (line) => {
    let a: any;
    try { a = JSON.parse(line); } catch { return; }
    if (a.type === "system" && a.subtype === "init") {
      sessionId = a.session_id; cliVersion = a.claude_code_version;
      recordClaudeVersion("cli", a.claude_code_version);
      log("stream", "system:init", { cli: a.claude_code_version, model: a.model });
    } else if (a.type === "system" && a.subtype === "task_started" && a.subagent_type) {
      taskBg.set(a.task_id, { type: a.subagent_type, bg: a.is_backgrounded, depth: a.spawn_depth });
      log("stream", "task_started", { agent: a.subagent_type, is_backgrounded: a.is_backgrounded, spawn_depth: a.spawn_depth });
    } else if (a.type === "system" && a.subtype === "task_notification" && taskBg.has(a.task_id)) {
      log("stream", "task_notification", { agent: taskBg.get(a.task_id)!.type, status: a.status, summary: a.summary });
    } else if (a.type === "assistant" && !a.parent_tool_use_id) {
      for (const b of a.message?.content ?? []) {
        if (b.type === "tool_use") log("stream", "main tool_use", { name: b.name, input: b.input });
        if (b.type === "text") log("stream", "main text", { text: b.text });
      }
    } else if (a.type === "result") {
      results.push({ t: now(), origin: a.origin?.kind ?? "prompt", text: a.result ?? "" });
      log("stream", "RESULT", { origin: a.origin?.kind ?? "prompt", result: a.result, cost: a.total_cost_usd });
    }
  });
  const exitCode: number | null = await new Promise((r) => child.on("close", (c) => r(c)));
  clearTimeout(timeout);
  const exited = now();
  log("runner", "claude -p exited", { code: exitCode });

  // ---- hook log -> timeline ----
  const hooks = readFileSync(hookLog, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
  const stops: Record<string, { t: number; last: string }[]> = {};
  const requestedBg: Record<string, boolean | undefined> = {};
  let workerToken: string | undefined;
  for (const h of hooks) {
    const t = h.t_epoch - t0;
    if (h.hook_event_name === "SubagentStop") (stops[h.agent_type] ??= []).push({ t, last: h.last_assistant_message ?? "" });
    if (h.hook_event_name === "PreToolUse") requestedBg[h.agent_id ? h.agent_type : "main"] = h.tool_input?.run_in_background;
    if (h.hook_event_name === "PostToolUse" && h.tool_name === "Bash") workerToken ??= JSON.stringify(h.tool_response ?? "").match(TOKEN_RE)?.[0];
    appendFileSync(logPath, JSON.stringify({ t, src: "hook", event: h.hook_event_name, agent: h.agent_type ?? "main", tool: h.tool_name }) + "\n");
  }

  // ---- session logs: main + launcher transcripts ----
  const mainLog = sessionId ? join(PROJECT_LOGS, `${sessionId}.jsonl`) : "";
  let launcherTranscript: { notifications: number; has_token: boolean } | null = null;
  const subDir = sessionId ? join(PROJECT_LOGS, sessionId, "subagents") : "";
  for (const [id, info] of taskBg)
    if (info.type === "launcher" && existsSync(join(subDir, `agent-${id}.jsonl`))) {
      const raw = readFileSync(join(subDir, `agent-${id}.jsonl`), "utf8");
      launcherTranscript = { notifications: raw.split("<task-notification>").length - 1, has_token: !!workerToken && raw.includes(workerToken) };
    }
  let tokenInMainLogVia: string | null = null;
  if (workerToken && existsSync(mainLog))
    for (const l of readFileSync(mainLog, "utf8").split("\n").filter(Boolean)) {
      const e = JSON.parse(l);
      if (e.type === "user" && !e.isSidechain && JSON.stringify(e.message ?? "").includes(workerToken)) {
        tokenInMainLogVia = e.origin?.kind === "task-notification" ? "task-notification turn" : "Agent tool result";
        break;
      }
    }

  const modeOf = (type: string) => [...taskBg.values()].find((v) => v.type === type)?.bg ?? null;
  const tokenResult = workerToken ? results.find((r) => r.text.includes(workerToken!)) : undefined;
  const lStop = stops["launcher"]?.[0];
  const wStop = stops["slow-worker"]?.[stops["slow-worker"].length - 1];
  const verdict = {
    scenario: s.name,
    driver: "claude -p (no SDK)",
    cli_version: cliVersion ?? null,
    chain: s.direct ? `main →${s.outer} worker` : `main →${s.outer} launcher →${s.inner} worker`,
    requested_run_in_background: requestedBg,
    launcher_is_backgrounded: s.direct ? null : modeOf("launcher"),
    worker_is_backgrounded: modeOf("slow-worker"),
    modes_as_intended:
      (s.direct || modeOf("launcher") === (s.outer === "bg")) && modeOf("slow-worker") === ((s.direct ? s.outer : s.inner) === "bg"),
    worker_token: workerToken ?? null,
    launcher_end_s: lStop ? lStop.t / 1000 : null,
    launcher_stop_count: stops["launcher"]?.length ?? 0,
    launcher_final_message: lStop?.last ?? null,
    launcher_got_token: s.direct ? null : !!workerToken && (stops["launcher"] ?? []).some((x) => x.last.includes(workerToken!)),
    launcher_transcript: launcherTranscript,
    worker_end_s: wStop ? wStop.t / 1000 : null,
    results: results.map((r) => ({ at_s: r.t / 1000, origin: r.origin, text: r.text })),
    token_reached_main: !!tokenResult,
    token_reached_main_how: tokenResult ? (tokenResult.origin === "prompt" ? "sync" : "callback") : null,
    token_in_main_log_via: tokenInMainLogVia,
    token_reached_main_at_s: tokenResult ? tokenResult.t / 1000 : null,
    process_exited_s: exited / 1000,
    exit_code: exitCode,
    main_log: mainLog,
  };
  writeFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), JSON.stringify(verdict, null, 2));
  console.log(`\n[${s.name}] VERDICT\n${JSON.stringify(verdict, null, 2)}\n`);
  return verdict;
}

async function main() {
  beginRun();
  mkdirSync(RESULTS_DIR, { recursive: true });
  const names = process.argv.slice(2);
  for (const s of names.length ? ALL.filter((x) => names.includes(x.name)) : ALL) await runScenario(s);

  const sdkDir = latestRunDir("experiment");
  const read = (dir: string | null, n: string) => { if (!dir) return null; try { return JSON.parse(readFileSync(join(dir, `${n}.verdict.json`), "utf8")); } catch { return null; } };
  const sdkHow = (v: any) => !v?.main?.token_reached_main ? "never" : v.main.token_reached_main_in_turn === "prompt" ? "sync" : "callback";
  const rows = ALL.map((s) => {
    const c = read(RESULTS_DIR, s.name), k = read(sdkDir, s.sdk);
    if (!c) return null;
    const sdkTokenAt = k?.main?.results?.find((r: any) => TOKEN_RE.test(r.text))?.at_s ?? "-";
    const cliLauncher = s.direct ? "–" : `${c.launcher_end_s}s, ${c.launcher_got_token ? "got token" : "no token"}`;
    const sdkLauncher = s.direct ? "–" : k ? `${k.launcher_first_stop_s}s, ${k.launcher_final_message_has_token ? "got token" : "no token"}` : "-";
    return `| ${c.chain} | ${c.modes_as_intended ? "yes" : "**NO**"} | ${cliLauncher} | ${sdkLauncher} | ${c.worker_end_s} / ${k?.worker_stop_s ?? "-"} | ` +
      `${c.token_reached_main_how ?? "**never**"} / ${sdkHow(k)} | ${c.token_reached_main_at_s ?? "-"} / ${sdkTokenAt} | ${c.process_exited_s} / ${k?.main?.query_iterator_ended_s ?? "-"} |`;
  }).filter(Boolean);
  const md = [
    "## Nested matrix, one-shot: headless `claude -p` vs Agent SDK",
    "",
    `Pairs are \`claude -p\` / SDK. Times in seconds from start. SDK values come from the experiment.ts \`1shot-*\` runs in results/${sdkDir ? sdkDir.split(/[\\/]/).pop() : "(none found)"}.`,
    "",
    "| chain | modes as intended (cli) | launcher ended, cli | launcher ended, SDK | worker ended | token reached main | token in main at | session ended |",
    "|---|---|---|---|---|---|---|---|",
    ...rows,
  ].join("\n");
  writeSummary("nested-cli-summary.md", md);
  console.log(md);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Offline (no model calls): the exact tokens of a real Claude Code session, read from its session files, compared
 * with the estimates of a CAIP-report (`resources/session-analyzers/claude-code/report.mjs`, the `.json` it writes
 * beside its HTML).
 *
 * From the files: every `assistant` entry of <session>.jsonl and of each subagents/agent-<id>.jsonl, deduplicated by
 * message.id (`<synthetic>` entries left out), plus each agent's .meta.json (agentType, description, toolUseId).
 * Checks:
 *   - files are consistent: every entry of one message carries the same output_tokens, with output_tokens_details
 *     and a stop_reason (no provisional values);
 *   - the per-model sum over all files equals the last cost-state of the main file;
 *   - per API call, the file's output_tokens against the report's callLog[].out, the call matched by its exact prompt
 *     (input / cache_read / cache_creation).
 *
 * Usage:  npx tsx investigations/stream-json-output-tokens/session-vs-report.ts [<session>.jsonl <CAIP-report>.json]
 *         (default: the sample in samples/8cb96fe0/). Subagent files are looked up in <dir>/<session-id>/subagents/
 *         (Claude Code's layout) or <dir>/subagents/ (the sample's).
 */
import { readFileSync, readdirSync, existsSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { INVESTIGATION_DIR, RESULTS_DIR, beginRun, writeSummary } from "../../lib/claude-home.mjs";

const DEFAULT_SESSION = join(INVESTIGATION_DIR, "samples", "8cb96fe0", "8cb96fe0-c2f4-48ec-9875-cfbe43c0e91b.jsonl");
const DEFAULT_REPORT = join(INVESTIGATION_DIR, "samples", "8cb96fe0", "CAIP-report-8cb96fe0.json");

const readJsonl = (f: string): any[] => readFileSync(f, "utf8").split("\n").filter(Boolean).flatMap((l) => { try { return [JSON.parse(l)]; } catch { return []; } });

type M = { id: string; model: string; outs: (number | null)[]; stops: (string | null)[]; thinking: number | null; details: boolean[]; blocks: string[]; u: any };

function main() {
  beginRun();
  const [sessionArg, reportArg] = process.argv.slice(2);
  const sessionFile = resolve(sessionArg ?? DEFAULT_SESSION);
  const reportFile = resolve(reportArg ?? DEFAULT_REPORT);
  const sid = basename(sessionFile, ".jsonl");
  const subDir = [join(dirname(sessionFile), sid, "subagents"), join(dirname(sessionFile), "subagents")].find(existsSync);
  const agents = [{ agent: "main", file: sessionFile, meta: null as any },
    ...(subDir ? readdirSync(subDir).filter((x) => x.endsWith(".jsonl")).map((x) => {
      const metaFile = join(subDir, x.replace(/\.jsonl$/, ".meta.json"));
      return { agent: x.slice(6, -6), file: join(subDir, x), meta: existsSync(metaFile) ? JSON.parse(readFileSync(metaFile, "utf8")) : null };
    }) : [])];
  const report = JSON.parse(readFileSync(reportFile, "utf8"));

  const versions = new Set<string>();
  let lastCost: any = null, costStates = 0;
  const filesByModel: Record<string, { output: number; thinking: number; input: number; cache_read: number; cache_write: number }> = {};
  const rows = agents.map(({ agent, file, meta }) => {
    const msgs = new Map<string, M>();
    for (const e of readJsonl(file)) {
      if (e.version) versions.add(e.version);
      if (e.type === "cost-state") { lastCost = e; costStates++; }
      if (e.type !== "assistant" || !e.message?.id) continue;
      const m = msgs.get(e.message.id) ?? { id: e.message.id, model: e.message.model, outs: [], stops: [], thinking: null, details: [], blocks: [], u: null };
      m.outs.push(e.message.usage?.output_tokens ?? null); m.stops.push(e.message.stop_reason ?? null);
      m.details.push(!!e.message.usage?.output_tokens_details);
      m.thinking = e.message.usage?.output_tokens_details?.thinking_tokens ?? m.thinking;
      m.blocks.push((e.message.content ?? []).map((b: any) => b.type).join("+")); m.u = e.message.usage;
      msgs.set(e.message.id, m);
    }
    const real = [...msgs.values()].filter((m) => m.model !== "<synthetic>");
    for (const m of real) {
      const t = (filesByModel[m.model] ??= { output: 0, thinking: 0, input: 0, cache_read: 0, cache_write: 0 });
      t.output += m.u.output_tokens ?? 0; t.thinking += m.thinking ?? 0; t.input += m.u.input_tokens ?? 0;
      t.cache_read += m.u.cache_read_input_tokens ?? 0; t.cache_write += m.u.cache_creation_input_tokens ?? 0;
    }
    const row = report.rows?.find((r: any) => r.id === agent);
    const calls: any[] = row?.callLog ?? [];
    const pairs = real.map((m, i) => {
      const c = calls.find((k) => k.fresh === (m.u.input_tokens ?? 0) && k.read === (m.u.cache_read_input_tokens ?? 0) && k.write === (m.u.cache_creation_input_tokens ?? 0));
      return { n: i + 1, id: m.id, blocks: m.blocks.join(" | "), output: m.u.output_tokens, thinking: m.thinking, report_out: c?.out ?? null, entries: m.outs.length };
    });
    const sum = (f: (p: any) => number) => pairs.reduce((s, p) => s + f(p), 0);
    return {
      agent, agentType: meta?.agentType ?? (agent === "main" ? "main session" : null), description: meta?.description ?? null, toolUseId: meta?.toolUseId ?? null,
      model: [...new Set(real.map((m) => m.model))].join(", "), messages: real.length, synthetic: msgs.size - real.length,
      entries: real.reduce((s, m) => s + m.outs.length, 0),
      provisional: {
        messages_with_differing_outputs: real.filter((m) => new Set(m.outs).size > 1).length,
        messages_without_output_tokens_details: real.filter((m) => !m.details.some(Boolean)).length,
        messages_with_null_stop_reason: real.filter((m) => m.stops.every((s) => s == null)).length,
      },
      output: sum((p) => p.output ?? 0), thinking: sum((p) => p.thinking ?? 0),
      naive_output_over_entries: real.reduce((s, m) => s + m.outs.reduce<number>((a, b) => a + (b ?? 0), 0), 0),
      report: row ? { label: row.agent, calls: calls.length, out_sum: calls.reduce((s, k) => s + (k.out ?? 0), 0) } : null,
      calls_matched: pairs.filter((p) => p.report_out != null).length,
      report_out_matched: sum((p) => p.report_out ?? 0),
      pairs,
    };
  });

  const cs = lastCost ? Object.fromEntries(Object.entries(lastCost.modelUsage ?? {}).map(([k, x]: any) => [k, { output: x.outputTokens, thinking: x.thinkingTokens, input: x.inputTokens, cache_read: x.cacheReadInputTokens, cache_write: x.cacheCreationInputTokens }])) : null;
  const csMatches = cs ? Object.keys({ ...cs, ...filesByModel }).every((k) => JSON.stringify(cs[k]) === JSON.stringify(filesByModel[k])) : null;
  const total = rows.reduce((s, r) => s + r.output, 0), totalReport = rows.reduce((s, r) => s + r.report_out_matched, 0);
  const verdict = {
    session: sid, session_file: sessionFile, report_file: reportFile, claude_code_versions: [...versions],
    cost_states: costStates, files_by_model: filesByModel, last_cost_state_by_model: cs, last_cost_state_equals_files: csMatches,
    output_total_files: total, output_total_report: totalReport, report_over_files: total ? totalReport / total : null,
    rows,
  };
  writeFileSync(join(RESULTS_DIR, `${sid.slice(0, 8)}.verdict.json`), JSON.stringify(verdict, null, 2));

  const pct = (a: number, b: number) => (b ? `${Math.round((a / b) * 100)}%` : "–");
  const md = [
    `## Session \`${sid}\` (Claude Code ${[...versions].join(", ")}): files vs CAIP-report`,
    "",
    `Files: \`${basename(sessionFile)}\` + ${rows.length - 1} subagent file(s). Report: \`${basename(reportFile)}\`.`,
    "",
    `Last cost-state = files (per model, all fields): **${csMatches == null ? "no cost-state" : csMatches ? "✅ exact" : "❌"}**. Output in the files: **${total}**, report estimate: **${totalReport}** (${pct(totalReport, total)}).`,
    "",
    "| agent | type | description | msgs | entries | provisional values | output (files) | of which thinking | naive Σ over entries | report out (matched calls) | report / files |",
    "|---|---|---|---|---|---|---|---|---|---|---|",
    ...rows.map((r) => `| ${r.agent} | ${r.agentType ?? "–"} | ${r.description ?? "–"} | ${r.messages} | ${r.entries} | ${r.provisional.messages_with_differing_outputs + r.provisional.messages_without_output_tokens_details + r.provisional.messages_with_null_stop_reason === 0 ? "none" : JSON.stringify(r.provisional)} | ${r.output} | ${r.thinking} | ${r.naive_output_over_entries} | ${r.report_out_matched} (${r.calls_matched}/${r.report?.calls ?? 0}) | ${pct(r.report_out_matched, r.output)} |`),
    "",
    "### Per API call",
    "",
    "| agent | # | blocks | output (files) | thinking | report out | report / (output − thinking) |",
    "|---|---|---|---|---|---|---|",
    ...rows.flatMap((r) => r.pairs.map((p: any) => `| ${r.agent.slice(0, 8)} | ${p.n} | ${p.blocks} | ${p.output} | ${p.thinking ?? 0} | ${p.report_out ?? "–"} | ${p.report_out == null ? "–" : pct(p.report_out, p.output - (p.thinking ?? 0))} |`)),
  ].join("\n");
  writeSummary("session-vs-report-summary.md", md);
  console.log(md.split("\n").slice(0, 10 + rows.length).join("\n"));
}

main();

// Command hook for the `claude -p` experiment: appends the hook input, stamped with the wall clock, to the file
// given as argv[2]. It prints nothing and exits 0, so it never changes what Claude Code does.
import { appendFileSync } from "node:fs";

let raw = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (c) => (raw += c));
process.stdin.on("end", () => {
  const t_epoch = Date.now();
  try {
    appendFileSync(process.argv[2], JSON.stringify({ t_epoch, ...JSON.parse(raw) }) + "\n");
  } catch {}
  process.exit(0);
});

/**
 * Shared logic of usage-sdk.ts and usage-cli.ts: the plan-usage readers, the fixed workload conversation and the
 * scenarios. A driver picks the mode ("sdk" or "cli"); this module does the rest.
 *
 * Readers (every reading is stored raw in <scenario>.jsonl and summarised in <scenario>.verdict.json):
 *   sdk  query.usage_EXPERIMENTAL_MAY_CHANGE_DO_NOT_RELY_ON_THIS_API_YET({ skipBehaviors: true }) on a query whose
 *        streaming input never sends a prompt (so the reading itself makes no model call).
 *   cli  `claude -p "/usage"` (stream-json): whatever the slash command prints in headless mode.
 *   ref  GET https://api.anthropic.com/api/oauth/usage with the run's OAuth token. Not a Claude Code channel: the
 *        reference ("ground truth") the Claude Code channels are compared with.
 * During the workload, every rate_limit_event of the stream is kept (channel B), and afterwards the session
 * transcripts are scanned for anything rate-limit related (channel D).
 */
import { query } from "@anthropic-ai/claude-agent-sdk";
import { spawn } from "node:child_process";
import { appendFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline";
import { CONFIG_DIR, ISOLATION_ENV, ISOLATION_SETTINGS, RESULTS_DIR, SESSIONS_DIR, loadPrompt, recordClaudeVersion } from "../../lib/claude-home.mjs";

export type Mode = "sdk" | "cli";
export type ScenarioName = "baseline" | "before-after" | "after-only";

const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
const MODEL = "opus";
const TOPICS = [
  "the history of lighthouses and the people who kept them",
  "how medieval cathedrals were engineered without modern mathematics",
  "the economics and logistics of the spice trade across the Indian Ocean",
];
/**
 * Reads after the workload, in seconds after it ends (USAGE_SETTLE="0,30,90" to see whether the endpoint lags).
 * Default one read: the usage endpoint answers 429 with a ~1 h retry-after once a bearer has asked too often.
 */
const SETTLE_S = (process.env.USAGE_SETTLE ?? "0").split(",").map(Number);

const cleanEnv = () => ({ ...Object.fromEntries(Object.entries(process.env).filter(([k]) => !/^CLAUDE/.test(k))), ...ISOLATION_ENV }) as NodeJS.ProcessEnv;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

let LOG = "";
let T0 = 0;
function log(event: string, data: Record<string, unknown> = {}) {
  const t = Date.now() - T0;
  appendFileSync(LOG, JSON.stringify({ t, event, ...data }) + "\n");
  console.log(`${(t / 1000).toFixed(1).padStart(7)}s  ${event.padEnd(22)} ${JSON.stringify(data).slice(0, 220)}`);
}

// ---------------------------------------------------------------- readers

/** Normalised view of a reading: utilization per window (0-100) and its reset time. */
type Windows = Record<string, { utilization: number | null; resets_at: string | null }>;
type Reading = { channel: "sdk" | "cli" | "probe" | "ref"; label: string; t: number; ok: boolean; windows: Windows | null; error?: string; raw?: unknown; model_calls?: unknown; ground_truth_only?: boolean };

function windowsFromRateLimits(rl: any): Windows | null {
  if (!rl || typeof rl !== "object") return null;
  const out: Windows = {};
  for (const [k, v] of Object.entries<any>(rl)) {
    if (k === "model_scoped" && Array.isArray(v)) for (const m of v) out[`model:${m.display_name}`] = { utilization: m.utilization ?? null, resets_at: m.resets_at ?? null };
    else if (k === "extra_usage") { if (v) out.extra_usage = { utilization: v.utilization ?? null, resets_at: null }; }
    else if (v && typeof v === "object" && "utilization" in v) out[k] = { utilization: v.utilization ?? null, resets_at: v.resets_at ?? null };
  }
  return out;
}

async function readSdk(label: string): Promise<Reading> {
  const t = Date.now() - T0;
  let release!: () => void;
  const done = new Promise<void>((r) => (release = r));
  async function* noPrompt() { await done; }
  // The debug log shows the CLI's own fetchUtilization lines: why rate_limits is null when it is.
  const debugFile = join(RESULTS_DIR, `sdk-read-${label.replace(/[^\w+-]/g, "_")}.debug.log`);
  const q = query({ prompt: noPrompt() as any, options: { cwd: process.cwd(), settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(), permissionMode: "dontAsk", allowedTools: [], debugFile } });
  const drain = (async () => { try { for await (const m of q as AsyncIterable<any>) if (m.type === "system" && m.subtype === "init") recordClaudeVersion("sdk", m.claude_code_version); } catch { /* closed */ } })();
  let r: Reading;
  try {
    const raw: any = await Promise.race([
      (q as any).usage_EXPERIMENTAL_MAY_CHANGE_DO_NOT_RELY_ON_THIS_API_YET({ skipBehaviors: true }),
      sleep(60_000).then(() => { throw new Error("timeout 60s"); }),
    ]);
    r = { channel: "sdk", label, t, ok: !!raw?.rate_limits_available, windows: windowsFromRateLimits(raw?.rate_limits), raw, model_calls: raw?.session?.model_usage };
  } catch (e: any) {
    r = { channel: "sdk", label, t, ok: false, windows: null, error: String(e?.message ?? e) };
  }
  release(); q.close(); await Promise.race([drain, sleep(5000)]);
  try { (r as any).debug_usage_lines = readFileSync(debugFile, "utf8").split("\n").filter((l) => /utilization|oauth\/usage|usage endpoint|429|rate.?limit/i.test(l)).map((l) => l.slice(0, 400)); } catch { /* no debug file */ }
  log(`read:sdk:${label}`, r as any);
  return r;
}

async function readCli(label: string): Promise<Reading> {
  const t = Date.now() - T0;
  const settingsPath = join(RESULTS_DIR, "cli-read.settings.json");
  if (!existsSync(settingsPath)) writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
  const events: any[] = [];
  const child = spawn(CLAUDE, ["-p", "/usage", "--output-format", "stream-json", "--verbose", "--setting-sources", "project", "--settings", settingsPath, "--permission-mode", "dontAsk"],
    { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
  child.stdin.end();
  let stderr = "";
  child.stderr.on("data", (d) => (stderr += d));
  createInterface({ input: child.stdout }).on("line", (l) => { try { events.push(JSON.parse(l)); } catch { /* not json */ } });
  const timer = setTimeout(() => child.kill(), 90_000);
  const code = await new Promise((r) => child.on("close", r));
  clearTimeout(timer);
  const init = events.find((e) => e.type === "system" && e.subtype === "init");
  if (init) recordClaudeVersion("cli", init.claude_code_version);
  const result = events.find((e) => e.type === "result");
  const text = [result?.result, ...events.filter((e) => e.type === "system" && e.subtype !== "init").map((e) => JSON.stringify(e))].filter(Boolean).join("\n");
  const windows = parseUsageText(text);
  const r: Reading = { channel: "cli", label, t, ok: !!windows && Object.keys(windows).length > 0, windows,
    raw: { exit: code, result: result?.result ?? null, result_subtype: result?.subtype ?? null, num_turns: result?.num_turns, event_types: events.map((e) => `${e.type}${e.subtype ? ":" + e.subtype : ""}`), stderr: stderr.trim().slice(0, 1000) || undefined },
    model_calls: result?.modelUsage ?? null };
  log(`read:cli:${label}`, r as any);
  return r;
}

/** Best effort: "<label> ... NN% used" lines of the /usage text. */
function parseUsageText(text: string): Windows | null {
  if (!text) return null;
  const out: Windows = {};
  const lines = text.split(/\r?\n/);
  lines.forEach((line, i) => {
    const m = line.match(/(\d+(?:\.\d+)?)\s*%\s*used/i);
    if (!m) return;
    const label = (line.replace(m[0], "").replace(/[█▌▏░▒▓\-|]+/g, "").trim() || lines[i - 1]?.trim() || `row${i}`).slice(0, 60);
    out[label] = { utilization: Number(m[1]), resets_at: (lines[i + 1]?.match(/reset[^\n]*/i)?.[0] ?? null) };
  });
  return Object.keys(out).length ? out : null;
}

async function readRef(label: string): Promise<Reading> {
  const t = Date.now() - T0;
  let r: Reading;
  try {
    const token = JSON.parse(readFileSync(join(CONFIG_DIR, ".credentials.json"), "utf8")).claudeAiOauth?.accessToken;
    const res = await fetch("https://api.anthropic.com/api/oauth/usage", {
      headers: { Authorization: `Bearer ${token}`, "anthropic-beta": "oauth-2025-04-20", "Content-Type": "application/json" },
    });
    const body: any = await res.json().catch(() => null);
    r = { channel: "ref", label, t, ok: res.ok, windows: res.ok ? windowsFromRateLimits(body) : null, raw: res.ok ? body : { status: res.status, body } };
  } catch (e: any) {
    r = { channel: "ref", label, t, ok: false, windows: null, error: String(e?.message ?? e) };
  }
  log(`read:ref:${label}`, r as any);
  return r;
}

/**
 * Channel B as a reader: a one-word Haiku request in a new session; its rate_limit_event carries
 * unifiedWindows.<window>.utilization (a 0-1 fraction, stored here x100 to compare with the 0-100 readers).
 */
async function readProbe(mode: Mode, label: string): Promise<Reading> {
  const t = Date.now() - T0;
  const events: any[] = [];
  let modelUsage: unknown = null;
  const onEvent = (m: any) => {
    if (m.type === "system" && m.subtype === "init") recordClaudeVersion(mode, m.claude_code_version);
    else if (m.type === "rate_limit_event") events.push(m.rate_limit_info);
    else if (m.type === "result") modelUsage = m.modelUsage ?? null;
  };
  const prompt = "Reply with the single word OK.";
  if (mode === "sdk") {
    const q = query({ prompt, options: { cwd: process.cwd(), model: "haiku", settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(), permissionMode: "dontAsk", allowedTools: [], maxTurns: 1, persistSession: false } as any });
    for await (const m of q as AsyncIterable<any>) onEvent(m);
  } else {
    const child = spawn(CLAUDE, ["-p", prompt, "--output-format", "stream-json", "--verbose", "--model", "haiku", "--max-turns", "1", "--no-session-persistence",
      "--setting-sources", "project", "--settings", JSON.stringify(ISOLATION_SETTINGS), "--permission-mode", "dontAsk"], { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
    child.stdin.end();
    createInterface({ input: child.stdout }).on("line", (l) => { try { onEvent(JSON.parse(l)); } catch { /* not json */ } });
    await new Promise((r) => child.on("close", r));
  }
  const uw = events.find((e) => e.unifiedWindows)?.unifiedWindows;
  const windows: Windows | null = uw ? Object.fromEntries(Object.entries<any>(uw).map(([k, v]) => [k, {
    utilization: typeof v.utilization === "number" ? Math.round(v.utilization * 10000) / 100 : null,
    resets_at: v.resetsAt ? new Date(v.resetsAt * 1000).toISOString() : null }])) : null;
  const r: Reading = { channel: "probe", label, t, ok: !!windows, windows, raw: { rate_limit_events: events }, model_calls: modelUsage };
  log(`read:probe:${label}`, r as any);
  return r;
}

// ---------------------------------------------------------------- workload

type Workload = { session_id: string | null; turns: number; rate_limit_events: any[]; model_usage: Record<string, any>; cost_usd: number; output_chars: number; t_start: number; t_end: number; errors: string[] };

async function runWorkload(mode: Mode, turns: number): Promise<Workload> {
  const w: Workload = { session_id: null, turns, rate_limit_events: [], model_usage: {}, cost_usd: 0, output_chars: 0, t_start: Date.now() - T0, t_end: 0, errors: [] };
  const addUsage = (mu: Record<string, any> | undefined) => {
    for (const [model, u] of Object.entries(mu ?? {})) {
      const acc = (w.model_usage[model] ??= {});
      for (const [k, v] of Object.entries<any>(u)) if (typeof v === "number") acc[k] = (acc[k] ?? 0) + v;
    }
  };
  for (let i = 0; i < turns; i++) {
    const prompt = loadPrompt("workload", { topic: TOPICS[i % TOPICS.length] });
    const onEvent = (m: any) => {
      if (m.type === "system" && m.subtype === "init") { w.session_id ??= m.session_id; recordClaudeVersion(mode, m.claude_code_version); log("workload:init", { turn: i + 1, version: m.claude_code_version, model: m.model }); }
      else if (m.type === "rate_limit_event") { w.rate_limit_events.push({ t: Date.now() - T0, turn: i + 1, ...m.rate_limit_info }); log("workload:rate_limit_event", m.rate_limit_info); }
      else if (m.type === "result") {
        w.cost_usd += m.total_cost_usd ?? 0; addUsage(m.modelUsage); w.output_chars += String(m.result ?? "").length;
        if (m.is_error) w.errors.push(`${m.subtype}: ${String(m.result ?? "").slice(0, 300)}`);
        log("workload:result", { turn: i + 1, subtype: m.subtype, cost: m.total_cost_usd, usage: m.usage });
      }
    };
    if (mode === "sdk") {
      const q = query({ prompt, options: { cwd: process.cwd(), model: MODEL, settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(),
        permissionMode: "dontAsk", allowedTools: [], maxTurns: 1, ...(w.session_id ? { resume: w.session_id } : {}) } });
      for await (const m of q as AsyncIterable<any>) onEvent(m);
    } else {
      const settingsPath = join(RESULTS_DIR, "workload.settings.json");
      if (!existsSync(settingsPath)) writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
      const args = ["-p", "--output-format", "stream-json", "--verbose", "--model", MODEL, "--setting-sources", "project", "--settings", settingsPath,
        "--permission-mode", "dontAsk", "--max-turns", "1", ...(w.session_id ? ["--resume", w.session_id] : [])];
      const child = spawn(CLAUDE, args, { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
      child.stdin.end(prompt);
      child.stderr.on("data", (d) => log("workload:stderr", { text: String(d).trim().slice(0, 500) }));
      const rl = createInterface({ input: child.stdout });
      rl.on("line", (l) => { try { onEvent(JSON.parse(l)); } catch { /* not json */ } });
      const timer = setTimeout(() => child.kill(), 10 * 60_000);
      await new Promise((r) => child.on("close", r));
      clearTimeout(timer);
    }
  }
  w.t_end = Date.now() - T0;
  return w;
}

/** Channel D: every line of the session transcript(s) that mentions rate limits or utilization. */
function scanTranscript(sessionId: string | null) {
  if (!sessionId) return { transcript: null, hits: [] as string[] };
  const path = join(SESSIONS_DIR, `${sessionId}.jsonl`);
  if (!existsSync(path)) return { transcript: path, hits: [] };
  const lines = readFileSync(path, "utf8").split("\n").filter(Boolean);
  const hits = lines.filter((l) => /rate_?limit|utilization|ratelimit/i.test(l)).map((l) => l.slice(0, 600));
  const types = [...new Set(lines.map((l) => { try { const e = JSON.parse(l); return `${e.type}${e.subtype ? ":" + e.subtype : ""}`; } catch { return "?"; } }))];
  return { transcript: path, lines: lines.length, entry_types: types, hits };
}

// ---------------------------------------------------------------- scenarios

const delta = (a: Reading | undefined, b: Reading | undefined) => {
  if (!a?.windows || !b?.windows) return null;
  const out: Record<string, number | null> = {};
  for (const k of new Set([...Object.keys(a.windows), ...Object.keys(b.windows)])) {
    const x = a.windows[k]?.utilization, y = b.windows[k]?.utilization;
    out[k] = typeof x === "number" && typeof y === "number" ? Math.round((y - x) * 1000) / 1000 : null;
  }
  return out;
};

export async function runScenario(mode: Mode, name: ScenarioName, turns: number) {
  LOG = join(RESULTS_DIR, `${name}.jsonl`);
  writeFileSync(LOG, "");
  T0 = Date.now();
  const read = mode === "sdk" ? readSdk : readCli;
  const readings: Reading[] = [];
  // The ref channel is opt-in (USAGE_REF=1): it calls the endpoint directly with the copied OAuth token.
  const useRef = process.env.USAGE_REF === "1";
  /** Every channel at one point in time. In after-only, "before" is read by the probe alone, as ground truth only. */
  const readAll = async (label: string, groundTruthOnly = false) => {
    if (!groundTruthOnly) readings.push(await read(label));
    readings.push({ ...(await readProbe(mode, label)), ground_truth_only: groundTruthOnly });
    if (useRef) readings.push({ ...(await readRef(label)), ground_truth_only: groundTruthOnly });
  };

  let workload: Workload | null = null;
  if (name === "baseline") {
    // No workload: is each channel available, does a reading itself consume anything, how stable is it?
    await readAll("t0"); await sleep(30_000); await readAll("t0+30s");
  } else {
    await readAll("before", name === "after-only");
    workload = await runWorkload(mode, turns);
    let last = 0;
    for (const s of SETTLE_S) { await sleep((s - last) * 1000); last = s; await readAll(`after+${s}s`); }
  }

  const pick = (ch: Reading["channel"], label: string) => readings.find((r) => r.channel === ch && r.label === label);
  const firstLabel = name === "baseline" ? "t0" : "before";
  const lastLabel = name === "baseline" ? "t0+30s" : `after+${SETTLE_S[SETTLE_S.length - 1]}s`;
  const channels = [...new Set(readings.map((r) => r.channel))];
  // after-only reconstruction of "before": the first rate_limit_event of the workload (state before its first request).
  const firstUw = workload?.rate_limit_events.find((e) => e.unifiedWindows)?.unifiedWindows;
  const reconstructedBefore: Windows | null = firstUw ? Object.fromEntries(Object.entries<any>(firstUw).map(([k, v]) => [k, { utilization: Math.round(v.utilization * 10000) / 100, resets_at: null }])) : null;
  const verdict = {
    scenario: name, mode, turns: workload ? turns : 0, model: MODEL, ref_channel_used: useRef,
    channel_ok: Object.fromEntries(channels.map((c) => [c, readings.filter((r) => r.channel === c).map((r) => `${r.label}${r.ground_truth_only ? "(gt)" : ""}:${r.ok}`)])),
    deltas: Object.fromEntries(channels.map((c) => [c, delta(pick(c, firstLabel), pick(c, lastLabel))])),
    delta_ref_by_settle: !useRef || name === "baseline" ? null : Object.fromEntries(SETTLE_S.map((s) => [`after+${s}s`, delta(pick("ref", "before"), pick("ref", `after+${s}s`))])),
    reconstructed_before_from_first_event: reconstructedBefore,
    probe_before: pick("probe", "before")?.windows ?? null,
    reconstruction_matches_probe_before: reconstructedBefore && pick("probe", "before")?.windows
      ? Object.entries(reconstructedBefore).every(([k, v]) => pick("probe", "before")!.windows![k]?.utilization === v.utilization) : null,
    readings: readings.map((r) => ({ channel: r.channel, label: r.label, ground_truth_only: !!r.ground_truth_only, t: r.t, ok: r.ok, windows: r.windows, error: r.error,
      sdk_rate_limits_available: r.channel === "sdk" ? (r.raw as any)?.rate_limits_available : undefined,
      sdk_debug_usage_lines: (r as any).debug_usage_lines, cli_usage_text: r.channel === "cli" ? (r.raw as any)?.result : undefined, model_calls: r.model_calls ?? null })),
    workload: workload && { session_id: workload.session_id, duration_s: (workload.t_end - workload.t_start) / 1000, cost_usd_equiv: workload.cost_usd, model_usage: workload.model_usage, output_chars: workload.output_chars, errors: workload.errors },
    rate_limit_events: workload?.rate_limit_events ?? null,
    transcript_scan: workload ? scanTranscript(workload.session_id) : null,
  };
  writeFileSync(join(RESULTS_DIR, `${name}.verdict.json`), JSON.stringify(verdict, null, 2));
  return verdict;
}

const fmt = (d: Record<string, number | null> | null) => (d ? Object.entries(d).filter(([, v]) => v !== null).map(([k, v]) => `${k} ${v! >= 0 ? "+" : ""}${v}`).join(", ") || "no numeric window" : "n/a");

const win = (w: Windows | null | undefined) => (w ? Object.entries(w).map(([k, v]) => `${k} ${v.utilization ?? "∅"}`).join(", ") : "null");

export function renderSummary(mode: Mode, vs: Awaited<ReturnType<typeof runScenario>>[]) {
  const ch = mode === "sdk" ? "`usage_EXPERIMENTAL…()`" : "`claude -p /usage`";
  return [
