/**
 * When an agent preloads skills with the `skills` frontmatter property, is the skill's frontmatter put in context or
 * only its body? Headless `claude -p` (installed CLI). Scenarios: subagent via the Agent tool, or the agent run as the
 * main thread with `--agent`.
 * Usage:  npx tsx investigations/subagent-preloaded-skill-frontmatter/skill-frontmatter-cli.ts [scenario ...]
 */
import { spawn } from "node:child_process";
import { writeFileSync, appendFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline";
import { ISOLATION_ENV, ISOLATION_SETTINGS, SESSIONS_DIR, RESULTS_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";
import { ALL, judge, renderSummary, type Scenario } from "./judge.ts";

const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
const cleanEnv = () => ({ ...Object.fromEntries(Object.entries(process.env).filter(([k]) => !/^CLAUDE/.test(k))), ...ISOLATION_ENV }) as NodeJS.ProcessEnv;

async function runScenario(s: Scenario) {
  const logPath = join(RESULTS_DIR, `${s.name}.jsonl`);
  const settingsPath = join(RESULTS_DIR, `${s.name}.settings.json`);
  writeFileSync(logPath, "");
  writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
  const probe = loadPrompt("probe").replace(/\s+/g, " ").trim();
  const prompt = s.mode === "subagent" ? loadPrompt("main", { agent: s.agent, probe }) : probe;
  const args = ["-p", "--output-format", "stream-json", "--verbose", "--model", "haiku", "--setting-sources", "project", "--settings", settingsPath,
    "--allowedTools", "Agent", "Glob", "--permission-mode", "dontAsk", ...(s.mode === "main" ? ["--agent", s.agent] : [])];
  const t0 = Date.now();
  const log = (event: string, data: Record<string, unknown> = {}) => {
    appendFileSync(logPath, JSON.stringify({ t: Date.now() - t0, event, ...data }) + "\n");
    console.log(`[${s.name}] ${event}`, JSON.stringify(data).slice(0, 200));
  };
  const child = spawn(CLAUDE, args, { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
  child.stdin.end(prompt);
  child.stderr.on("data", (d) => log("stderr", { text: String(d).trim() }));
  const timeout = setTimeout(() => { log("HARD_TIMEOUT"); child.kill(); }, 4 * 60_000);
  let sessionId: string | undefined, cliVersion: string | undefined, finalResult = "", cost: number | undefined;
  const toolCalls: string[] = [];
  const rl = createInterface({ input: child.stdout });
  const rlClosed = new Promise((r) => rl.once("close", r));
  rl.on("line", (line) => {
    let a: any; try { a = JSON.parse(line); } catch { return; }
    if (a.type === "system" && a.subtype === "init") { sessionId = a.session_id; cliVersion = a.claude_code_version; recordClaudeVersion("cli", cliVersion); log("system:init", { cli: cliVersion }); }
    else if (a.type === "assistant") {
      for (const b of a.message?.content ?? []) if (b.type === "tool_use") {
      // the main thread's own Agent call is not an agent tool call; everything else (or anything with a parent) is
      if (a.parent_tool_use_id || s.mode === "main") toolCalls.push(`${b.name} ${JSON.stringify(b.input)}`);
      log("tool_use", { parent: !!a.parent_tool_use_id, name: b.name });
      }
    }
    else if (a.type === "result") { finalResult = a.result || finalResult; cost = a.total_cost_usd; log("RESULT", { result: a.result, cost }); }
  });
  const exitCode: number | null = await new Promise((r) => child.on("close", (c) => r(c)));
  await rlClosed;
  clearTimeout(timeout);
  const verdict = { scenario: s.name, driver: "claude -p", cli_version: cliVersion ?? null, mode: s.mode, agent: s.agent, skills: s.skills, note: s.note,
    ...judge(s, sessionId, finalResult, toolCalls), final_answer: finalResult, cost_usd: cost ?? null, exit_code: exitCode,
    session_log: sessionId ? join(SESSIONS_DIR, `${sessionId}.jsonl`) : null };
  writeFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), JSON.stringify(verdict, null, 2));
  console.log(JSON.stringify(verdict, null, 2));
  return verdict;
}

async function main() {
  beginRun();
  const names = process.argv.slice(2);
  const vs = [];
  for (const s of names.length ? ALL.filter((x) => names.includes(x.name)) : ALL) vs.push(await runScenario(s));
  const md = renderSummary("claude -p", vs);
  writeSummary("skill-frontmatter-cli-summary.md", md);
  console.log(md);
}
main().catch((e) => { console.error(e); process.exit(1); });

