 * Usage:  npx tsx investigations/subagent-preloaded-skill-frontmatter/skill-frontmatter-sdk.ts [scenario ...]
 */
import { query } from "@anthropic-ai/claude-agent-sdk";
import { writeFileSync, appendFileSync } from "node:fs";
import { join } from "node:path";
import { ISOLATION_ENV, ISOLATION_SETTINGS, SESSIONS_DIR, RESULTS_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";
import { ALL, judge, renderSummary, type Scenario } from "./judge.ts";

async function runScenario(s: Scenario) {
  const logPath = join(RESULTS_DIR, `${s.name}.jsonl`);
  writeFileSync(logPath, "");
  const probe = loadPrompt("probe").replace(/\s+/g, " ").trim();
  const prompt = s.mode === "subagent" ? loadPrompt("main", { agent: s.agent, probe }) : probe;
  const t0 = Date.now();
  const log = (event: string, data: Record<string, unknown> = {}) => {
    appendFileSync(logPath, JSON.stringify({ t: Date.now() - t0, event, ...data }) + "\n");
    console.log(`[${s.name}] ${event}`, JSON.stringify(data).slice(0, 200));
  };
  let sessionId: string | undefined, sdkVersion: string | undefined, finalResult = "", cost: number | undefined;
  const toolCalls: string[] = [];
  const q = query({
    prompt,
    options: {
      cwd: process.cwd(), model: "haiku", settingSources: ["project"], settings: ISOLATION_SETTINGS,
      allowedTools: ["Agent", "Glob"], permissionMode: "dontAsk",
      env: { ...process.env, ...ISOLATION_ENV },
      ...(s.mode === "main" ? { agent: s.agent } : {}),
    },
  });
  const timeout = setTimeout(() => { log("HARD_TIMEOUT"); q.interrupt(); }, 4 * 60_000);
  for await (const m of q as AsyncIterable<any>) {
    log("msg", { type: m.type, subtype: m.subtype, sub: !!m.parent_tool_use_id });
    if (m.type === "system" && m.subtype === "init") { sessionId = m.session_id; sdkVersion = m.claude_code_version; recordClaudeVersion("sdk", sdkVersion!); log("system:init", { sdk_cli: sdkVersion }); }
    else if (m.type === "assistant") {
      for (const b of m.message?.content ?? []) if (b.type === "tool_use") {
      if (m.parent_tool_use_id || s.mode === "main") toolCalls.push(`${b.name} ${JSON.stringify(b.input)}`);
      log("tool_use", { parent: !!m.parent_tool_use_id, name: b.name });
      }
    }
    else if (m.type === "result") { finalResult = m.result || finalResult; cost = m.total_cost_usd; log("RESULT", { result: m.result, cost }); }
  }
  clearTimeout(timeout);
  const verdict = { scenario: s.name, driver: "Agent SDK", claude_code_version: sdkVersion ?? null, mode: s.mode, agent: s.agent, skills: s.skills, note: s.note,
    ...judge(s, sessionId, finalResult, toolCalls), final_answer: finalResult, cost_usd: cost ?? null,
    session_log: sessionId ? join(SESSIONS_DIR, `${sessionId}.jsonl`) : null };
  writeFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), JSON.stringify(verdict, null, 2));
  console.log(JSON.stringify(verdict, null, 2));
  return verdict;
}

async function main() {
  beginRun();
  const names = process.argv.slice(2);
  const vs = [];
  for (const s of names.length ? ALL.filter((x) => names.includes(x.name)) : ALL) vs.push(await runScenario(s));
  const md = renderSummary("Agent SDK", vs);
  writeSummary("skill-frontmatter-sdk-summary.md", md);
