1	/**
2	 * Parallel foreground fan-out: can the prompt alone make main issue N Agent tool calls in ONE message,
3	 * and do N foreground (sync) workers then run in parallel while main blocks until all have finished?
4	 *
5	 * No hook changes any tool input: hooks here only record timings. Foreground is forced the documented way:
6	 *   CLAUDE_CODE_DISABLE_BACKGROUND_TASKS=1  (every subagent runs in the foreground)
7	 *   CLAUDE_CODE_FORK_SUBAGENT=0             (fork mode off)
8	 *
9	 * Usage:  npx tsx investigations/subagent-background-behaviour/parallel.ts [runs=1] [workers=5]
10	 */
11	import { query, type HookCallback, type SDKMessage } from "@anthropic-ai/claude-agent-sdk";
12	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from "node:fs";
13	import { join } from "node:path";
14	import { ISOLATION_ENV, ISOLATION_SETTINGS, RESULTS_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";
15	
16	const RUNS = Number(process.argv[2] ?? 1);
17	const N = Number(process.argv[3] ?? 5);
18	const TOKEN_RE_G = /WORKER_TOKEN=\d+/g;
19	
20	function mainPrompt(): string {
21	  return loadPrompt("parallel-main", { n: N });
22	}
23	
24	/** The SDK's child inherits this process's env: drop the parent Claude Code session's own variables. */
25	function cleanEnv(): Record<string, string | undefined> {
26	  const env: Record<string, string | undefined> = {};
27	  for (const [k, v] of Object.entries(process.env)) if (!/^CLAUDE/.test(k)) env[k] = v;
28	  return { ...env, ...ISOLATION_ENV, CLAUDE_CODE_DISABLE_BACKGROUND_TASKS: "1", CLAUDE_CODE_FORK_SUBAGENT: "0" };
29	}
30	
31	async function runOnce(run: number) {
32	  const name = `parallel-${N}-run${run}`;
33	  const t0 = Date.now();
34	  const logPath = join(RESULTS_DIR, `${name}.jsonl`);
35	  writeFileSync(logPath, "");
36	  const now = () => Date.now() - t0;
37	  const log = (src: string, event: string, data: Record<string, unknown> = {}) => {
38	    const t = now();
39	    appendFileSync(logPath, JSON.stringify({ t, src, event, ...data }) + "\n");
40	    const brief = Object.entries(data)
41	      .map(([k, v]) => `${k}=${typeof v === "string" ? JSON.stringify(v.length > 110 ? v.slice(0, 110) + "…" : v) : JSON.stringify(v)}`)
42	      .join(" ");
43	    console.log(`[${name}] ${(t / 1000).toFixed(1).padStart(6)}s  ${src.padEnd(6)} ${event.padEnd(24)} ${brief}`);
44	  };
45	
46	  let transcriptPath: string | undefined;
47	  const agentToolUsesByMessage = new Map<string, string[]>(); // main assistant message.id -> Agent tool_use ids
48	  const workers = new Map<string, { start?: number; end?: number; bg?: boolean; token?: string }>();
49	  const mainAgentReturns: number[] = [];
50	  const results: { t: number; origin: string; text: string; num_turns: number }[] = [];
51	  const toolResultMessages: { t: number; count: number }[] = [];
52	  const w = (id: string) => workers.get(id) ?? (workers.set(id, {}), workers.get(id)!);
53	
54	  // observers only: every hook returns {} and changes nothing
55	  const pre: HookCallback = async (input: any) => {
56	    if (!input.agent_id) transcriptPath = input.transcript_path;
57	    log("hook", "PreToolUse(Agent)", { caller: input.agent_id ? input.agent_type : "main", input: input.tool_input });
58	    return {};
59	  };
60	  const post: HookCallback = async (input: any) => {
61	    const text = JSON.stringify(input.tool_response ?? "");
62	    if (input.tool_name === "Agent" && !input.agent_id) {
63	      mainAgentReturns.push(now());
64	      log("hook", "PostToolUse(Agent)", { caller: "main", returned: (text.match(TOKEN_RE_G) ?? []).join(" ") });
65	    } else if (input.agent_id) {
66	      const tok = text.match(TOKEN_RE_G)?.[0];
67	      if (tok) w(input.agent_id).token = tok;
68	      log("hook", `PostToolUse(${input.tool_name})`, { caller: input.agent_type, agent_id: input.agent_id, token: tok });
69	    }
70	    return {};
71	  };
72	  const subStart: HookCallback = async (input: any) => {
73	    w(input.agent_id).start = now();
74	    log("hook", "SubagentStart", { agent: input.agent_type, agent_id: input.agent_id });
75	    return {};
76	  };
77	  const subStop: HookCallback = async (input: any) => {
78	    w(input.agent_id).end = now();
79	    log("hook", "SubagentStop", { agent: input.agent_type, agent_id: input.agent_id, last: input.last_assistant_message });
80	    return {};
81	  };
82	
83	  const q = query({
84	    prompt: mainPrompt(), // one-shot: the CLI alone decides when the session ends
85	    options: {
86	      cwd: process.cwd(),
87	      model: "sonnet",
88	      settingSources: ["project"],
89	      settings: ISOLATION_SETTINGS,
90	      allowedTools: ["Agent", "Bash"],
91	      permissionMode: "dontAsk",
92	      env: cleanEnv(),
93	      hooks: {
94	        PreToolUse: [{ matcher: "Agent", hooks: [pre] }],
95	        PostToolUse: [{ hooks: [post] }],
96	        SubagentStart: [{ hooks: [subStart] }],
97	        SubagentStop: [{ hooks: [subStop] }],
98	      },
99	    },
100	  });
101	  const timeout = setTimeout(() => { log("runner", "HARD_TIMEOUT"); q.close(); }, 8 * 60_000);
102	
103	  for await (const m of q as AsyncIterable<SDKMessage>) {
104	    const a = m as any;
105	    if (m.type === "system" && a.subtype === "init") {
106	      recordClaudeVersion("sdk", a.claude_code_version);
107	      log("stream", "system:init", { cli: a.claude_code_version, model: a.model });
108	    } else if (m.type === "system" && a.subtype === "task_started" && a.subagent_type === "slow-worker") {
109	      w(a.task_id).bg = a.is_backgrounded;
110	      log("stream", "task_started", { agent: a.subagent_type, task_id: a.task_id, is_backgrounded: a.is_backgrounded, spawn_depth: a.spawn_depth });
111	    } else if (m.type === "system" && a.subtype === "task_notification") {
112	      log("stream", "task_notification", { task_id: a.task_id, status: a.status, summary: a.summary });
113	    } else if (m.type === "assistant" && !a.parent_tool_use_id) {
114	      for (const b of a.message?.content ?? []) {
115	        if (b.type === "tool_use") {
116	          const ids = agentToolUsesByMessage.get(a.message.id) ?? [];
117	          if (b.name === "Agent") ids.push(b.id);
118	          agentToolUsesByMessage.set(a.message.id, ids);
119	          log("stream", "main tool_use", { message_id: a.message.id, name: b.name, input: b.input });
120	        } else if (b.type === "text") log("stream", "main text", { message_id: a.message.id, text: b.text });
121	      }
122	    } else if (m.type === "user" && !a.parent_tool_use_id) {
123	      const content = Array.isArray(a.message?.content) ? a.message.content : [];
124	      const n = content.filter((b: any) => b.type === "tool_result").length;
125	      if (n) toolResultMessages.push({ t: now(), count: n });
126	      log("stream", "main user", { tool_results: n, origin: a.origin?.kind });
127	    } else if (m.type === "result") {
128	      results.push({ t: now(), origin: a.origin?.kind ?? "prompt", text: a.result ?? "", num_turns: a.num_turns });
129	      log("stream", "RESULT", { origin: a.origin?.kind ?? "prompt", num_turns: a.num_turns, result: a.result, cost: a.total_cost_usd });
130	    }
131	  }
132	  clearTimeout(timeout);
133	  const sessionEnd = now();
134	
135	  // ---- verdict ----
136	  const ws = [...workers.entries()].filter(([, v]) => v.start !== undefined);
137	  const starts = ws.map(([, v]) => v.start!);
138	  const ends = ws.map(([, v]) => v.end ?? Infinity);
139	  const workerTokens = ws.map(([, v]) => v.token).filter(Boolean) as string[];
140	  const firstResult = results[0];
141	  const mainTokens = firstResult ? [...new Set(firstResult.text.match(TOKEN_RE_G) ?? [])] : [];
142	  const durations = ws.map(([, v]) => (v.end ?? 0) - v.start!);
143	  const sumDur = durations.reduce((x, y) => x + y, 0);
144	  const wall = Math.max(...ends) - Math.min(...starts);
145	  const groups = [...agentToolUsesByMessage.entries()].filter(([, ids]) => ids.length);
146	
147	  const verdict = {
148	    run: name,
149	    env: { CLAUDE_CODE_DISABLE_BACKGROUND_TASKS: "1", CLAUDE_CODE_FORK_SUBAGENT: "0" },
150	    hooks_modify_input: false,
151	    // 1. steering: N Agent calls in one assistant message
152	    agent_calls_per_main_message: groups.map(([id, ids]) => ({ message_id: id, agent_calls: ids.length })),
153	    check1_all_calls_in_one_message: groups.length === 1 && groups[0][1].length === N,
154	    // 2. all foreground
155	    workers_started: ws.length,
156	    workers_is_backgrounded: ws.map(([, v]) => v.bg),
157	    check2_all_foreground: ws.length === N && ws.every(([, v]) => v.bg === false),
158	    // 3. main blocked until all finished
159	    worker_tokens: workerTokens,
160	    main_tokens_in_first_result: mainTokens,
161	    check3_main_has_all_tokens_in_first_result:
162	      workerTokens.length === N && workerTokens.every((t) => mainTokens.includes(t)) && firstResult?.origin === "prompt",
163	    main_agent_calls_returned_s: mainAgentReturns.map((t) => t / 1000),
164	    tool_result_messages: toolResultMessages.map((x) => ({ at_s: x.t / 1000, tool_results: x.count })),
165	    first_result_s: firstResult ? firstResult.t / 1000 : null,
166	    last_worker_end_s: Math.max(...ends) / 1000,
167	    results: results.map((r) => ({ at_s: r.t / 1000, origin: r.origin, num_turns: r.num_turns })),
168	    // 4. parallelism
169	    worker_start_spread_s: (Math.max(...starts) - Math.min(...starts)) / 1000,
170	    all_overlap: Math.max(...starts) < Math.min(...ends),
171	    worker_durations_s: durations.map((d) => d / 1000),
172	    wall_clock_all_workers_s: wall / 1000,
173	    sum_of_worker_durations_s: sumDur / 1000,
174	    check4_parallel: Math.max(...starts) < Math.min(...ends) && wall < 0.5 * sumDur,
175	    session_ended_s: sessionEnd / 1000,
176	    transcript: transcriptPath ?? null,
177	  };
178	  writeFileSync(join(RESULTS_DIR, `${name}.verdict.json`), JSON.stringify(verdict, null, 2));
179	  console.log(`\n[${name}] VERDICT\n${JSON.stringify(verdict, null, 2)}\n`);
180	  return verdict;
181	}
182	
183	async function main() {
184	  beginRun();
185	  mkdirSync(RESULTS_DIR, { recursive: true });
186	  const verdicts = [];
187	  for (let r = 1; r <= RUNS; r++) verdicts.push(await runOnce(r));
188	  const yn = (b: boolean) => (b ? "PASS" : "**FAIL**");
189	  const md = [
190	    `## Parallel foreground fan-out (${N} workers, prompt-steered, no input-changing hooks)`,
191	    "",
192	    "| run | 1. one message with N Agent calls | 2. all foreground | 3. main got all tokens before answering | 4. parallel (start spread / wall / sum of durations, s) | main answered (s) | session ended (s) |",
193	    "|---|---|---|---|---|---|---|",
194	    ...verdicts.map((v) =>
195	      `| ${v.run} | ${yn(v.check1_all_calls_in_one_message)} (${v.agent_calls_per_main_message.map((g) => g.agent_calls).join("+")}) | ` +
196	      `${yn(v.check2_all_foreground)} | ${yn(v.check3_main_has_all_tokens_in_first_result)} (${v.main_tokens_in_first_result.length}/${v.worker_tokens.length}) | ` +
197	      `${yn(v.check4_parallel)} (${v.worker_start_spread_s} / ${v.wall_clock_all_workers_s} / ${v.sum_of_worker_durations_s}) | ${v.first_result_s} | ${v.session_ended_s} |`),
198	  ].join("\n");
199	  writeSummary(`parallel-${N}-summary.md`, md);
200	  console.log(md);
201	}
202	
203	main().catch((e) => {
204	  console.error(e);
205	  process.exit(1);
206	});
