1	/**
2	 * Experiment: in the Agent SDK, does a subagent that launches a nested subagent
3	 * wait for that nested subagent before it finishes?
4	 *
5	 * Docs claim (code.claude.com/docs/en/sub-agents#let-subagents-spawn-their-own-subagents):
6	 *   "In non-interactive mode and the Agent SDK, the launching subagent doesn't wait,
7	 *    so a nested background subagent that finishes after its launcher has ended
8	 *    reports to your main conversation instead."
9	 *
10	 * Topology:  main  --Agent(outer)-->  launcher  --Agent(inner)-->  slow-worker (sleep 40s, returns random token)
11	 *
12	 * Each scenario fixes outer/inner foreground-vs-background. The PreToolUse hook enforces the
13	 * run_in_background value on every Agent call (and records whether the model already chose it),
14	 * and task_started.is_backgrounded confirms the mode the harness actually used.
15	 *
16	 * Usage:  npx tsx investigations/subagent-background-behaviour/experiment.ts [scenario ...]
17	 *   scenarios: fg-bg  fg-fg  bg-bg  bg-fg   (outer-inner). Default: all four.
18	 */
19	import { query, type HookCallback, type SDKMessage, type SDKUserMessage } from "@anthropic-ai/claude-agent-sdk";
20	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { ISOLATION_ENV, ISOLATION_SETTINGS, RESULTS_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";
23	
24	type Mode = "fg" | "bg";
25	/**
26	 * input: how the SDK client feeds the main conversation
27	 *   "open"   streaming input kept open until all background work has drained (default)
28	 *   "close"  streaming input closed as soon as the first result arrives
29	 *   "string" plain string prompt (one-shot, the SDK closes stdin itself)
30	 * busyMain: after the launcher returns, main runs its own 70 s command, so the worker finishes mid-turn
31	 */
32	/** direct: main calls slow-worker itself (no launcher); `outer` is then the worker's mode and `inner` is unused */
33	type Scenario = { name: string; outer: Mode; inner: Mode; input?: "open" | "close" | "string"; busyMain?: boolean; direct?: boolean };
34	
35	const ALL: Scenario[] = [
36	  { name: "fg-bg", outer: "fg", inner: "bg" },
37	  { name: "fg-fg", outer: "fg", inner: "fg" },
38	  { name: "bg-bg", outer: "bg", inner: "bg" },
39	  { name: "bg-fg", outer: "bg", inner: "fg" },
40	  // main-conversation behaviour (all with a background worker that outlives its launcher)
41	  { name: "main-busy", outer: "fg", inner: "bg", busyMain: true },
42	  { name: "main-close", outer: "fg", inner: "bg", input: "close" },
43	  { name: "main-string", outer: "fg", inner: "bg", input: "string" },
44	  // main calls the worker directly, no launcher in between
45	  { name: "direct-fg", outer: "fg", inner: "fg", direct: true },
46	  { name: "direct-bg", outer: "bg", inner: "bg", direct: true },
47	  // one-shot string prompt: nothing in this script holds the session open, so the CLI alone decides when it ends
48	  { name: "1shot-direct-fg", outer: "fg", inner: "fg", direct: true, input: "string" },
49	  { name: "1shot-direct-bg", outer: "bg", inner: "bg", direct: true, input: "string" },
50	  { name: "1shot-fg-fg", outer: "fg", inner: "fg", input: "string" },
51	  { name: "1shot-fg-bg", outer: "fg", inner: "bg", input: "string" },
52	  { name: "1shot-bg-fg", outer: "bg", inner: "fg", input: "string" },
53	  { name: "1shot-bg-bg", outer: "bg", inner: "bg", input: "string" },
54	];
55	
56	const HARD_TIMEOUT_MS = 6 * 60_000;
57	const QUIET_GRACE_MS = 10_000;
58	
59	const TOKEN_RE = /WORKER_TOKEN=\d+/;
60	
61	function mainPrompt(s: Scenario): string {
62	  return loadPrompt("nested-main", { direct: !!s.direct, busy_main: !!s.busyMain, outer_bg: s.outer === "bg", inner_bg: s.inner === "bg" });
63	}
64	
65	/** Main-thread entries of the session transcript: exactly what the main model was fed, minus static context. */
66	function mainTranscriptExcerpt(path: string): string {
67	  const skip = new Set(["environment", "model", "deferred_tools_delta", "agent_listing_delta", "skill_listing", "total_tokens_reminder",
68	    "session_context", "date", "credential_org", "prompt_snapshot", "mcp_instructions_delta", "remote_session_change"]);
69	  const out: string[] = [];
70	  let raw = "";
71	  try { raw = readFileSync(path, "utf8"); } catch { return `(transcript not found: ${path})`; }
72	  for (const line of raw.split("\n")) {
73	    if (!line.trim()) continue;
74	    const e = JSON.parse(line);
75	    if (["file-history-snapshot", "atis-latch", "last-prompt", "ai-title", "cost-state"].includes(e.type)) continue;
76	    if (e.type === "attachment" && skip.has(e.attachment?.type)) continue;
77	    const c = e.message?.content;
78	    const body = typeof c === "string" ? c
79	      : Array.isArray(c) ? c.map((b: any) => `${b.type}: ${b.text ?? JSON.stringify(b.content ?? b.input)}`).join("\n")
80	      : JSON.stringify({ content: e.content, attachment: e.attachment, operation: e.operation });
81	    const meta = ["origin", "operation"].filter((k) => k in e).map((k) => `${k}=${JSON.stringify(e[k])}`).join(" ");
82	    out.push(`--- ${String(e.timestamp ?? "").slice(11, 23)} ${e.type} ${meta}\n${body}`);
83	  }
84	  return out.join("\n");
85	}
86	
87	async function runScenario(s: Scenario) {
88	  const t0 = Date.now();
89	  const logPath = join(RESULTS_DIR, `${s.name}.jsonl`);
90	  writeFileSync(logPath, "");
91	
92	  const agentTypeById = new Map<string, string>(); // agent_id/task_id -> agent type
93	  const stops: { t: number; type: string; id: string; last: string; bgTasks: number }[] = [];
94	  const taskStarts: Record<string, any> = {};
95	  const taskEnds: Record<string, { t: number; via: string; status?: string }> = {};
96	  const agentToolReturns: { t: number; caller: string; text: string }[] = [];
97	  const mainTexts: { t: number; origin: string; text: string }[] = [];
98	  const hookAdjustments: string[] = [];
99	  let workerToken: string | undefined;
100	  let lastMsgAt = Date.now();
101	  let resultCount = 0;
102	  let lastWasResult = false;
103	  let liveBgTasks = 0;
104	  let transcriptPath: string | undefined;
105	  const mainResults: { t: number; origin: string; num_turns: number; text: string }[] = [];
106	  const mainInjected: { t: number; origin: string; text: string }[] = [];
107	  let mainAgentReturnAt: number | undefined;
108	  let mainBashReturnAt: number | undefined;
109	
110	  const log =(src: string, event: string, data: Record<string, unknown> = {}) => {
111	    const t = Date.now() - t0;
112	    appendFileSync(logPath, JSON.stringify({ t, src, event, ...data }) + "\n");
113	    const brief = Object.entries(data)
114	      .map(([k, v]) => `${k}=${typeof v === "string" ? JSON.stringify(v.length > 110 ? v.slice(0, 110) + "…" : v) : JSON.stringify(v)}`)
115	      .join(" ");
116	    console.log(`[${s.name}] ${(t / 1000).toFixed(1).padStart(6)}s  ${src.padEnd(6)} ${event.padEnd(26)} ${brief}`);
117	  };
118	  const who = (input: any) => (input.agent_id ? `${input.agent_type ?? agentTypeById.get(input.agent_id) ?? "?"}` : "main");
119	  const textOf = (v: unknown): string =>
120	    typeof v === "string" ? v : Array.isArray(v) ? v.map((b: any) => b?.text ?? "").join("\n") : JSON.stringify(v ?? "");
121	
122	  // ---- hooks: precise timestamps for subagent lifecycle and Agent tool calls ----
123	  const preAgent: HookCallback = async (input: any) => {
124	    const caller = who(input);
125	    if (caller === "main") transcriptPath = input.transcript_path;
126	    const want = caller === "main" ? s.outer === "bg" : s.inner === "bg";
127	    const asked = input.tool_input?.run_in_background;
128	    log("hook", "PreToolUse(Agent)", { caller, subagent_type: input.tool_input?.subagent_type, model_asked_bg: asked, enforced_bg: want });
129	    if (asked !== want) hookAdjustments.push(`${caller}: model asked run_in_background=${asked}, enforced ${want}`);
130	    return {
131	      hookSpecificOutput: {
132	        hookEventName: "PreToolUse",
133	        permissionDecision: "allow",
134	        updatedInput: { ...input.tool_input, run_in_background: want },
135	      },
136	    };
137	  };
138	  const postTool: HookCallback = async (input: any) => {
139	    const caller = who(input);
140	    const text = textOf(input.tool_response?.content ?? input.tool_response);
141	    if (input.tool_name === "Agent") {
142	      agentToolReturns.push({ t: Date.now() - t0, caller, text });
143	      if (caller === "main") mainAgentReturnAt = Date.now() - t0;
144	      log("hook", "PostToolUse(Agent)", { caller, returned: text });
145	    } else {
146	      if (caller === "main") mainBashReturnAt = Date.now() - t0;
147	      const m = text.match(TOKEN_RE) ?? JSON.stringify(input.tool_response ?? "").match(TOKEN_RE);
148	      if (m) workerToken = m[0];
149	      log("hook", `PostToolUse(${input.tool_name})`, { caller, token: m?.[0] });
150	    }
151	    return {};
152	  };
153	  const subStart: HookCallback = async (input: any) => {
154	    agentTypeById.set(input.agent_id, input.agent_type);
155	    log("hook", "SubagentStart", { agent: input.agent_type, agent_id: input.agent_id });
156	    return {};
157	  };
158	  const subStop: HookCallback = async (input: any) => {
159	    const type = input.agent_type ?? agentTypeById.get(input.agent_id) ?? "?";
160	    const last = input.last_assistant_message ?? "";
161	    const bgTasks = (input.background_tasks ?? []).length;
162	    stops.push({ t: Date.now() - t0, type, id: input.agent_id, last, bgTasks });
163	    log("hook", "SubagentStop", { agent: type, last_message: last, in_flight_bg_tasks: bgTasks });
164	    return {};
165	  };
166	
167	  // ---- input: streaming (kept open until drained, or closed after the first result) or a plain string ----
168	  const inputMode = s.input ?? "open";
169	  let finish!: () => void;
170	  const finished = new Promise<void>((r) => (finish = r));
171	  let gotFirstResult!: () => void;
172	  const firstResult = new Promise<void>((r) => (gotFirstResult = r));
173	  async function* input(): AsyncGenerator<SDKUserMessage> {
174	    yield { type: "user", message: { role: "user", content: mainPrompt(s) }, parent_tool_use_id: null };
175	    await (inputMode === "close" ? Promise.race([firstResult, finished]) : finished);
176	    if (inputMode === "close") log("runner", "closing input after first result");
177	  }
178	
179	  const q = query({
180	    prompt: inputMode === "string" ? mainPrompt(s) : input(),
181	    options: {
182	      cwd: process.cwd(),
183	      model: "sonnet",
184	      settingSources: ["project"], // loads .claude/agents/*.md from the investigation folder (the cwd)
185	      settings: ISOLATION_SETTINGS,
186	      allowedTools: ["Agent", "Bash"],
187	      permissionMode: "dontAsk",
188	      env: { ...process.env, ...ISOLATION_ENV, CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "3" },
189	      hooks: {
190	        PreToolUse: [{ matcher: "Agent", hooks: [preAgent] }],
191	        PostToolUse: [{ hooks: [postTool] }],
192	        SubagentStart: [{ hooks: [subStart] }],
193	        SubagentStop: [{ hooks: [subStop] }],
194	      },
195	    },
196	  });
197	
198	  const watchdog = setInterval(() => {
199	    const elapsed = Date.now() - t0;
200	    const allEnded = Object.keys(taskStarts).length >= (s.direct ? 1 : 2) &&Object.keys(taskStarts).every((id) => taskEnds[id]);
201	    if (elapsed > HARD_TIMEOUT_MS) {
202	      log("runner", "HARD_TIMEOUT");
203	      finish();
204	      q.close();
205	    } else if (lastWasResult && allEnded && liveBgTasks === 0 && Date.now() - lastMsgAt > QUIET_GRACE_MS) {
206	      log("runner", "drained; closing input");
207	      finish();
208	    }
209	  }, 1000);
210	
211	  try {
212	    for await (const m of q as AsyncIterable<SDKMessage>) {
213	      lastMsgAt = Date.now();
214	      lastWasResult = m.type === "result";
215	      const anyM = m as any;
216	      if (m.type === "system") {
217	        switch (anyM.subtype) {
218	          case "init":
219	            recordClaudeVersion("sdk", anyM.claude_code_version);
220	            log("stream", "system:init", { cli: anyM.claude_code_version, model: anyM.model, agents: anyM.agents });
221	            break;
222	          case "task_started":
223	            taskStarts[anyM.task_id] = anyM;
224	            if (anyM.subagent_type) agentTypeById.set(anyM.task_id, anyM.subagent_type);
225	            log("stream", "task_started", {
226	              agent: anyM.subagent_type, task_id: anyM.task_id, is_backgrounded: anyM.is_backgrounded,
227	              spawn_depth: anyM.spawn_depth, parent_task: anyM.parent_task_id ? agentTypeById.get(anyM.parent_task_id) ?? anyM.parent_task_id : "main",
228	            });
229	            break;
230	          case "task_updated":
231	            if (["completed", "failed", "killed"].includes(anyM.patch?.status) && !taskEnds[anyM.task_id])
232	              taskEnds[anyM.task_id] = { t: Date.now() - t0, via: "task_updated", status: anyM.patch.status };
233	            log("stream", "task_updated", { agent: agentTypeById.get(anyM.task_id), patch: anyM.patch });
234	            break;
235	          case "task_notification":
236	            if (!taskEnds[anyM.task_id]) taskEnds[anyM.task_id] = { t: Date.now() - t0, via: "task_notification", status: anyM.status };
237	            log("stream", "task_notification", { agent: agentTypeById.get(anyM.task_id), status: anyM.status, summary: anyM.summary });
238	            break;
239	          case "background_tasks_changed":
240	            liveBgTasks = (anyM.tasks ?? []).length;
241	            log("stream", "background_tasks_changed", { live: (anyM.tasks ?? []).map((t: any) => t.subagent_type ?? t.task_type) });
242	            break;
243	          case "task_progress":
244	            break;
245	          default:
246	            log("stream", `system:${anyM.subtype}`);
247	        }
248	      } else if (m.type === "assistant" && !anyM.parent_tool_use_id) {
249	        const text = (anyM.message?.content ?? []).filter((b: any) => b.type === "text").map((b: any) => b.text).join("\n");
250	        for (const b of anyM.message?.content ?? [])
251	          if (b.type === "tool_use") log("stream", "main tool_use", { name: b.name, input: b.input });
252	        if (text) {
253	          mainTexts.push({ t: Date.now() - t0, origin: "assistant", text });
254	          log("stream", "main assistant text", { text });
255	        }
256	      } else if (m.type === "user" && !anyM.parent_tool_use_id) {
257	        const content = anyM.message?.content;
258	        const isToolResult = Array.isArray(content) && content.some((b: any) => b.type === "tool_result");
259	        const text = isToolResult ? textOf(content.map((b: any) => ({ text: textOf(b.content) }))) : textOf(content);
260	        if (!isToolResult) mainInjected.push({ t: Date.now() - t0, origin: anyM.origin?.kind ?? "none", text });
261	        log("stream", isToolResult ? "main user tool_result" : "main user message", { origin: anyM.origin?.kind, synthetic: anyM.isSynthetic, text });
262	      } else if (m.type === "result") {
263	        resultCount++;
264	        const origin = anyM.origin?.kind ?? "prompt";
265	        mainTexts.push({ t: Date.now() - t0, origin, text: anyM.result ?? "" });
266	        mainResults.push({ t: Date.now() - t0, origin, num_turns: anyM.num_turns, text: anyM.result ?? "" });
267	        log("stream", "RESULT", { n: resultCount, subtype: anyM.subtype, origin, num_turns: anyM.num_turns, result: anyM.result, cost: anyM.total_cost_usd });
268	        gotFirstResult();
269	      }
270	    }
271	    log("runner", "query iterator ended");
272	  } catch (e) {
273	    log("runner", "query iterator threw", { error: String(e) });
274	  } finally {
275	    clearInterval(watchdog);
276	    finish();
277	  }
278	  const iteratorEndedAt = Date.now() - t0;
279	
280	  // ---- verdict ----
281	  const idsOf = (type: string) => Object.keys(taskStarts).filter((id) => agentTypeById.get(id) === type);
282	  const launcherId = idsOf("launcher")[0];
283	  const workerId = idsOf("slow-worker")[0];
284	  const launcherStops = stops.filter((x) => x.type === "launcher");
285	  const workerStops = stops.filter((x) => x.type === "slow-worker");
286	  const launcherFirstStop = launcherStops[0];
287	  const launcherLastStop = launcherStops[launcherStops.length - 1];
288	  const workerStop = workerStops[workerStops.length - 1];
289	  const launcherSawToken = launcherStops.some((x) => TOKEN_RE.test(x.last));
290	  const launcherAgentReturn = agentToolReturns.find((r) => r.caller === "launcher");
291	  // result entries carry the turn origin: "prompt" (answer to our prompt) or "task-notification" (injected turn)
292	  const mainSawToken = mainTexts.find((x) => x.origin !== "assistant" && TOKEN_RE.test(x.text));
293	  const notifResults = mainTexts.filter((x) => x.origin === "task-notification");
294	
295	  const verdict = {
296	    scenario: s.name,
297	    direct: !!s.direct,
298	    outer_requested: s.outer,
299	    inner_requested: s.inner,
300	    launcher_is_backgrounded: launcherId ? taskStarts[launcherId].is_backgrounded : null,
301	    worker_is_backgrounded: workerId ? taskStarts[workerId].is_backgrounded : null,
302	    worker_spawn_depth: workerId ? taskStarts[workerId].spawn_depth : null,
303	    worker_token: workerToken ?? null,
304	    launcher_agent_tool_returned_s: launcherAgentReturn ? launcherAgentReturn.t / 1000 : null,
305	    launcher_agent_tool_return_text: launcherAgentReturn?.text.slice(0, 200) ?? null,
306	    launcher_first_stop_s: launcherFirstStop ? launcherFirstStop.t / 1000 : null,
307	    launcher_last_stop_s: launcherLastStop ? launcherLastStop.t / 1000 : null,
308	    launcher_stop_count: launcherStops.length,
309	    worker_stop_s: workerStop ? workerStop.t / 1000 : null,
310	    launcher_ended_before_worker: launcherFirstStop && workerStop ? launcherFirstStop.t < workerStop.t : null,
311	    launcher_final_message_has_token: launcherSawToken,
312	    launcher_final_message: launcherLastStop?.last ?? null,
313	    main_saw_token: !!mainSawToken,
314	    main_saw_token_via: mainSawToken?.origin ?? null,
315	    main_task_notification_turns: notifResults.length,
316	    hook_adjustments: hookAdjustments,
317	    results: resultCount,
318	    launcher_waited_for_worker:
319	      launcherFirstStop && workerStop ? !(launcherFirstStop.t < workerStop.t && !launcherSawToken) : null,
320	    // ---- main conversation ----
321	    main: {
322	      input_mode: inputMode,
323	      busy_main: !!s.busyMain,
324	      blocked_on_launcher_until_s: mainAgentReturnAt !== undefined ? mainAgentReturnAt / 1000 : null,
325	      own_work_returned_s: mainBashReturnAt !== undefined ? mainBashReturnAt / 1000 : null,
326	      results: mainResults.map((r) => ({ at_s: r.t / 1000, origin: r.origin, num_turns: r.num_turns, text: r.text })),
327	      injected_user_messages_on_stream: mainInjected.map((x) => ({ at_s: x.t / 1000, origin: x.origin, text: x.text.slice(0, 300) })),
328	      worker_end_status: workerId ? taskEnds[workerId]?.status ?? "no end event" : "never started",
329	      worker_end_s: workerId && taskEnds[workerId] ? taskEnds[workerId].t / 1000 : null,
330	      token_reached_main: !!mainSawToken,
331	      token_reached_main_in_turn: mainSawToken?.origin ?? null,
332	      token_reached_main_at_s: mainSawToken ? mainSawToken.t / 1000 : null,
333	      query_iterator_ended_s: iteratorEndedAt / 1000,
334	      transcript: transcriptPath ?? null,
335	    },
336	  };
337	  writeFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), JSON.stringify(verdict, null, 2));
338	  if (transcriptPath) writeFileSync(join(RESULTS_DIR, `${s.name}.main-transcript.txt`), mainTranscriptExcerpt(transcriptPath));
339	  console.log(`\n[${s.name}] VERDICT\n${JSON.stringify(verdict, null, 2)}\n`);
340	  return verdict;
341	}
