343	async function main() {
344	  beginRun();
345	  mkdirSync(RESULTS_DIR, { recursive: true });
346	  const names = process.argv.slice(2);
347	  const scenarios = names.length ? ALL.filter((s) => names.includes(s.name)) : ALL;
348	  for (const s of scenarios) await runScenario(s);
349	
350	  // summary covers every scenario that has a verdict on disk, so running a subset keeps the others
351	  const verdicts = ALL.flatMap((s) => {
352	    try { return [JSON.parse(readFileSync(join(RESULTS_DIR, `${s.name}.verdict.json`), "utf8"))]; } catch { return []; }
353	  });
354	  const launcherRows = verdicts.filter((v) => !v.direct).map(
355	    (v) =>
356	      `| ${v.scenario} | ${v.launcher_is_backgrounded} | ${v.worker_is_backgrounded} | ${v.launcher_first_stop_s} | ${v.worker_stop_s} | ` +
357	      `${v.launcher_final_message_has_token} | **${v.launcher_waited_for_worker ? "WAITED" : "DID NOT WAIT"}** |`,
358	  );
359	  const mainRows = verdicts.filter((v) => v.main).map((v) => {
360	    const m = v.main;
361	    const results = m.results.map((r: any) => `${r.at_s}s ${r.origin}: \`${r.text.replace(/\|/g, "\\|").replace(/\n/g, " ⏎ ")}\``).join("<br>");
362	    const mode = v.direct ? `direct worker ${v.worker_is_backgrounded ? "bg" : "fg"}` : `${m.input_mode}${m.busy_main ? " + busy main" : ""}`;
363	    return `| ${v.scenario} | ${mode} |${m.blocked_on_launcher_until_s ?? "-"} | ` +
364	      `${m.worker_end_status} @ ${m.worker_end_s ?? "-"}s | ${results} | ${m.token_reached_main ? m.token_reached_main_in_turn : "no"} | ${m.query_iterator_ended_s} |`;
365	  });
366	  const tokenRows = verdicts.filter((v) => v.main).map((v) => {
367	    const m = v.main;
368	    const chain = v.direct ? `main →${v.outer_requested} worker` : `main →${v.outer_requested} launcher →${v.inner_requested} worker`;
369	    // verdicts written before token_reached_main_at_s existed: take the first result that carries the token
370	    m.token_reached_main_at_s ??= m.results.find((r: any) => TOKEN_RE.test(r.text))?.at_s ?? null;
371	    const how = !m.token_reached_main ? "**NEVER**" : m.token_reached_main_in_turn === "prompt" ? "sync (in the prompt's turn)" : "callback (task-notification turn)";
372	    const before = m.token_reached_main ? (m.token_reached_main_at_s <= m.query_iterator_ended_s ? "yes" : "no") : "no";
373	    return `| ${v.scenario} | ${chain} | ${m.input_mode} | ${m.worker_end_s ?? "-"} | ${how} | ${m.token_reached_main_at_s ?? "-"} | ${m.query_iterator_ended_s} | ${before} |`;
374	  });
375	  const md = [
376	    "## Did the WORKER_TOKEN reach main before the session ended?",
377	    "",
378	    "input `open` = this script kept the session open until background work drained; `string` = one-shot, the CLI alone decides when to end.",
379	    "",
380	    "| scenario | chain (fg = sync, bg = async) | input | worker ended (s) | token reached main | at (s) | session ended (s) | before end |",
381	    "|---|---|---|---|---|---|---|---|",
382	    ...tokenRows,
383	    "",
384	    "## Launcher behaviour",
385	    "",
386	    "| scenario (outer-inner) | launcher bg | worker bg | launcher ended (s) | worker ended (s) | launcher got token | launcher |",
387	    "|---|---|---|---|---|---|---|",
388	    ...launcherRows,
389	    "",
390	    "## Main conversation behaviour",
391	    "",
392	    "| scenario | input | main's Agent call returned (s) | worker | main results (time, turn origin, text) | worker token reached main in | query iterator ended (s) |",
393	    "|---|---|---|---|---|---|---|",
394	    ...mainRows,
395	  ].join("\n");
396	  writeSummary("summary.md", md);
397	  console.log(md);
398	}
399	
400	main().catch((e) => {
401	  console.error(e);
402	  process.exit(1);
403	});
