1	/**
2	 * AskUserQuestion relay through main, foreground only.
3	 *
4	 *   main --Agent (fg)--> clarifier            clarifier draws a secret NONCE (never shown to main) and replies
5	 *                                              QUESTION_FOR_USER: ... / OPTIONS: ...
6	 *   main --AskUserQuestion--> fake user       the test answers "French" (SDK: canUseTool; CLI: PreToolUse hook)
7	 *   main --SendMessage(to=agentId)--> clarifier   same instance resumed; it waits 15 s, then replies
8	 *                                              CLARIFIER_FINAL: <greeting> NONCE=<n>
9	 *
10	 * Only the original instance knows the nonce, so a matching nonce in the final reply proves the SAME instance
11	 * (same context) was resumed. Foreground is forced only by env: CLAUDE_CODE_DISABLE_BACKGROUND_TASKS=1,
12	 * CLAUDE_CODE_FORK_SUBAGENT=0. No hook changes Agent or SendMessage input.
13	 *
14	 * Usage:  npx tsx investigations/askuserquestion-relay/askuser.ts [sdk|cli|both=both] [runs=1]
15	 */
16	import { query, type HookCallback, type SDKMessage } from "@anthropic-ai/claude-agent-sdk";
17	import { spawn } from "node:child_process";
18	import { mkdirSync, writeFileSync, appendFileSync, readFileSync, existsSync, readdirSync } from "node:fs";
19	import { homedir } from "node:os";
20	import { join } from "node:path";
21	import { createInterface } from "node:readline";
22	import { ISOLATION_ENV, ISOLATION_SETTINGS, SESSIONS_DIR, RESULTS_DIR, LIB_DIR, loadPrompt, beginRun, recordClaudeVersion, writeSummary } from "../../lib/claude-home.mjs";
23	
24	const DRIVER = (process.argv[2] ?? "both") as "sdk" | "cli" | "both";
25	const RUNS = Number(process.argv[3] ?? 1);
26	const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
27	const PROJECT_DIR = SESSIONS_DIR;
28	const FAKE_ANSWER = "French";
29	const NONCE_RE = /NONCE=(\d+|UNKNOWN)/;
30	
31	const MAIN_PROMPT = loadPrompt("askuser-main");
