33	function cleanEnv(): Record<string, string> {
34	  const env: Record<string, string> = {};
35	  for (const [k, v] of Object.entries(process.env)) if (!/^CLAUDE/.test(k) && v !== undefined) env[k] = v;
36	  return { ...env, ...ISOLATION_ENV, CLAUDE_CODE_DISABLE_BACKGROUND_TASKS: "1", CLAUDE_CODE_FORK_SUBAGENT: "0" };
37	}
