39	function pickAnswers(questions: any[]) {
40	  const answers: Record<string, string> = {};
41	  for (const q of questions) answers[q.question] = (q.options.find((o: any) => new RegExp(FAKE_ANSWER, "i").test(o.label)) ?? q.options[0]).label;
42	  return answers;
43	}
