45	type Logger = (src: string, event: string, data?: Record<string, unknown>) => void;
46	function makeLogger(name: string, t0: number): Logger {
47	  const logPath = join(RESULTS_DIR, `${name}.jsonl`);
48	  writeFileSync(logPath, "");
49	  return (src, event, data = {}) => {
50	    const t = Date.now() - t0;
51	    appendFileSync(logPath, JSON.stringify({ t, src, event, ...data }) + "\n");
52	    const brief = Object.entries(data)
53	      .map(([k, v]) => { const s = typeof v === "string" ? v : JSON.stringify(v); return `${k}=${JSON.stringify(s.length > 120 ? s.slice(0, 120) + "…" : s)}`; })
54	      .join(" ");
55	    console.log(`[${name}] ${(t / 1000).toFixed(1).padStart(6)}s  ${src.padEnd(6)} ${event.padEnd(22)} ${brief}`);
56	  };
57	}
