59	/** Stream events are the same shape for SDK messages and `claude -p` stream-json lines. */
60	function makeStreamHandler(log: Logger, t0: number, st: StreamState) {
61	  return (a: any) => {
62	    if (a.type === "system" && a.subtype === "init") {
63	      st.sessionId = a.session_id; st.cliVersion = a.claude_code_version;
64	      log("stream", "system:init", { cli: a.claude_code_version, model: a.model, session: a.session_id,
65	        has_AskUserQuestion: a.tools?.includes("AskUserQuestion"), has_SendMessage: a.tools?.includes("SendMessage") });
66	      st.tools = a.tools;
67	    } else if (a.type === "system" && a.subtype === "task_started") {
68	      st.taskStarted.push({ t: Date.now() - t0, task_id: a.task_id, agent: a.subagent_type, is_backgrounded: a.is_backgrounded });
69	      log("stream", "task_started", { agent: a.subagent_type, task_id: a.task_id, is_backgrounded: a.is_backgrounded });
70	    } else if (a.type === "system" && a.subtype === "task_notification") {
71	      log("stream", "task_notification", { task_id: a.task_id, status: a.status, summary: a.summary });
72	    } else if (a.type === "assistant" && !a.parent_tool_use_id) {
73	      for (const b of a.message?.content ?? []) {
74	        if (b.type === "tool_use") log("stream", "main tool_use", { name: b.name, input: b.input });
75	        else if (b.type === "text") log("stream", "main text", { text: b.text });
76	      }
77	    } else if (a.type === "user" && !a.parent_tool_use_id) {
78	      const content = Array.isArray(a.message?.content) ? a.message.content : [];
79	      for (const b of content.filter((b: any) => b.type === "tool_result"))
80	        log("stream", "main tool_result", { text: typeof b.content === "string" ? b.content : JSON.stringify(b.content) });
81	      if (a.origin?.kind) log("stream", "main user", { origin: a.origin.kind });
82	    } else if (a.type === "result") {
83	      st.results.push({ t: Date.now() - t0, origin: a.origin?.kind ?? "prompt", text: a.result ?? "" });
84	      log("stream", "RESULT", { origin: a.origin?.kind ?? "prompt", num_turns: a.num_turns, result: a.result, stop_reason: a.stop_reason, cost: a.total_cost_usd });
85	    }
86	  };
87	}
