97	async function runSdk(name: string, t0: number, log: Logger, st: StreamState) {
98	  const obs: HookCallback = async (input: any) => {
99	    const ev = input.hook_event_name;
100	    const who = input.agent_id ? `${input.agent_type}:${input.agent_id}` : "main";
101	    if (ev === "SubagentStart" || ev === "SubagentStop") log("hook", ev, { agent: input.agent_type, agent_id: input.agent_id, last: input.last_assistant_message });
102	    else log("hook", `${ev}(${input.tool_name})`, { caller: who });
103	    return {};
104	  };
105	  const q = query({
106	    prompt: MAIN_PROMPT, // one-shot
107	    options: {
108	      cwd: process.cwd(),
109	      model: "sonnet",
110	      settingSources: ["project"],
111	      settings: ISOLATION_SETTINGS,
112	      allowedTools: ["Agent", "Bash", "SendMessage"],
113	      env: cleanEnv(),
114	      // the fake user: documented SDK way to answer AskUserQuestion
115	      canUseTool: async (toolName, input) => {
116	        if (toolName === "AskUserQuestion") {
117	          const answers = pickAnswers((input as any).questions ?? []);
118	          log("fake-user", "answers", { answers });
119	          return { behavior: "allow", updatedInput: { questions: (input as any).questions, answers } };
120	        }
121	        log("canUseTool", "unexpected", { toolName });
122	        return { behavior: "allow", updatedInput: input };
123	      },
124	      hooks: {
125	        PreToolUse: [{ hooks: [obs] }],
126	        PostToolUse: [{ hooks: [obs] }],
127	        SubagentStart: [{ hooks: [obs] }],
128	        SubagentStop: [{ hooks: [obs] }],
129	      },
130	    },
131	  });
132	  const handle = makeStreamHandler(log, t0, st);
133	  const timeout = setTimeout(() => { log("runner", "HARD_TIMEOUT"); q.close(); }, 6 * 60_000);
134	  for await (const m of q as AsyncIterable<SDKMessage>) handle(m);
135	  clearTimeout(timeout);
136	}
