138	async function runCli(name: string, t0: number, log: Logger, st: StreamState) {
139	  const hookLog = join(RESULTS_DIR, `${name}.hooks.jsonl`);
140	  const settingsPath = join(RESULTS_DIR, `${name}.settings.json`);
141	  writeFileSync(hookLog, "");
142	  const node = (script: string, ...args: string[]) =>
143	    `node "${script.replace(/\\/g, "/")}" ${args.map((a) => `"${a.replace(/\\/g, "/")}"`).join(" ")}`;
144	  const logger = [{ hooks: [{ type: "command", command: node(join(LIB_DIR, "hook-log.mjs"), hookLog) }] }];
145	  writeFileSync(settingsPath, JSON.stringify({
146	    ...ISOLATION_SETTINGS,
147	    hooks: {
148	      PreToolUse: [
