190	const textOf = (c: any): string =>
191	  typeof c === "string" ? c : Array.isArray(c) ? c.map((b: any) => (b.type === "text" ? b.text : b.type === "tool_result" ? textOf(b.content) : "")).join("\n") : "";
192	const readJsonl = (p: string) => readFileSync(p, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
