194	function analyse(sessionId: string, t0: number) {
195	  const mainPath = join(PROJECT_DIR, `${sessionId}.jsonl`);
196	  const rel = (ts: string) => (Date.parse(ts) - t0) / 1000;
197	  const entries = readJsonl(mainPath).filter((e) => !e.isSidechain);
198	  const calls: { id: string; name: string; input: any; use_s: number; result_s?: number; result?: string }[] = [];
199	  const notifications: { at_s: number; text: string }[] = [];
200	  const answers: { at_s: number; text: string }[] = [];
201	  for (const e of entries) {
202	    if (e.type === "assistant") {
203	      for (const b of e.message?.content ?? []) {
204	        if (b.type === "tool_use") calls.push({ id: b.id, name: b.name, input: b.input, use_s: rel(e.timestamp) });
205	        if (b.type === "text" && b.text.trim()) answers.push({ at_s: rel(e.timestamp), text: b.text });
206	      }
207	    } else if (e.type === "user") {
208	      const c = e.message?.content;
209	      if (Array.isArray(c)) for (const b of c) if (b.type === "tool_result") {
210	        const call = calls.find((x) => x.id === b.tool_use_id);
211	        if (call) { call.result_s = rel(e.timestamp); call.result = textOf(b.content); }
212	      }
213	      const t = textOf(c);
214	      if (t.includes("<task-notification>")) notifications.push({ at_s: rel(e.timestamp), text: t });
215	    }
216	  }
217	  const subDir = join(PROJECT_DIR, sessionId, "subagents");
218	  const subagents = existsSync(subDir)
219	    ? readdirSync(subDir).filter((f) => /^agent-.*\.jsonl$/.test(f)).map((f) => {
220	        const es = readJsonl(join(subDir, f));
221	        const prompts = es.filter((e) => e.type === "user" && !(Array.isArray(e.message?.content) && e.message.content.some((b: any) => b.type === "tool_result")))
222	          .map((e) => ({ at_s: rel(e.timestamp), text: textOf(e.message.content).slice(0, 200) }));
223	        const bashOutputs = es.filter((e) => e.type === "user" && Array.isArray(e.message?.content))
224	          .flatMap((e) => e.message.content.filter((b: any) => b.type === "tool_result").map((b: any) => ({ at_s: rel(e.timestamp), text: textOf(b.content).trim() })));
225	        const finals = es.filter((e) => e.type === "assistant").flatMap((e) => (e.message?.content ?? []).filter((b: any) => b.type === "text").map((b: any) => ({ at_s: rel(e.timestamp), text: b.text })));
226	        return { file: f, agent_id: f.replace(/^agent-|\.jsonl$/g, ""), prompts, bash_outputs: bashOutputs, assistant_texts: finals };
227	      })
228	    : [];
229	  return { mainPath, calls, notifications, answers, subagents };
230	}
