234	async function runOnce(driver: "sdk" | "cli", run: number) {
235	  const name = `askuser-${driver}-run${run}`;
236	  const t0 = Date.now();
237	  const log = makeLogger(name, t0);
238	  const st: StreamState = { taskStarted: [], results: [] };
239	  await (driver === "sdk" ? runSdk : runCli)(name, t0, log, st);
240	  recordClaudeVersion(driver, st.cliVersion);
241	  const sessionEnd = (Date.now() - t0) / 1000;
242	  if (!st.sessionId) throw new Error(`${name}: no session id`);
243	  const tr = analyse(st.sessionId, t0);
244	
245	  const agentCalls = tr.calls.filter((c) => c.name === "Agent");
246	  const askCalls = tr.calls.filter((c) => c.name === "AskUserQuestion");
247	  const sendCalls = tr.calls.filter((c) => c.name === "SendMessage");
248	  const firstAgent = agentCalls[0];
249	  const agentId = firstAgent?.result?.match(/agentId:\s*([\w-]+)/)?.[1];
250	  const send = sendCalls[0];
251	  const clarifierTranscripts = tr.subagents.filter((s) => s.prompts.some((p) => /greeting|USER_ANSWER/.test(p.text)));
252	  const own = tr.subagents.find((s) => s.agent_id === agentId);
253	  const firstNonce = own?.bash_outputs.map((b) => b.text.match(/NONCE=(\d+)/)?.[1]).find(Boolean);
254	  const finalFromSub = own?.assistant_texts.map((x) => x.text).filter((x) => x.includes("CLARIFIER_FINAL")).pop();
255	  const finalNonce = finalFromSub?.match(NONCE_RE)?.[1];
256	  const clarifierStarts = st.taskStarted.filter((x) => x.agent === "clarifier" || x.task_id === agentId);
257	  const lastResult = st.results[st.results.length - 1];
258	  const call = (c?: (typeof tr.calls)[number]) => c && { name: c.name, input: c.input, use_s: c.use_s, result_s: c.result_s, blocked_s: c.result_s !== undefined ? +(c.result_s - c.use_s).toFixed(2) : null, result: c.result };
259	
260	  const verdict = {
261	    run: name,
262	    driver: driver === "sdk" ? "Agent SDK query()" : "claude -p (no SDK)",
263	    cli_version: st.cliVersion ?? null,
264	    env: { CLAUDE_CODE_DISABLE_BACKGROUND_TASKS: "1", CLAUDE_CODE_FORK_SUBAGENT: "0" },
265	    fake_user: driver === "sdk" ? `canUseTool answers "${FAKE_ANSWER}"` : `PreToolUse hook fake-user.mjs answers "${FAKE_ANSWER}"`,
266	    main_has_AskUserQuestion: st.tools?.includes("AskUserQuestion") ?? null,
267	    main_has_SendMessage: st.tools?.includes("SendMessage") ?? null,
268	    main_tool_sequence: tr.calls.map((c) => c.name),
269	    agent_call: call(firstAgent),
270	    agent_id: agentId ?? null,
271	    check1_subagent_asked_question: !!firstAgent?.result?.includes("QUESTION_FOR_USER"),
272	    ask_call: call(askCalls[0]),
273	    check2_main_asked_user_and_got_fake_answer: !!askCalls[0]?.result?.includes(FAKE_ANSWER),
274	    send_call: call(send),
275	    check3_sendmessage_to_same_id: !!send && !!agentId && send.input?.to === agentId,
276	    agent_calls_total: agentCalls.length,
277	    clarifier_transcripts: clarifierTranscripts.map((s) => s.file),
278	    first_run_nonce: firstNonce ?? null,
279	    resumed_run_final: finalFromSub ?? null,
280	    check4_same_instance: agentCalls.length === 1 && clarifierTranscripts.length === 1 && !!firstNonce && finalNonce === firstNonce,
281	    clarifier_task_started: clarifierStarts.map((x) => ({ at_s: x.t / 1000, task_id: x.task_id, is_backgrounded: x.is_backgrounded })),
282	    main_task_notification_turns: tr.notifications.map((n) => ({ at_s: n.at_s, text: n.text.slice(0, 300) })),
283	    // foreground = main's SendMessage call blocks until the resumed run ends and returns its final report inline,
284	    // with no later task-notification turn. The stream's is_backgrounded flag is recorded but not used: see README.
285	    resumed_run_ended_s: own?.assistant_texts.filter((x) => x.text.includes("CLARIFIER_FINAL")).pop()?.at_s ?? null,
286	    resumed_run_is_backgrounded_flag: clarifierStarts[1]?.is_backgrounded ?? null,
287	    check5_resume_was_foreground:
288	      !!send?.result?.includes("CLARIFIER_FINAL") && tr.notifications.length === 0 && send?.result_s !== undefined &&
289	      send.result_s >= (own?.assistant_texts.filter((x) => x.text.includes("CLARIFIER_FINAL")).pop()?.at_s ?? Infinity),
290	    results: st.results.map((r) => ({ at_s: r.t / 1000, origin: r.origin, text: r.text })),
291	    check6_main_final_has_nonce: !!lastResult && !!firstNonce && lastResult.text.includes(`NONCE=${firstNonce}`),
292	    subagent_transcripts: tr.subagents,
293	    session_ended_s: sessionEnd,
294	    transcript: tr.mainPath,
295	  };
296	  writeFileSync(join(RESULTS_DIR, `${name}.verdict.json`), JSON.stringify(verdict, null, 2));
297	  console.log(`\n[${name}] VERDICT\n${JSON.stringify({ ...verdict, subagent_transcripts: undefined }, null, 2)}\n`);
298	  return verdict;
299	}
