1	/**
2	 * Independent token counts for the pieces of a request, with POST /v1/messages/count_tokens (free, no model call),
3	 * authenticated with the run's OAuth token (Bearer + anthropic-beta: oauth-2025-04-20; there is no API key).
4	 * Only text taken from the session files of an attribution-cli.ts run (system blocks, tool definitions, messages)
5	 * is sent. It answers: do the counts of the requests reconstructed from the session file match the real usage of each
6	 * call, and what do the single pieces count?
7	 *
8	 * Usage:  npx tsx investigations/prompt-token-attribution/count-tokens.ts [<attribution-cli run folder>]
9	 */
10	import { readFileSync, readdirSync, existsSync, writeFileSync } from "node:fs";
11	import { join } from "node:path";
12	import { ISOLATION_ENV, INVESTIGATION_DIR, RESULTS_DIR, beginRun, writeSummary } from "../../lib/claude-home.mjs";
13	
14	const MODEL = "claude-haiku-5-5";
15	const readJsonl = (f: string): any[] => readFileSync(f, "utf8").split("\n").filter(Boolean).flatMap((l) => { try { return [JSON.parse(l)]; } catch { return []; } });
16	const table = (head: string[], rows: (string | number)[][]) => `| ${head.join(" | ")} |\n|${head.map(() => "---").join("|")}|\n${rows.map((r) => `| ${r.join(" | ")} |`).join("\n")}\n`;
17	let token = "";
18	const BETAS = process.env.COUNT_BETAS ?? "oauth-2025-04-20,advisor-tool-2026-03-01,inline-tools-2026-09-15,advanced-tool-use-2025-11-20,claude-code-20250219";
19	let nCalls = 0;
20	const log: string[] = [];
21	
22	async function count(body: { system?: any; tools?: any; messages: any[] }): Promise<number> {
23	  nCalls++;
24	  for (let attempt = 0; attempt < 4; attempt++) {
25	    const res = await fetch("https://api.anthropic.com/v1/messages/count_tokens", {
26	      method: "POST",
27	      headers: { Authorization: `Bearer ${token}`, "anthropic-beta": BETAS, "anthropic-version": "2023-06-01", "content-type": "application/json" },
28	      body: JSON.stringify({ model: MODEL, ...body }),
29	    });
30	    const text = await res.text();
31	    if (res.status === 429) { await new Promise((r) => setTimeout(r, 2000 * (attempt + 1))); continue; }
32	    if (!res.ok) throw new Error(`count_tokens ${res.status}: ${text.slice(0, 300)}`);
33	    return JSON.parse(text).input_tokens;
34	  }
35	  throw new Error("count_tokens: rate limited");
36	}
37	const clean = (o: any) => JSON.parse(JSON.stringify(o, (k, v) => (k === "cache_control" ? undefined : v)));
38	const X = [{ role: "user", content: "x" }];
39	
40	// messages of the session up to (and excluding) the (k+1)th API call, rebuilt from the session entries
41	function sessionMessages(file: string) {
42	  const L = readJsonl(file);
43	  const first = L.find((e) => e.type === "api-request-blob" && e.message.role === "user");
44	  const blobs = L.filter((e) => e.type === "api-request-blob");
45	  const sysBlobs = blobs.filter((b) => b.message.role === "system").map((b) => b.message.content.map((c: any) => c.text).join("\n"));
46	  const msgs: any[] = [{ role: "user", content: clean(first.message.content) }];
47	  const seen = new Map<string, any>();
48	  for (const e of L) {
49	    if (e.type === "assistant" && e.message?.id && e.message.model !== "<synthetic>") {
50	      if (!seen.has(e.message.id)) { const m = { role: "assistant", content: [] as any[] }; seen.set(e.message.id, m); msgs.push(m); }
51	      seen.get(e.message.id).content.push(...clean(e.message.content).filter((b: any) => b.type !== "thinking"));
52	    } else if (e.type === "user" && e.message?.role === "user" && Array.isArray(e.message.content) && e.message.content.some((b: any) => b.type === "tool_result")) {
53	      const prev = msgs[msgs.length - 1];
54	      if (prev && prev.role === "user" && prev !== msgs[0] && prev.content.every((b: any) => b.type === "tool_result")) prev.content.push(...clean(e.message.content));
55	      else msgs.push({ role: "user", content: clean(e.message.content) });
56	    }
57	  }
58	  const shapes = L.filter((e) => e.type === "api-request-shape");
59	  return { msgs, sysBlobs, shape: shapes[0].shape, lastShape: shapes[shapes.length - 1].shape, attachments: L.filter((e) => e.attachment).map((e) => e.attachment) };
60	}
