62	async function main() {
63	  beginRun();
64	  token = JSON.parse(readFileSync(join(ISOLATION_ENV.CLAUDE_CONFIG_DIR, ".credentials.json"), "utf8")).claudeAiOauth?.accessToken;
65	  const dirs = readdirSync(join(INVESTIGATION_DIR, "results")).filter((d) => d.endsWith("-attribution-cli") && existsSync(join(INVESTIGATION_DIR, "results", d, "runs.json"))).sort();
66	  const nRuns = (d: string) => JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", d, "runs.json"), "utf8")).runs.length;
67	  const dir = process.argv[2] ?? [...dirs].sort((p, q) => nRuns(p) - nRuns(q) || p.localeCompare(q)).pop()!; // default: the folder with the most runs (the full batch)
68	  const runs: any[] = JSON.parse(readFileSync(join(INVESTIGATION_DIR, "results", dir, "runs.json"), "utf8")).runs;
69	  const P = (c: any) => { const u = c.start ?? c.assistant[0]; return u.input + u.cache_creation + u.cache_read; };
70	  const made = (p: any) => p.calls.filter((c: any) => c.model !== "<synthetic>" && (c.start || c.assistant.length));
71	  let md = `Source: results/${dir}/runs.json and its session files. count_tokens model ${MODEL}.\n\n`;
72	
73	  // ---- A. reconstructed request vs real usage, per call ----
74	  md += `## A. Request rebuilt from the session file: count_tokens vs real prompt size\n\n`;
75	  md += `System = api-request-shape.system, tools = api-request-shape.tools, messages = first user blob + the session's assistant / tool_result entries (thinking blocks left out). The two mid-conversation system blobs (Environment, total_tokens) are counted separately and added.\n\n`;
76	  const rows: (string | number)[][] = [];
77	  for (const name of ["base", "user-w200", "user-w800", "claudemd-w800", "skills-listing-3", "pre-default", "pre-tools-none", "pre-tools-bash", "pre-floor", "tool-tiny", "tool-w100", "tool-w800", "skill-invoke-w800"]) {
78	    const r = runs.find((x) => x.name === `${name}-partial-r1`); if (!r) continue;
79	    const p = r.procs[0]; const { msgs, sysBlobs, shape } = sessionMessages(p.sessionFile);
80	    const cs = made(p);
