82	    const sysBlobTokens = sysBlobs.length ? (await count({ messages: [{ role: "user", content: sysBlobs.join("\n") }] })) - (await count({ messages: X })) : 0;
83	    // call k sees messages up to the k-th assistant-free prefix: call 1 = msgs[0]; call 2 = msgs[0..2]
84	    for (let k = 0; k < cs.length; k++) {
85	      const upto = msgs.slice(0, 1 + 2 * k);
86	      const c = await count({ system: sys, ...(tools ? { tools } : {}), messages: upto });
87	      const real = P(cs[k]);
88	      rows.push([name, `call ${k + 1}`, real, c, c + sysBlobTokens, real - c - sysBlobTokens]);
89	    }
90	  }
91	  md += table(["scenario", "call", "real prompt size (usage)", "count_tokens of rebuilt request", "+ system blobs", "real − counted"], rows);
92	  md += `\nThe residual is what the rebuilt request lacks (the deferred-tool list and connector text that are not in the shape, framing). If it is the same in every scenario, differences of counts equal differences of usage.\n\n`;
93	
94	  // ---- B. blocks counted alone ----
95	  md += `## B. Blocks counted alone (count with the block − count of a one-word message)\n\n`;
96	  const ref = runs.find((x) => x.name === "pre-default-partial-r1")!.procs[0];
97	  const { msgs: m0, sysBlobs, shape } = sessionMessages(ref.sessionFile);
98	  const base = await count({ messages: X });
99	  const brows: (string | number)[][] = [];
100	  const sysBlocks = clean(shape.system) as any[];
101	  for (let i = 0; i < sysBlocks.length; i++) brows.push([`system block ${i + 1}`, sysBlocks[i].text.length, (await count({ system: [sysBlocks[i]], messages: X })) - base]);
102	  const tools = clean(shape.tools) as any[];
103	  for (const t of tools) brows.push([`tool ${t.name}`, JSON.stringify(t).length, (await count({ tools: [{ ...t, defer_loading: false }], messages: X })) - base]);
104	  const allTools = (await count({ tools, messages: X })) - base;
105	  brows.push(["all 17 inline tools together", JSON.stringify(tools).length, allTools]);
106	  const allSys = (await count({ system: sysBlocks, messages: X })) - base;
107	  brows.push(["all system blocks together", sysBlocks.reduce((s, b) => s + b.text.length, 0), allSys]);
108	  for (let i = 0; i < m0[0].content.length; i++) brows.push([`first user message, block ${i + 1}`, m0[0].content[i].text.length, (await count({ messages: [{ role: "user", content: [m0[0].content[i]] }] })) - base]);
109	  for (let i = 0; i < sysBlobs.length; i++) brows.push([`system-role blob ${i + 1}`, sysBlobs[i].length, (await count({ messages: [{ role: "user", content: sysBlobs[i] }] })) - base]);
110	  md += table(["block", "chars", "tokens"], brows);
111	  md += `\nTokens per char: system blocks ${(allSys / sysBlocks.reduce((s, b) => s + b.text.length, 0)).toFixed(3)}, inline tools ${(allTools / JSON.stringify(tools).length).toFixed(3)}.\n\n`;
112	  md += `Sum of the counted pieces: system ${allSys} + tools ${allTools} + user blocks + blobs, against the real first call of pre-default.\n\n`;
113	
114	  // ---- C. tool_result / assistant / user blocks ----
115	  md += `## C. Messages of a tool round counted alone (count of the conversation prefix, same system and tools)\n\n`;
116	  const crows: (string | number)[][] = [];
