1	/**
2	 * Shared logic of usage-sdk.ts and usage-cli.ts: the plan-usage readers, the fixed workload conversation and the
3	 * scenarios. A driver picks the mode ("sdk" or "cli"); this module does the rest.
4	 *
5	 * Readers (every reading is stored raw in <scenario>.jsonl and summarised in <scenario>.verdict.json):
6	 *   sdk  query.usage_EXPERIMENTAL_MAY_CHANGE_DO_NOT_RELY_ON_THIS_API_YET({ skipBehaviors: true }) on a query whose
7	 *        streaming input never sends a prompt (so the reading itself makes no model call).
8	 *   cli  `claude -p "/usage"` (stream-json): whatever the slash command prints in headless mode.
9	 *   ref  GET https://api.anthropic.com/api/oauth/usage with the run's OAuth token. Not a Claude Code channel: the
10	 *        reference ("ground truth") the Claude Code channels are compared with.
11	 * During the workload, every rate_limit_event of the stream is kept (channel B), and afterwards the session
12	 * transcripts are scanned for anything rate-limit related (channel D).
13	 */
14	import { query } from "@anthropic-ai/claude-agent-sdk";
15	import { spawn } from "node:child_process";
16	import { appendFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
17	import { homedir } from "node:os";
18	import { join } from "node:path";
19	import { createInterface } from "node:readline";
20	import { CONFIG_DIR, ISOLATION_ENV, ISOLATION_SETTINGS, RESULTS_DIR, SESSIONS_DIR, loadPrompt, recordClaudeVersion } from "../../lib/claude-home.mjs";
21	
22	export type Mode = "sdk" | "cli";
23	export type ScenarioName = "baseline" | "before-after" | "after-only";
24	
25	const CLAUDE = join(homedir(), ".local", "bin", "claude.exe");
26	const MODEL = "opus";
27	const TOPICS = [
28	  "the history of lighthouses and the people who kept them",
29	  "how medieval cathedrals were engineered without modern mathematics",
30	  "the economics and logistics of the spice trade across the Indian Ocean",
31	];
32	/**
33	 * Reads after the workload, in seconds after it ends (USAGE_SETTLE="0,30,90" to see whether the endpoint lags).
34	 * Default one read: the usage endpoint answers 429 with a ~1 h retry-after once a bearer has asked too often.
35	 */
36	const SETTLE_S = (process.env.USAGE_SETTLE ?? "0").split(",").map(Number);
37	
38	const cleanEnv = () => ({ ...Object.fromEntries(Object.entries(process.env).filter(([k]) => !/^CLAUDE/.test(k))), ...ISOLATION_ENV }) as NodeJS.ProcessEnv;
39	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
40	
41	let LOG = "";
42	let T0 = 0;
43	function log(event: string, data: Record<string, unknown> = {}) {
44	  const t = Date.now() - T0;
45	  appendFileSync(LOG, JSON.stringify({ t, event, ...data }) + "\n");
46	  console.log(`${(t / 1000).toFixed(1).padStart(7)}s  ${event.padEnd(22)} ${JSON.stringify(data).slice(0, 220)}`);
47	}
48	
49	// ---------------------------------------------------------------- readers
50	
51	/** Normalised view of a reading: utilization per window (0-100) and its reset time. */
52	type Windows = Record<string, { utilization: number | null; resets_at: string | null }>;
53	type Reading = { channel: "sdk" | "cli" | "probe" | "ref"; label: string; t: number; ok: boolean; windows: Windows | null; error?: string; raw?: unknown; model_calls?: unknown; ground_truth_only?: boolean };
54	
55	function windowsFromRateLimits(rl: any): Windows | null {
56	  if (!rl || typeof rl !== "object") return null;
57	  const out: Windows = {};
58	  for (const [k, v] of Object.entries<any>(rl)) {
59	    if (k === "model_scoped" && Array.isArray(v)) for (const m of v) out[`model:${m.display_name}`] = { utilization: m.utilization ?? null, resets_at: m.resets_at ?? null };
60	    else if (k === "extra_usage") { if (v) out.extra_usage = { utilization: v.utilization ?? null, resets_at: null }; }
61	    else if (v && typeof v === "object" && "utilization" in v) out[k] = { utilization: v.utilization ?? null, resets_at: v.resets_at ?? null };
62	  }
63	  return out;
64	}
65	
66	async function readSdk(label: string): Promise<Reading> {
67	  const t = Date.now() - T0;
68	  let release!: () => void;
69	  const done = new Promise<void>((r) => (release = r));
70	  async function* noPrompt() { await done; }
71	  // The debug log shows the CLI's own fetchUtilization lines: why rate_limits is null when it is.
72	  const debugFile = join(RESULTS_DIR, `sdk-read-${label.replace(/[^\w+-]/g, "_")}.debug.log`);
73	  const q = query({ prompt: noPrompt() as any, options: { cwd: process.cwd(), settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(), permissionMode: "dontAsk", allowedTools: [], debugFile } });
74	  const drain = (async () => { try { for await (const m of q as AsyncIterable<any>) if (m.type === "system" && m.subtype === "init") recordClaudeVersion("sdk", m.claude_code_version); } catch { /* closed */ } })();
75	  let r: Reading;
76	  try {
77	    const raw: any = await Promise.race([
78	      (q as any).usage_EXPERIMENTAL_MAY_CHANGE_DO_NOT_RELY_ON_THIS_API_YET({ skipBehaviors: true }),
79	      sleep(60_000).then(() => { throw new Error("timeout 60s"); }),
80	    ]);
81	    r = { channel: "sdk", label, t, ok: !!raw?.rate_limits_available, windows: windowsFromRateLimits(raw?.rate_limits), raw, model_calls: raw?.session?.model_usage };
82	  } catch (e: any) {
83	    r = { channel: "sdk", label, t, ok: false, windows: null, error: String(e?.message ?? e) };
84	  }
85	  release(); q.close(); await Promise.race([drain, sleep(5000)]);
86	  try { (r as any).debug_usage_lines = readFileSync(debugFile, "utf8").split("\n").filter((l) => /utilization|oauth\/usage|usage endpoint|429|rate.?limit/i.test(l)).map((l) => l.slice(0, 400)); } catch { /* no debug file */ }
87	  log(`read:sdk:${label}`, r as any);
88	  return r;
89	}
90	
91	async function readCli(label: string): Promise<Reading> {
92	  const t = Date.now() - T0;
93	  const settingsPath = join(RESULTS_DIR, "cli-read.settings.json");
94	  if (!existsSync(settingsPath)) writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
95	  const events: any[] = [];
96	  const child = spawn(CLAUDE, ["-p", "/usage", "--output-format", "stream-json", "--verbose", "--setting-sources", "project", "--settings", settingsPath, "--permission-mode", "dontAsk"],
97	    { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
98	  child.stdin.end();
99	  let stderr = "";
100	  child.stderr.on("data", (d) => (stderr += d));
101	  createInterface({ input: child.stdout }).on("line", (l) => { try { events.push(JSON.parse(l)); } catch { /* not json */ } });
102	  const timer = setTimeout(() => child.kill(), 90_000);
103	  const code = await new Promise((r) => child.on("close", r));
104	  clearTimeout(timer);
105	  const init = events.find((e) => e.type === "system" && e.subtype === "init");
106	  if (init) recordClaudeVersion("cli", init.claude_code_version);
107	  const result = events.find((e) => e.type === "result");
108	  const text = [result?.result, ...events.filter((e) => e.type === "system" && e.subtype !== "init").map((e) => JSON.stringify(e))].filter(Boolean).join("\n");
109	  const windows = parseUsageText(text);
110	  const r: Reading = { channel: "cli", label, t, ok: !!windows && Object.keys(windows).length > 0, windows,
111	    raw: { exit: code, result: result?.result ?? null, result_subtype: result?.subtype ?? null, num_turns: result?.num_turns, event_types: events.map((e) => `${e.type}${e.subtype ? ":" + e.subtype : ""}`), stderr: stderr.trim().slice(0, 1000) || undefined },
112	    model_calls: result?.modelUsage ?? null };
113	  log(`read:cli:${label}`, r as any);
114	  return r;
115	}
116	
117	/** Best effort: "<label> ... NN% used" lines of the /usage text. */
118	function parseUsageText(text: string): Windows | null {
119	  if (!text) return null;
120	  const out: Windows = {};
121	  const lines = text.split(/\r?\n/);
122	  lines.forEach((line, i) => {
123	    const m = line.match(/(\d+(?:\.\d+)?)\s*%\s*used/i);
124	    if (!m) return;
125	    const label = (line.replace(m[0], "").replace(/[█▌▏░▒▓\-|]+/g, "").trim() || lines[i - 1]?.trim() || `row${i}`).slice(0, 60);
126	    out[label] = { utilization: Number(m[1]), resets_at: (lines[i + 1]?.match(/reset[^\n]*/i)?.[0] ?? null) };
127	  });
128	  return Object.keys(out).length ? out : null;
129	}
130	
131	async function readRef(label: string): Promise<Reading> {
132	  const t = Date.now() - T0;
133	  let r: Reading;
134	  try {
135	    const token = JSON.parse(readFileSync(join(CONFIG_DIR, ".credentials.json"), "utf8")).claudeAiOauth?.accessToken;
136	    const res = await fetch("https://api.anthropic.com/api/oauth/usage", {
137	      headers: { Authorization: `Bearer ${token}`, "anthropic-beta": "oauth-2025-04-20", "Content-Type": "application/json" },
138	    });
139	    const body: any = await res.json().catch(() => null);
140	    r = { channel: "ref", label, t, ok: res.ok, windows: res.ok ? windowsFromRateLimits(body) : null, raw: res.ok ? body : { status: res.status, body } };
141	  } catch (e: any) {
142	    r = { channel: "ref", label, t, ok: false, windows: null, error: String(e?.message ?? e) };
143	  }
144	  log(`read:ref:${label}`, r as any);
145	  return r;
146	}
