148	/**
149	 * Channel B as a reader: a one-word Haiku request in a new session; its rate_limit_event carries
150	 * unifiedWindows.<window>.utilization (a 0-1 fraction, stored here x100 to compare with the 0-100 readers).
151	 */
152	async function readProbe(mode: Mode, label: string): Promise<Reading> {
153	  const t = Date.now() - T0;
154	  const events: any[] = [];
155	  let modelUsage: unknown = null;
156	  const onEvent = (m: any) => {
157	    if (m.type === "system" && m.subtype === "init") recordClaudeVersion(mode, m.claude_code_version);
158	    else if (m.type === "rate_limit_event") events.push(m.rate_limit_info);
159	    else if (m.type === "result") modelUsage = m.modelUsage ?? null;
160	  };
161	  const prompt = "Reply with the single word OK.";
162	  if (mode === "sdk") {
163	    const q = query({ prompt, options: { cwd: process.cwd(), model: "haiku", settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(), permissionMode: "dontAsk", allowedTools: [], maxTurns: 1, persistSession: false } as any });
164	    for await (const m of q as AsyncIterable<any>) onEvent(m);
165	  } else {
166	    const child = spawn(CLAUDE, ["-p", prompt, "--output-format", "stream-json", "--verbose", "--model", "haiku", "--max-turns", "1", "--no-session-persistence",
167	      "--setting-sources", "project", "--settings", JSON.stringify(ISOLATION_SETTINGS), "--permission-mode", "dontAsk"], { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
168	    child.stdin.end();
169	    createInterface({ input: child.stdout }).on("line", (l) => { try { onEvent(JSON.parse(l)); } catch { /* not json */ } });
170	    await new Promise((r) => child.on("close", r));
171	  }
172	  const uw = events.find((e) => e.unifiedWindows)?.unifiedWindows;
173	  const windows: Windows | null = uw ? Object.fromEntries(Object.entries<any>(uw).map(([k, v]) => [k, {
174	    utilization: typeof v.utilization === "number" ? Math.round(v.utilization * 10000) / 100 : null,
175	    resets_at: v.resetsAt ? new Date(v.resetsAt * 1000).toISOString() : null }])) : null;
176	  const r: Reading = { channel: "probe", label, t, ok: !!windows, windows, raw: { rate_limit_events: events }, model_calls: modelUsage };
177	  log(`read:probe:${label}`, r as any);
178	  return r;
179	}
