181	// ---------------------------------------------------------------- workload
182	
183	type Workload = { session_id: string | null; turns: number; rate_limit_events: any[]; model_usage: Record<string, any>; cost_usd: number; output_chars: number; t_start: number; t_end: number; errors: string[] };
184	
185	async function runWorkload(mode: Mode, turns: number): Promise<Workload> {
186	  const w: Workload = { session_id: null, turns, rate_limit_events: [], model_usage: {}, cost_usd: 0, output_chars: 0, t_start: Date.now() - T0, t_end: 0, errors: [] };
187	  const addUsage = (mu: Record<string, any> | undefined) => {
188	    for (const [model, u] of Object.entries(mu ?? {})) {
189	      const acc = (w.model_usage[model] ??= {});
190	      for (const [k, v] of Object.entries<any>(u)) if (typeof v === "number") acc[k] = (acc[k] ?? 0) + v;
191	    }
192	  };
193	  for (let i = 0; i < turns; i++) {
194	    const prompt = loadPrompt("workload", { topic: TOPICS[i % TOPICS.length] });
195	    const onEvent = (m: any) => {
196	      if (m.type === "system" && m.subtype === "init") { w.session_id ??= m.session_id; recordClaudeVersion(mode, m.claude_code_version); log("workload:init", { turn: i + 1, version: m.claude_code_version, model: m.model }); }
197	      else if (m.type === "rate_limit_event") { w.rate_limit_events.push({ t: Date.now() - T0, turn: i + 1, ...m.rate_limit_info }); log("workload:rate_limit_event", m.rate_limit_info); }
198	      else if (m.type === "result") {
199	        w.cost_usd += m.total_cost_usd ?? 0; addUsage(m.modelUsage); w.output_chars += String(m.result ?? "").length;
200	        if (m.is_error) w.errors.push(`${m.subtype}: ${String(m.result ?? "").slice(0, 300)}`);
201	        log("workload:result", { turn: i + 1, subtype: m.subtype, cost: m.total_cost_usd, usage: m.usage });
202	      }
203	    };
204	    if (mode === "sdk") {
205	      const q = query({ prompt, options: { cwd: process.cwd(), model: MODEL, settingSources: ["project"], settings: ISOLATION_SETTINGS, env: cleanEnv(),
206	        permissionMode: "dontAsk", allowedTools: [], maxTurns: 1, ...(w.session_id ? { resume: w.session_id } : {}) } });
207	      for await (const m of q as AsyncIterable<any>) onEvent(m);
208	    } else {
209	      const settingsPath = join(RESULTS_DIR, "workload.settings.json");
210	      if (!existsSync(settingsPath)) writeFileSync(settingsPath, JSON.stringify({ ...ISOLATION_SETTINGS }, null, 2));
211	      const args = ["-p", "--output-format", "stream-json", "--verbose", "--model", MODEL, "--setting-sources", "project", "--settings", settingsPath,
212	        "--permission-mode", "dontAsk", "--max-turns", "1", ...(w.session_id ? ["--resume", w.session_id] : [])];
213	      const child = spawn(CLAUDE, args, { cwd: process.cwd(), env: cleanEnv(), stdio: ["pipe", "pipe", "pipe"] });
214	      child.stdin.end(prompt);
215	      child.stderr.on("data", (d) => log("workload:stderr", { text: String(d).trim().slice(0, 500) }));
216	      const rl = createInterface({ input: child.stdout });
217	      rl.on("line", (l) => { try { onEvent(JSON.parse(l)); } catch { /* not json */ } });
218	      const timer = setTimeout(() => child.kill(), 10 * 60_000);
219	      await new Promise((r) => child.on("close", r));
220	      clearTimeout(timer);
221	    }
222	  }
223	  w.t_end = Date.now() - T0;
224	  return w;
225	}
