227	/** Channel D: every line of the session transcript(s) that mentions rate limits or utilization. */
228	function scanTranscript(sessionId: string | null) {
229	  if (!sessionId) return { transcript: null, hits: [] as string[] };
230	  const path = join(SESSIONS_DIR, `${sessionId}.jsonl`);
231	  if (!existsSync(path)) return { transcript: path, hits: [] };
232	  const lines = readFileSync(path, "utf8").split("\n").filter(Boolean);
233	  const hits = lines.filter((l) => /rate_?limit|utilization|ratelimit/i.test(l)).map((l) => l.slice(0, 600));
234	  const types = [...new Set(lines.map((l) => { try { const e = JSON.parse(l); return `${e.type}${e.subtype ? ":" + e.subtype : ""}`; } catch { return "?"; } }))];
235	  return { transcript: path, lines: lines.length, entry_types: types, hits };
