240	const delta = (a: Reading | undefined, b: Reading | undefined) => {
241	  if (!a?.windows || !b?.windows) return null;
242	  const out: Record<string, number | null> = {};
243	  for (const k of new Set([...Object.keys(a.windows), ...Object.keys(b.windows)])) {
244	    const x = a.windows[k]?.utilization, y = b.windows[k]?.utilization;
245	    out[k] = typeof x === "number" && typeof y === "number" ? Math.round((y - x) * 1000) / 1000 : null;
246	  }
247	  return out;
248	};
