250	export async function runScenario(mode: Mode, name: ScenarioName, turns: number) {
251	  LOG = join(RESULTS_DIR, `${name}.jsonl`);
252	  writeFileSync(LOG, "");
253	  T0 = Date.now();
254	  const read = mode === "sdk" ? readSdk : readCli;
255	  const readings: Reading[] = [];
256	  // The ref channel is opt-in (USAGE_REF=1): it calls the endpoint directly with the copied OAuth token.
257	  const useRef = process.env.USAGE_REF === "1";
258	  /** Every channel at one point in time. In after-only, "before" is read by the probe alone, as ground truth only. */
259	  const readAll = async (label: string, groundTruthOnly = false) => {
260	    if (!groundTruthOnly) readings.push(await read(label));
261	    readings.push({ ...(await readProbe(mode, label)), ground_truth_only: groundTruthOnly });
262	    if (useRef) readings.push({ ...(await readRef(label)), ground_truth_only: groundTruthOnly });
263	  };
264	
265	  let workload: Workload | null = null;
266	  if (name === "baseline") {
267	    // No workload: is each channel available, does a reading itself consume anything, how stable is it?
268	    await readAll("t0"); await sleep(30_000); await readAll("t0+30s");
269	  } else {
270	    await readAll("before", name === "after-only");
271	    workload = await runWorkload(mode, turns);
272	    let last = 0;
273	    for (const s of SETTLE_S) { await sleep((s - last) * 1000); last = s; await readAll(`after+${s}s`); }
274	  }
275	
276	  const pick = (ch: Reading["channel"], label: string) => readings.find((r) => r.channel === ch && r.label === label);
277	  const firstLabel = name === "baseline" ? "t0" : "before";
278	  const lastLabel = name === "baseline" ? "t0+30s" : `after+${SETTLE_S[SETTLE_S.length - 1]}s`;
279	  const channels = [...new Set(readings.map((r) => r.channel))];
280	  // after-only reconstruction of "before": the first rate_limit_event of the workload (state before its first request).
281	  const firstUw = workload?.rate_limit_events.find((e) => e.unifiedWindows)?.unifiedWindows;
282	  const reconstructedBefore: Windows | null = firstUw ? Object.fromEntries(Object.entries<any>(firstUw).map(([k, v]) => [k, { utilization: Math.round(v.utilization * 10000) / 100, resets_at: null }])) : null;
283	  const verdict = {
284	    scenario: name, mode, turns: workload ? turns : 0, model: MODEL, ref_channel_used: useRef,
285	    channel_ok: Object.fromEntries(channels.map((c) => [c, readings.filter((r) => r.channel === c).map((r) => `${r.label}${r.ground_truth_only ? "(gt)" : ""}:${r.ok}`)])),
286	    deltas: Object.fromEntries(channels.map((c) => [c, delta(pick(c, firstLabel), pick(c, lastLabel))])),
287	    delta_ref_by_settle: !useRef || name === "baseline" ? null : Object.fromEntries(SETTLE_S.map((s) => [`after+${s}s`, delta(pick("ref", "before"), pick("ref", `after+${s}s`))])),
288	    reconstructed_before_from_first_event: reconstructedBefore,
289	    probe_before: pick("probe", "before")?.windows ?? null,
290	    reconstruction_matches_probe_before: reconstructedBefore && pick("probe", "before")?.windows
291	      ? Object.entries(reconstructedBefore).every(([k, v]) => pick("probe", "before")!.windows![k]?.utilization === v.utilization) : null,
292	    readings: readings.map((r) => ({ channel: r.channel, label: r.label, ground_truth_only: !!r.ground_truth_only, t: r.t, ok: r.ok, windows: r.windows, error: r.error,
293	      sdk_rate_limits_available: r.channel === "sdk" ? (r.raw as any)?.rate_limits_available : undefined,
294	      sdk_debug_usage_lines: (r as any).debug_usage_lines, cli_usage_text: r.channel === "cli" ? (r.raw as any)?.result : undefined, model_calls: r.model_calls ?? null })),
295	    workload: workload && { session_id: workload.session_id, duration_s: (workload.t_end - workload.t_start) / 1000, cost_usd_equiv: workload.cost_usd, model_usage: workload.model_usage, output_chars: workload.output_chars, errors: workload.errors },
296	    rate_limit_events: workload?.rate_limit_events ?? null,
297	    transcript_scan: workload ? scanTranscript(workload.session_id) : null,
298	  };
299	  writeFileSync(join(RESULTS_DIR, `${name}.verdict.json`), JSON.stringify(verdict, null, 2));
300	  return verdict;
301	}
