303	const fmt = (d: Record<string, number | null> | null) => (d ? Object.entries(d).filter(([, v]) => v !== null).map(([k, v]) => `${k} ${v! >= 0 ? "+" : ""}${v}`).join(", ") || "no numeric window" : "n/a");
304	
305	const win = (w: Windows | null | undefined) => (w ? Object.entries(w).map(([k, v]) => `${k} ${v.utilization ?? "∅"}`).join(", ") : "null");
306	
307	export function renderSummary(mode: Mode, vs: Awaited<ReturnType<typeof runScenario>>[]) {
308	  const ch = mode === "sdk" ? "`usage_EXPERIMENTAL…()`" : "`claude -p /usage`";
309	  return [
310	    `## Plan usage before/after a conversation: ${mode === "sdk" ? "Agent SDK" : "headless `claude -p`"}`,
311	    "",
312	    `Channels: \`${mode}\` = ${ch}; \`probe\` = rate_limit_event.unifiedWindows of a one-word Haiku request (x100); \`ref\` = GET /api/oauth/usage (opt-in).`,
313	    "Values are utilization in percent points (0-100). (gt) = read only as ground truth, not part of the scenario.",
314	    "",
315	    "| scenario | channel | readings (label: windows) | Δ first→last |",
316	    "|---|---|---|---|",
317	    ...vs.flatMap((v) => Object.keys(v.channel_ok).map((c) =>
318	      `| ${v.scenario} | ${c} | ${v.readings.filter((r) => r.channel === c).map((r) => `${r.label}${r.ground_truth_only ? "(gt)" : ""}: ${r.ok ? win(r.windows) : "**not available**"}`).join("<br>")} | ${fmt((v.deltas as any)[c])} |`)),
319	    "",
320	    "| scenario | workload events (turn: 5h / 7d, ×100) | before reconstructed from 1st event | matches probe before | transcript hits | tokens out |",
321	    "|---|---|---|---|---|---|",
322	    ...vs.filter((v) => v.workload).map((v) => `| ${v.scenario} | ${(v.rate_limit_events ?? []).map((e: any) => `t${e.turn}: ${e.unifiedWindows ? `${Math.round(e.unifiedWindows.five_hour?.utilization * 100)} / ${Math.round(e.unifiedWindows.seven_day?.utilization * 100)}` : "no unifiedWindows"}`).join("<br>") || "none"} | ` +
323	      `${win(v.reconstructed_before_from_first_event)} | ${v.reconstruction_matches_probe_before ?? "n/a"} | ${v.transcript_scan?.hits.length ?? "n/a"} | ` +
324	      `${Object.entries(v.workload!.model_usage).map(([m, u]: any) => `${m}: ${u.outputTokens ?? 0}`).join("<br>")} |`),
325	  ].join("\n");
326	}
