1	// Shared harness for the drivers in investigations/<folder>/*.ts: binds a run to its investigation folder and isolates it.
2	// Every driver imports it before anything else.
3	//
4	//   npx tsx investigations/<folder>/<driver>.ts [driver args...]
5	//   node lib/claude-home.mjs investigations/<folder> --check          one cheap claude -p run that prints what it loaded
6	//   node lib/claude-home.mjs investigations/<folder> [claude args...] interactive claude, isolated, credentials synced
7	//
8	// The investigation folder is the folder of the driver script (for the CLI forms above: argv[2], which is then removed).
9	// On import it chdirs there, so `.claude/` and CLAUDE.md of that folder are the fixture each run loads.
10	// - beginRun(): first call in main(). Syncs credentials (below) and creates RESULTS_DIR, results/<YYYY-MM-DD>-<HHMM>-
11	//   <driver>/ inside the folder, with a run.json (args, versions, git commit, hashes of lib/ and of the investigation's
12	//   files) so a run can be tied back to the exact code and fixture.
13	// - recordClaudeVersion(via, version): call it with the claude_code_version of each session's system:init, via "sdk"
14	//   (the SDK runs the Claude Code it bundles) or "cli" (the installed claude). Only the versions that ran are recorded.
15	// - writeSummary(file, markdown): writes a summary into RESULTS_DIR under a header with the run, versions and git commit.
16	// - loadPrompt(name, vars): renders prompts/<name>.md from the folder. {{var}} is replaced, {{#var}}...{{/var}} is kept
17	//   only when var is truthy and {{^var}}...{{/var}} only when it is falsy.
18	// - ISOLATION_ENV: CLAUDE_CONFIG_DIR=<folder>/.claude-home, CLAUDE_CODE_PROJECT_DIR_NAME=sessions, so session logs
19	//   land in <folder>/.claude-home/projects/sessions/<id>.jsonl (+ <id>/subagents/agent-<agentId>.jsonl).
20	// - ISOLATION_SETTINGS (SDK `settings`, or merged into the CLI --settings file): skips the CLAUDE.md / AGENTS.md / rules
21	//   files of every ancestor directory (the repo root CLAUDE.md included) and keeps transcripts from the 30-day sweep.
22	// - Credentials: the run shares the login in ~/.claude/.credentials.json. Whichever copy holds the later expiresAt
23	//   wins and is written over the other, at start and at exit, so a token refreshed during a run goes back home.
24	import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
