69	export function loadPrompt(name, vars = {}) {
70	  const path = join(INVESTIGATION_DIR, "prompts", `${name}.md`);
71	  if (!existsSync(path)) throw new Error(`missing prompt template ${relative(REPO_ROOT, path)}`);
72	  const text = readFileSync(path, "utf8").replace(/\r\n/g, "\n").replace(/\n+$/, "")
73	    .replace(/\{\{([#^])(\w+)\}\}([\s\S]*?)\{\{\/\2\}\}/g, (_, kind, key, body) => (!!vars[key] === (kind === "#") ? body : ""))
74	    .replace(/\{\{(\w+)\}\}/g, (_, key) => {
75	      if (!(key in vars)) throw new Error(`${relative(REPO_ROOT, path)}: no value for {{${key}}}`);
